def analyze_data(data):
    if 'revenue' in data:
        revenue = sum(data['revenue'])
        if revenue > 10000:
            bonus = 500
        else:
            bonus = 100
    else:
        bonus = 0
    if 'expenses' in data and 'revenue' in data:
        net_profit = revenue - sum(data['expenses'])
        if net_profit > 5000:
            reinvestment = net_profit * 0.1
        else:
            reinvestment = 0
    return bonus, reinvestment",

