class OnlineStore:
    def __init__(self, inventory_amount):
        self.inventory_amount = inventory_amount

    def purchase(self, order_quantity):
        if order_quantity > self.inventory_amount:
            return "Order too large, cannot fulfill."
        else:
            self.inventory_amount -= order_quantity
            return "Order fulfilled."

store = OnlineStore(100)
response1 = store.purchase(70)
response2 = store.purchase(40)
