# Python program to apply discounts on products based on membership status and store location tax rates

membership_status = 'gold'  # Possible values: 'none', 'silver', 'gold'
base_prices = {'laptop': 1000, 'smartphone': 800, 'tablet': 600}
tax_rates = {'NY': 0.08, 'CA': 0.09, 'TX': 0.07}
location = 'CA'

def calculate_discount(price, status):
    if status == 'gold':
        return price * 0.10
    elif status == 'silver':
        return price * 0.05
    else:
        return 0

def calculate_tax(price, rate):
    return price * rate

def final_price(base_price, status, location):
    discount = calculate_discount(base_price, status)
    after_discount_price = base_price - discount
    tax = calculate_tax(after_discount_price, tax_rates[location])
    total_price = after_discount_price + tax
    return total_price

# Example calculation
product_prices = {product: final_price(price, membership_status, location) for product, price in base_prices.items()}

