class OfficeUser:
    def __init__(self, name):
        self.name = name
        self.active_project = None
        self.coffee_access = False

    def assign_project(self, project):
        self.active_project = project
        self.update_coffee_access()
        self.log_status('Assigned to a new project: ' + project)

    def log_status(self, message):
        print(f'User: {self.name} - Status: {message}')

    def update_coffee_access(self):
        allowed_projects = ['Project X', 'Project Z']
        if self.active_project in allowed_projects:
            self.coffee_access = True
        else:
            self.coffee_access = False",

