def calculate_score(temperature, is_sunny, number_of_visitors):
    if is_sunny:
        mood = 'happy'
    else:
        mood = 'indifferent'

    if temperature > 20:
        comfort = 'comfortable'
    else:
        comfort = 'uncomfortable'

    if mood == 'happy' and comfort == 'comfortable':
        visitors_satisfaction = 0.9 * number_of_visitors
    elif mood == 'happy' or comfort == 'comfortable':
        visitors_satisfaction = 0.7 * number_of_visitors
    else:
        visitors_satisfaction = 0.5 * number_of_visitors
    return visitors_satisfaction",

