def process_data(data, scale_factor=1.5):
    if data['value'] > 100:
        data['category'] = 'High'
    else:
        data['category'] = 'Low'
    data['adjusted_value'] = data['value'] * scale_factor
    return data['category'], data['adjusted_value']",

