class EnvironmentMonitor: 
    def __init__(self, temperature, humidity): 
        self.temperature = temperature 
        self.humidity = humidity 

    def update_temperature(self, delta): 
        self.temperature += delta 

    def apply_heat_index(self): 
        if self.temperature > 30 and self.humidity > 40: 
            return 'High heat index' 
        else: 
            return 'Normal' 

monitor = EnvironmentMonitor(25, 45) 
monitor.update_temperature(10) 
heat_index = monitor.apply_heat_index()",

