        temperature = temp;
    }

    public void setWeather(boolean sunny, int temp) {
        if (sunny) {
            temperature = temp >= 30 ? temp : 30;
        } else {
            temperature = temp <= 20 ? temp : 20;
        }
        isSunny = sunny;
    }

    public boolean willPeopleGoOutside() {
        return isSunny && temperature > 25;
    }

    public int getTemperature() {
        return temperature;
    }

    public boolean isItSunny() {
        return isSunny;
    }
}",

class Experiment {
  int temperature;
  int pressure;
  boolean result;
  public Experiment(int temperature) {
    this.temperature = temperature;
    this.pressure = (int) (temperature * 1.2); // Assumes pressure is dependent on temperature
    this.result = this.pressure > 100; // Result is true if pressure is greater than 100
  }
  public void setTemperature(int temperature) {
    this.temperature = temperature;
    this.pressure = (int) (temperature * 1.1); // Changing the dependency formula here
    this.result = this.pressure > 110; // Also changing the threshold for result
  }
}",

