def calculate_discount(item_price, customer_loyalty_status):
    base_discount = 0.05
    loyalty_discount_multiplier = 0.85
    if customer_loyalty_status == 'gold':
        incremental_discount = 0.15
    elif customer_loyalty_status == 'silver':
        incremental_discount = 0.10
    else:
        incremental_discount = 0
    final_discount = base_discount + (incremental_discount * loyalty_discount_multiplier)
    discounted_price = item_price * (1 - final_discount)
    return discounted_price",

