class HealthSystem:
    def __init__(self, num_doctors):
        self.num_doctors = num_doctors
        self.patient_health = 0  # scale from 0 (poor) to 100 (excellent)

    def treat_patient(self, treatment_plan):
        if treatment_plan == 'advanced':
            self.patient_health += 40
        elif treatment_plan == 'regular':
            self.patient_health += 20
        else:
            self.patient_health += 5

        self.patient_health = min(self.patient_health, 100)  # Cap health at 100

    def hire_doctor(self):
        self.num_doctors += 1

    def impact_of_doctors_on_health(self):
        if self.num_doctors > 5:
            self.patient_health += 10
        else:
            self.patient_health -= 5
        self.patient_health = max(self.patient_health, 0)  # Health shouldn't fall below 0

system = HealthSystem(4)
system.treat_patient('regular')
system.hire_doctor()
system.impact_of_doctors_on_health()
""",

