def update_prices(prices, adjustment_factor, demand, supply):
    if supply > demand:
        adjustment_factor *= 0.9
    else:
        adjustment_factor *= 1.1
    new_prices = {product: price * adjustment_factor for product, price in prices.items()}
    return new_prices",

