  public EnergyUsageCalculator(float initialTemperature) {
    temperature = initialTemperature;
    heatingOn = initialTemperature < 20;
  }

  public void setTemperature(float newTemperature) {
    temperature = newTemperature;
    if (temperature < 18) {
      heatingOn = true;
    } else if (temperature > 25) {
      heatingOn = false;
    }
  }

  public float estimateEnergyUsage() {
    if (heatingOn) {
      return (21 - temperature) * 1.2f;
    } else {
      return 0;
    }
  }
}
",

