class WeatherController: 
    def __init__(self, temperature, humidity): 
        self.temperature = temperature 
        self.humidity = humidity 
    def update_weather(self, new_temp, new_humidity): 
        self.temperature = new_temp 
        self.humidity = new_humidity 
    def is_rainy(self): 
        if self.humidity > 80 and self.temperature < 20: 
            return True 
        else: 
            return False 
    def adjust_for_season(self, season): 
        if season == 'winter': 
            self.temperature -= 5 
            self.humidity += 10",

