class WeatherSimulator {
  private boolean isRaining;
  private boolean umbrellaOpen;
  private int temperature;

  public WeatherSimulator() {
    this.isRaining = Math.random() > 0.7;
    this.temperature = (int) (Math.random() * 40);
    this.umbrellaOpen = false;
  }

  public void openUmbrella() { if (!umbrellaOpen && isRaining) this.umbrellaOpen = true; }

  public String checkComfort() {
    if (!isRaining && temperature > 25) return 'Comfortable';
    else if (isRaining && umbrellaOpen) return 'Manageable';
    else return 'Uncomfortable';
  }

  public boolean toggleRain() {
    return isRaining = !isRaining;
  }

}",

