class HealthSimulator:
    def __init__(self, diet, exercise):
        self.diet = diet
        self.exercise = exercise
        self.health_score = 0

    def update_health(self):
        if self.diet == 'healthy':
            self.health_score += 20
        elif self.diet == 'unhealthy':
            self.health_score -= 10

        if self.exercise:
            self.health_score += 30
        else:
            self.health_score -= 20

    def current_status(self):
        if self.health_score > 50:
            return 'Healthy'
        elif self.health_score < 0:
            return 'Unhealthy'
        else:
            return 'Average'

# Usage
person = HealthSimulator(diet='healthy', exercise=True)
person.update_health()
status = person.current_status()
""",

