class WeatherSimulator{
  int temperature;
  bool isRaining;

  WeatherSimulator(int temp){
    temperature = temp;
    isRaining = false;
  }

  void updateWeather(int deltaTemp, bool rain){
    temperature += deltaTemp;
    if(rain){
      isRaining = true;
      if(temperature < 0){
        isRaining = false;  // freezes instead of rain
      }
    }
  }

  bool willPeopleUseUmbrellas(){
    if(isRaining && temperature > 0){
      return true;
    }
    return false;
  }
}",

