class WeatherStation {
    private double temperature;
    private boolean isRainy;
    private int alertLevel;

    public WeatherStation(double temperature, boolean isRainy) {
        this.temperature = temperature;
        this.isRainy = isRainy;
        this.alertLevel = calculateAlertLevel();
    }

    private int calculateAlertLevel() {
        if (this.isRainy) {
            if (this.temperature < 0) {
                return 3; // High alert - ice risk
            } else {
                return 2; // Moderate alert - rain
            }
        } else {
            if (this.temperature > 30) {
                return 1; // Low alert - heat
            } else {
                return 0; // No alert
            }
        }
    }

    public void updateWeather(double temperature, boolean isRainy) {
        this.temperature = temperature;
        this.isRainy = isRainy;
        this.alertLevel = calculateAlertLevel();
    }

    public int getAlertLevel() {
        return this.alertLevel;
    }
}
",

