        def __init__(self):
            self.temperature = 98.6
            self.coughing = False

        def get_sick(self, virus):
            if virus == 'flu':
                self.temperature += 3
                self.coughing = True
            elif virus == 'cold':
                self.coughing = True

        def take_medicine(self, medicine):
            if medicine == 'antipyretic':
                self.temperature -= 2
            elif medicine == 'cough syrup':
                self.coughing = False

    patient = HealthStatus()
    patient.get_sick('flu')
    patient.take_medicine('antipyretic')
