class WeatherSimulator {
  int temperature = 20;
  boolean isRaining = false;

  void changeWeather(int newTemp, boolean rain) {
    if (newTemp > 30) {
      isRaining = true;
      temperature = newTemp - 5;
    } else if (rain) {
      temperature = newTemp + 10;
      isRaining = true;
    } else {
      temperature = newTemp;
      isRaining = false;
    }
  }

  String reportWeather() {
    if (isRaining) {
      return "Rainy with " + temperature + " degrees";
    } else {
      return "Clear with " + temperature + " degrees";
    }
  }
}",

