    "CodeSnippet": """
    class WeatherSimulator {
      int temperature;
      boolean isRainy;

      public WeatherSimulator(int temperature, boolean isRainy) {
        this.temperature = temperature;
        this.isRainy = isRainy;
      }

      public void updateWeather() {
        if (this.temperature < 0) {
          this.isRainy = false;   // It is too cold, so no rain, only snow (if precipitation)
        } else if (this.temperature > 20) {
          this.isRainy = Math.random() > 0.5; // Higher temperature, random chance of rain
        }
      }

      public boolean willPlantGrow() {
        if (this.temperature >= 10 && this.isRainy) {
          return true;   // Suitable conditions for plant growth
        }
        return false;
      }
    }
    """
