        "python_code": "class Car:
    def __init__(self, fuel_level, engine_running):
        self.fuel_level = fuel_level
        self.engine_running = engine_running
        self.speed = 0

    def start_engine(self):
        if self.fuel_level > 0:
            self.engine_running = True

    def stop_engine(self):
        self.engine_running = False

    def accelerate(self, increase):
        if self.engine_running and self.fuel_level >= 5:
            self.speed += increase
            self.fuel_level -= 5
        elif self.engine_running:
            self.speed += increase / 2

    def decelerate(self, decrease):
        if self.speed > decrease:
            self.speed -= decrease
        else:
            self.speed = 0"
