class SalesReport {
  private:
    double salesAmount;
    int numItems;
    double taxRate;

  public:
    SalesReport(double amount, int items, double tax) : salesAmount(amount), numItems(items), taxRate(tax) {}

    double calculateTotal() const {
      double taxAmount = salesAmount * taxRate;
      return salesAmount + taxAmount;
    }

    double averagePricePerItem() const {
      if (numItems > 0)
        return salesAmount / numItems;
      else
        return 0;
    }

    void applyDiscount(double discountRate) {
      salesAmount -= salesAmount * discountRate;
    }

    void updateTaxRate(double newTaxRate) {
      taxRate = newTaxRate;
    }
}",

