class ShoppingList:
    def __init__(self):
        self.items = []

    def add_item(self, item):
        self.items.append(item)
        print(f"Item {item} added to the shopping list.")

class Shopper:
    def __init__(self, name, budget):
        self.name = name
        self.budget = budget
        self.shopping_list = ShoppingList()

    def purchase_items(self):
        if self.budget >= len(self.shopping_list.items) * 10:
            for item in self.shopping_list.items:
                print(f"{self.name} purchased {item}.")
            self.budget -= len(self.shopping_list.items) * 10
            return True
        else:
            print(f"{self.name} cannot afford to purchase all the items.")
            return False

def main():
    shopper = Shopper("Alex", 50)
    shopper.shopping_list.add_item("eggs")
    shopper.shopping_list.add_item("milk")
    shopper.shopping_list.add_item("bread")
    shopper.purchase_items()

if __name__ == "__main__":
    main()
