class WeatherSimulator {
    private boolean isCloudy;
    private boolean willRain;

    public WeatherSimulator() {
        isCloudy = Math.random() > 0.5;
        willRain = isCloudy && Math.random() > 0.7;
    }

    public boolean changeWeather() {
        isCloudy = !isCloudy;
        willRain = isCloudy && Math.random() > 0.8;
        return willRain;
    }

    public boolean isItGoingToRain() {
        return willRain;
    }

    public boolean isItCloudy() {
        return isCloudy;
    }
}",

