class WeatherSimulator {
  int temperature;
  boolean isRaining;

  WeatherSimulator(int temperature, boolean isRaining) {
    this.temperature = temperature;
    this.isRaining = isRaining;
  }

  void updateWeather(int newTemp, boolean newRainStatus) {
    temperature = newTemp;
    isRaining = newRainStatus;
  }

  String getWeatherStatus() {
    if (temperature > 20 && isRaining) {
      return "Warm and rainy";
    } else if (temperature <= 20 && isRaining) {
      return "Cold and rainy";
    } else if (temperature > 20 && !isRaining) {
      return "Warm and sunny";
    } else {
      return "Cold and dry";
    }
  }
}",

