class WeatherControlDevice {
    boolean cloudy = false;
    boolean rain = false;

    void setCloudy(boolean state) {
        cloudy = state;
        if (cloudy) {
            rain = true;
        }
    }

    boolean checkRain() {
        return rain;
    }

    void resetWeather() {
        cloudy = false;
        rain = false;
    }

    void startRainRegardless() {
        cloudy = true;
        rain = true;
    }
}",

