class ShoppingCart:
    def __init__(self):
        self.items = []
        self.total_price = 0
        self.discount_rate = 0

    def add_item(self, price, discounted=False):
        if discounted:
            price *= (1 - self.discount_rate)
        self.items.append(price)
        self.total_price += price

    def change_discount(self, new_discount_rate):
        self.discount_rate = new_discount_rate
