class TrafficSystem {
  int signal; 
  boolean isRaining; 

  public TrafficSystem(boolean weather) {
    isRaining = weather;
    if (isRaining) {
      signal = 1; // 1 for red
    } else {
      signal = 0; // 0 for green
    }
  }

  public void manualOverride(int newSignal) {
    signal = newSignal;
  }

  public int getTrafficStatus() {
    if (signal == 1) {
      return 5; // Heavy traffic
    } else {
      return 1; // Light traffic
    }
  }
}",

