def process_order(user, item, discount_code=None):
    price = item.price
    if discount_code:
        if verify_discount(discount_code):
            price *= 0.9
    if user.is_premium_member:
        price *= 0.95
    update_inventory(item)
    return price

def verify_discount(code):
    valid_codes = {'SAVE10', 'OFF20'}
    return code in valid_codes

def update_inventory(item):
    item.stock -= 1",

