class HealthMonitor(object):
    def __init__(self, age, smoker_status, fitness_level):
        self.age = age
        self.smoker_status = smoker_status
        self.fitness_level = fitness_level
        self.heart_risk = self.calculate_risk()

    def calculate_risk(self):
        base_risk = 5
        if self.age > 50:
            base_risk += 5
        if self.smoker_status == 'smoker':
            base_risk += 10
        if self.fitness_level == 'high':
            base_risk -= 3
        return base_risk

    def update_fitness_level(self, new_level):
        self.fitness_level = new_level
        self.heart_risk = self.calculate_risk()",

