public class HealthSystem {
    private int health;
    private boolean isInvincible;

    public HealthSystem(int initialHealth) {
       health = initialHealth;
       isInvincible = false;
    }

    public void takeDamage(int damage) {
        if (!isInvincible) {
            health -= damage;
        }
    }

    public void heal(int amount) {
        health += amount;
    }

    public void setInvincible(boolean status) {
        isInvincible = status;
    }

    public int getHealth() {
        return health;
    }

    public boolean getInvincibilityStatus() {
        return isInvincible;
    }
}",

