class Sales:
    def __init__(self, product):
        self.product = product
        self.sales_figures = 0

    def update_sales(self, marketing_budget):
        if self.product.price > 50:
            if marketing_budget > 1000:
                self.sales_figures += 200
            else:
                self.sales_figures += 100
        else:
            if marketing_budget > 1000:
                self.sales_figures += 300
            else:
                self.sales_figures += 150

# Example usage
product_a = Product(60, 'high')
sales_a = Sales(product_a)
sales_a.update_sales(1200)
