def compute_discount(items, coupon_code):
    total = sum(item['price'] * item['quantity'] for item in items)
    discount = 0
    if coupon_code == '20OFF':
        discount = total * 0.2
    elif coupon_code == '10OFF':
        discount = total * 0.1
    return total - discount",

