def compute_health_scores(age, weight, exercise_hours):
    health_risk = (age * 0.2 + weight * 0.5) - exercise_hours * 2
    if health_risk > 50:
        return 'High Risk'
    elif 20 <= health_risk <= 50:
        return 'Medium Risk'
    else:
        return 'Low Risk'",

