class PopulationHealth:
    def __init__(self, number_of_people, vaccination_rate):
        self.number_of_people = number_of_people
        self.vaccination_rate = vaccination_rate
        self.immunity_level = self.calculate_immunity()

    def calculate_immunity(self):
        return self.number_of_people * self.vaccination_rate 

    def introduce_pathogen(self, virulence):
        if self.immunity_level > 100:
            return 'pathogen contained'
        elif self.immunity_level * virulence > 200:
            return 'outbreak controlled'
        else:
            return 'large outbreak'
