def compute_health_scores(age, diet_quality, physical_activity_level):
    base_score = 100
    if age > 50:
        base_score -= 10
    if diet_quality < 5:
        base_score -= 30
    if physical_activity_level > 7:
        base_score += 20
    return base_score",

