class HealthSystem:
    def __init__(self):
        self.patients = []

    def add_patient(self, patient):
        if not self.check_existing_patient(patient):
            self.patients.append(patient)
            return "Patient added"
        else:
            return "Patient already exists"

    def check_existing_patient(self, patient):
        return any(p.id == patient.id for p in self.patients)

    def administer_vaccine(self, patient_id):
        for patient in self.patients:
            if patient.id == patient_id:
                patient.vaccinated = True
                return "Vaccine administered"
        return "Patient not found"

    def check_vaccination_status(self, patient_id):
        for patient in self.patients:
            if patient.id == patient_id:
                return patient.vaccinated
        return False

# Simplified version of a Patient class.
class Patient:
    def __init__(self, id):
        self.id = id
        self.vaccinated = False
