class WeatherStation {
  int temperature; 
  boolean isRaining; 
  int humidityLevel;

  public WeatherStation(int temperature, boolean isRaining, int humidityLevel) {
    this.temperature = temperature;
    this.isRaining = isRaining;
    this.humidityLevel = humidityLevel;
  }

  public boolean willRainSoon() {
    if (this.humidityLevel > 85 && this.temperature < 20) {
      return true;
    }
    return false;
  }

  public void increaseHumidity(int increment) {
    this.humidityLevel += increment;
  }

  public void adjustTemperature(boolean increase) {
    if (increase) {
      this.temperature += 5;
    } else {
      this.temperature -= 5;
    }
  }
}",

