class TrafficSystem { 
    int trafficDensity; 
    boolean isHoliday; 
    int trafficSpeed; 

    TrafficSystem(int trafficDensity, boolean isHoliday) { 
        this.trafficDensity = trafficDensity; 
        this.isHoliday = isHoliday; 
        calculateTrafficSpeed(); 
    } 

    void calculateTrafficSpeed() { 
        if(isHoliday) { 
            trafficSpeed = 80; 
        } else if (trafficDensity < 50) { 
            trafficSpeed = 70; 
        } else { 
            trafficSpeed = 30; 
        } 
    } 

    boolean isHighTraffic() { 
