class Market:
    def __init__(self, economy_status):
        self.economy_status = economy_status

    def demand_modifier(self):
        if self.economy_status == 'good':
            return 1.1
        elif self.economy_status == 'poor':
            return 0.8
        else:
            return 1.0

class Sale:
    def __init__(self, base_price, ad_spend):
        self.base_price = base_price
        self.ad_spend = ad_spend

    def calculate_sale(self, modifier):
        return self.base_price * self.ad_spend * modifier

# Main Execution
current_market = Market('good')
product_sale = Sale(100, 10)
final_sale = product_sale.calculate_sale(current_market.demand_modifier())

print(f"Final Sales Figure: ${final_sale}")
""",

