def process_data(data, filters, enhance=False):
    if 'date' in filters:
        data = [d for d in data if d['date'] >= filters['date']]
    if 'category' in filters:
        data = [d for d in data if d['category'] == filters['category']]
    if enhance:
        data = [{'id': d['id'], 'value': d['value'] * 1.1} for d in data]
    return data",

