class Store:
    def __init__(self):
        self.stock = {'apple': 50, 'banana': 75, 'cherry': 20}
        self.money = 1000

    def sell_item(self, item, quantity):
        if item in self.stock and self.stock[item] >= quantity:
            self.stock[item] -= quantity
            sales = quantity * self.get_price(item)
            self.money += sales
            return True
        else:
            return False

    def get_price(self, item):
        pricing = {'apple': 10, 'banana': 5, 'cherry': 15}
        return pricing.get(item, 0)

    def add_stock(self, item, quantity):
        if item in self.stock:
            self.stock[item] += quantity
        else:
            self.stock[item] = quantity

