class WeatherSimulator {
  def __init__(self, temperature, humidity):
    self.temperature = temperature
    self.humidity = humidity
    self.weather_condition = ''

  def update_weather(self):
    if self.temperature > 20 and self.humidity > 70:
      self.weather_condition = 'Rainy'
    elif self.temperature < 0:
      self.weather_condition = 'Snowy'
    else:
      self.weather_condition = 'Clear'

  def is_rainy(self):
    return self.weather_condition == 'Rainy'

  def make_rain(self):
    self.humidity = 80
    self.update_weather()
}",

