def analyze_temperatures(data): 
    avg_temp = sum(data) / len(data) 
    hot_days = [day for day in data if day > 30] 
    cold_days = [day for day in data if day < 10] 
    result = {'average': avg_temp, 'hot_days_count': len(hot_days), 'cold_days_count': len(cold_days)} 
    return result",

