def log_request(request, error_log_enabled, debug_mode):
    if error_log_enabled:
        if request['status_code'] >= 500:
            print('Logging error: ', request)
        elif debug_mode and request['status_code'] == 404:
            print('Logging debug: ', request)
        else:
            print('No logging needed')
    else:
        if debug_mode and request['status_code'] in [403, 405]:
            print('Logging debug only mode: ', request)
        else:
            print('Logging disabled')

# Example requests
log_request({'status_code': 500}, error_log_enabled=True, debug_mode=False)
log_request({'status_code': 404}, error_log_enabled=True, debug_mode=True)
log_request({'status_code': 405}, error_log_enabled=False, debug_mode=True)
""",

