class ShoppingCart {
  constructor() {
    this.items = [];
    this.discount = 0;
  }

  addItem(item) {
    this.items.push(item);
    this.updateDiscount();
  }

  updateDiscount() {
    if (this.items.length > 5) {
      this.discount = 20;
    } else {
      this.discount = 0;
    }
  }

  removeItem() {
    if (this.items.length > 0) {
      this.items.pop();
      this.updateDiscount();
    }
  }

  calculateTotal() {
    let total = this.items.reduce((sum, item) => sum + item.price, 0);
    return total - total * this.discount / 100;
  }
}",

