class ClimateControlSystem:
    def __init__(self):
        self.temperature = 25
        self.humidity = 50
        self.weather = 'sunny'

    def adjust_temperature(self, adjustment):
        if self.weather == 'cold':
            self.temperature += (adjustment * 2)
        else:
            self.temperature += adjustment

    def change_weather(self, new_weather):
        self.weather = new_weather
        if new_weather == 'rainy':
            self.humidity += 25
        elif new_weather == 'sunny':
            self.humidity -= 15

    def activate_heating(self):
        self.adjust_temperature(5)
        if self.weather == 'snowy':
            self.humidity += 10

    def simulate_day(self):
        if self.weather in ['sunny', 'cold']:
            self.adjust_temperature(-3)
        else:
            self.adjust_temperature(-1)
