def process_data(data, filter_key, operation, threshold): 
    filtered_data = [d for d in data if d[filter_key] >= threshold]
    if operation == 'sum':
        result = sum(filtered_data)
    elif operation == 'count':
        result = len(filtered_data)
    else:
        result = None
    return result",

