class WeatherSimulator { 
    private int temperature;
    private boolean isRainy;

    public WeatherSimulator() {
      this.temperature = (int) (Math.random() * 30); // Random temperature between 0 and 29
      this.isRainy = (this.temperature < 20);  // It's more likely to rain when it's cooler
    }

    public void causeStorm() {
      this.isRainy = true;
      this.temperature -= 5; // Storm causes the temperature to decrease by 5 degrees
    }

    public int getTemperature() {
      return temperature;
    }

    public boolean getRainStatus() {
      return isRainy;
    }
  }",

