# Python code for managing inventory based on sales and product returns

class InventoryManagement:
    def __init__(self):
        self.inventory = {'apples': 100, 'oranges': 150, 'bananas': 200}

    def sell_product(self, product, quantity):
        if self.inventory[product] >= quantity:
            self.inventory[product] -= quantity
            return 'Sale completed'
        else:
            return 'Insufficient stock'

    def return_product(self, product, quantity):
        self.inventory[product] += quantity
        return 'Return processed'

    def check_inventory(self, product):
        return self.inventory[product]

    def order_stock(self, product, quantity):
        self.inventory[product] += quantity

# Example usage
inventory_system = InventoryManagement()
sale_response = inventory_system.sell_product('apples', 50)
return_response = inventory_system.return_product('apples', 20)
""",

