class WeatherController {
  int temperature;
  boolean isRaining;

  WeatherController(int temp, boolean rain) {
    this.temperature = temp;
    this.isRaining = rain;
  }

  String getWeatherStatus() {
    if (temperature > 20 && !isRaining) {
      return "Sunny";
    } else if (temperature <= 20 && isRaining) {
      return "Rainy";
    }
    return "Cloudy";
  }

  void temperatureRise(int increase) {
    this.temperature += increase;
    if (this.temperature > 30) {
      this.isRaining = false;
    }
  }

  void simulateRain() {
    this.isRaining = true;
    if (this.temperature > 20) {
      this.temperature -= 5;
    }
  }
}",

