         flag = false;
      }
   }
   boolean checkFlag() {
      return flag;
   }
   int getCounter() {
      return counter;
   }
}",

class EventSystem {
   int counter = 0;
   boolean flag = false;
   void receiveEvent(String eventType) {
      if (eventType.equals('A')) {
         counter += 1;
         if (counter > 5) {
            flag = true;
         }
      } else if (eventType.equals('B')) {
         counter = 0;
         flag = false;
      }
   }
   boolean checkFlag() {
      return flag;
   }
   int getCounter() {
      return counter;
   }
}",

class MarketingCampaign:
    def __init__(self, budget):
        self.budget = budget
        self.ads = 0
        self.sales = 0

    def spend_on_ads(self, amount):
        if amount > self.budget:
            return "Insufficient budget"
        self.budget -= amount
        self.ads += amount / 10

    def generate_sales(self):
        if self.ads > 0:
            self.sales = self.ads * 50  # More ads, more sales
        return self.sales

# Campaign instance
campaign = MarketingCampaign(1000)
campaign.spend_on_ads(500)
result_sales = campaign.generate_sales()

