class Car {
    constructor(gasTank, engineHealth) {
        this.gasTank = gasTank;
        this.engineHealth = engineHealth;
        this.isRunning = false;
    }
    startEngine() {
        if (this.gasTank > 0 && this.engineHealth > 50) {
            this.isRunning = true;
        }
    }
    drive() {
        if (this.isRunning) {
            this.gasTank -= 10;
            this.engineHealth -= 5;
        }
    }
    refuel(gas) {
        this.gasTank += gas;
    }
    repair() {
        this.engineHealth = 100;
    }
}",

