class PollSystem {
    int totalVotes;
    HashMap<String, Integer> votesPerCandidate;

    public PollSystem() {
        totalVotes = 0;
        votesPerCandidate = new HashMap<>();
    }

    public void castVote(String candidate) {
        totalVotes++;
        votesPerCandidate.put(candidate, votesPerCandidate.getOrDefault(candidate, 0) + 1);
    }

    public int getTotalVotes() {
        return totalVotes;
    }

    public int getVotesForCandidate(String candidate) {
        return votesPerCandidate.getOrDefault(candidate, 0);
    }
}",

