class WeatherSimulator {
    def __init__(self, temperature, humidity):
        self.temperature = temperature
        self.humidity = humidity
        self.weather_condition = ''
        self.adjust_weather()

    def adjust_weather(self):
        if self.temperature > 30 and self.humidity > 50:
            self.weather_condition = 'Tropical'
        elif self.temperature < 10:
            self.weather_condition = 'Cold'
        elif self.humidity < 30:
            self.weather_condition = 'Dry'
        else:
            self.weather_condition = 'Moderate'

    def set_humidity(self, new_humidity):
        self.humidity = new_humidity
        self.adjust_weather()

    def set_temperature(self, new_temperature):
        self.temperature = new_temperature
        self.adjust_weather()
}",

