class WeatherSimulator {
  private int temperature;
  private boolean isRaining;

  public WeatherSimulator() {
    this.temperature = (int)(Math.random() * 35);
    this.isRaining = Math.random() > 0.7;
  }

  public void increaseTemperature(int delta) {
    this.temperature += delta;
    if (this.temperature > 30) {
      this.isRaining = Math.random() > 0.5;
    }
  }

  public boolean willItRain() {
    return isRaining;
  }

  public void setRain(boolean rainStatus) {
    this.isRaining = rainStatus;
    if (!rainStatus) {
      this.temperature = (int)(Math.random() * 25) + 5;
    }
  }
}",

