import random

def weather_condition():
    conditions = ['sunny', 'cloudy', 'rainy', 'stormy']
    return random.choice(conditions)

def traffic_volume(weather):
    if weather == 'sunny' or weather == 'cloudy':
        return 'high'
    elif weather == 'rainy':
        return 'moderate'
    else: # stormy
        return 'low'

def accident_risk(traffic, weather):
    if traffic == 'high' and weather != 'stormy':
        return 'medium'
    elif traffic == 'moderate' or (traffic == 'high' and weather == 'stormy'):
        return 'high'
    else: # low traffic
        return 'low'
