    if (windowOpen && !heaterStatus) {
      roomTemperature = newTemp - 5;
    } else if (!windowOpen && heaterStatus) {
      roomTemperature = newTemp + 5;
    } else {
      roomTemperature = newTemp;
    }
  }

  public void toggleHeaterStatus() {
    heaterStatus = !heaterStatus;
    if (heaterStatus) {
      roomTemperature += 5;
    } else {
      roomTemperature -= 5;
    }
  }

  public void toggleWindow() {
    windowOpen = !windowOpen;
    if (windowOpen) {
      roomTemperature -= 5;
    } else {
      roomTemperature += 5;
    }
  }
}",

def compute_metrics(data):
  sales = sum(data['sales'])
  expenses = sum(data['expenses'])
  profit = sales - expenses
  roi = (profit / expenses) * 100 if expenses != 0 else 0
  return {'sales': sales, 'expenses': expenses, 'profit': profit, 'roi': roi}

data = {'sales': [100, 200, 300], 'expenses': [50, 150, 200]}
metrics = compute_metrics(data)",

