                }

                updateGameSales() {
                    if (this.sales['books'] > 100) {
                       this.sales['games'] += 10; // bonus games sales if book sales are high
                    }
                }

                applyDiscount() {
                    this.discount = 0.2; // increases discount rate
                    this.sales['books'] -= this.sales['books'] * this.discount;
                    this.sales['games'] -= this.sales['games'] * this.discount;
                }
            }
            """,

class TemperatureControlSystem { 
   private boolean isHeating = false; 
   private int setTemperature = 20; 
   private int currentTemperature = 18; 

   public void updateTemperature() { 
     if (currentTemperature < setTemperature) { 
       isHeating = true; 
       currentTemperature += 2; 
     } else { 
       isHeating = false; 
     } 
   } 

   public void setDesiredTemperature(int newTemp) { 
     setTemperature = newTemp; 
     updateTemperature(); 
   } 

   public boolean getHeatingStatus() { 
     return isHeating; 
   } 

   public int getCurrentTemperature() { 
     return currentTemperature; 
   } 
 }",

