class WeatherSimulator {
    private double temperature;
    private boolean isRaining;

    public WeatherSimulator() {
        this.temperature = 20.0;  // Default temperature (in Celsius)
        this.isRaining = false;  // Default Weather Condition
    }

    public void increaseTemperature(double degrees) {
        this.temperature += degrees;
        if (this.temperature > 30) {
            this.isRaining = true;  // It starts raining if the temperature is too high
        }
    }

    public boolean willItRain() {
        return this.isRaining;
    }

    public void setRaining(boolean raining) {
        this.isRaining = raining;
        if (raining) {
            this.temperature = 25;  // Assume rain brings down the temperature
        }
    }
}",

