def process_data(data):
  processed_data = normalize(data)
  if should_augment(data):
    augmented_data = augment(data)
    return combine(processed_data, augmented_data)
  else:
    return processed_data

 def normalize(data):
  return [x / max(data) for x in data]

 def augment(data):
  return [x + 1 for x in data]

 def should_augument(data):
  return len(data) > 10

 def combine(a, b):
  return a + b",

