class WeatherSimulator {
  private boolean isRaining;
  private int temperature;

  public WeatherSimulator(boolean rain, int temp) {
    isRaining = rain;
    temperature = temp;
  }

  public boolean willPeopleUseUmbrellas() {
    boolean useUmbrella = false;
    if (isRaining) {
      if (temperature < 20) {
        useUmbrella = true;
      }
    }
    return useUmbrella;
  }

  public boolean isColderOutside() {
    return temperature < 15;
  }
}
",

