def update_inventory(product_sell, current_inventory): 
    if product_sell['product_id'] in current_inventory: 
        current_inventory[product_sell['product_id']] -= product_sell['quantity'] 
        if current_inventory[product_sell['product_id']] < 0: 
            current_inventory[product_sell['product_id']] = 0 
    return current_inventory",

