class SystemStatus:
  def __init__(self):
    self.temperature = 25  # degrees Celsius
    self.pressure = 1     # atmospheres
    self.humidity = 50    # percent

  def heat_system(self, increase):
    self.temperature += increase
    if self.temperature > 30:
      self.humidity += 5

  def cool_system(self, decrease):
    self.temperature -= decrease
    if self.temperature < 20:
      self.humidity -= 10

  def increase_pressure(self):
    self.pressure += 0.5
    if self.pressure > 1.5:
      self.temperature += 3

