def compute_scores(grades, bonus_enabled, penalty_enabled):
    base_score = sum(grades) / len(grades)
    if bonus_enabled:
        bonus = max(grades)
        base_score += bonus
    if penalty_enabled:
        penalty = min(grades)
        base_score -= penalty
    return base_score",

