def update_inventory(products, sales):
    inventory = {item: stock for item, stock in products}
    for sale in sales:
        product, quantity_sold = sale
        if product in inventory:
            inventory[product] -= quantity_sold
            if inventory[product] < 0:
                inventory[product] = 0
    return inventory

