class OnlineStore:
    def __init__(self, inventory, sales):
        self.inventory = inventory
        self.sales = sales

    def update_inventory(self, product, amount):
        if product in self.inventory:
            self.inventory[product] -= amount
            self.sales[product] += amount
        else:
            print(f'Unknown product: {product}')

    def get_inventory(self, product):
        if product in self.inventory:
            return self.inventory[product]
        else:
            return 0

    def report_sales(self, product):
        if product in self.sales:
            return self.sales[product]
        else:
            return 0",

