def process_data(data): 
    clean_data = clean(data) 
    processed_data = analyze(clean_data) 
    if 'error' in processed_data: 
        return handle_error(processed_data) 
    return summarize(processed_data) 

def clean(data): 
    return [d for d in data if d['isValid']] 

def analyze(data): 
    try: 
        result = {'mean': sum(d['value'] for d in data) / len(data), 'max': max(d['value'] for d in data)} 
    except ZeroDivisionError: 
        result = {'error': 'Division by zero'} 
    return result 

def handle_error(data): 
    return {'status': 'error', 'message': data['error']} 

def summarize(data): 
    return {'status': 'success', 'data': {'mean': data['mean'], 'max': data['max']}}",

