class DataProcessor {
    int data;
    boolean status;
    DataProcessor(int initialData) {
        this.data = initialData;
        this.status = false;
    }
    void updateData(int newData) {
        if (newData > 0) {
            this.data = newData;
            this.status = true;
        } else {
            this.status = false;
        }
    }
    boolean processData() {
        if (this.status) {
            this.data += 10;
            return true;
        }
        return false;
    }
}",

