    "code": "class SalesDataAnalyzer:
    def __init__(self, sales_records):
        self.sales_records = sales_records

    def total_sales(self):
        return sum(record['amount'] for record in self.sales_records if record['status'] == 'completed')

    def average_sale_amount(self):
        completed_sales = [record['amount'] for record in self.sales_records if record['status'] == 'completed']
        if completed_sales:
            return sum(completed_sales) / len(completed_sales)
        else:
            return 0

    def apply_discount(self, discount_percentage):
        for record in self.sales_records:
            if record['status'] == 'completed':
                record['amount'] -= record['amount'] * (discount_percentage / 100)
