def update_user_activity(user, action, database):
    if action == 'login':
        user['status'] = 'online'
        database['log'].append(f"User {user['id']} logged in.")
    elif action == 'logout':
        user['status'] = 'offline'
        database['log'].append(f"User {user['id']} logged out.")
    database['user_activity'][user['id']] = action
    return database",

