# A simple banking system to handle transactions and balance inquiries

class Account:
    def __init__(self, owner, balance=0):
        self.owner = owner
        self.balance = balance

    def deposit(self, amount):
        if amount > 0:
            self.balance += amount
            return True
        else:
            return False

    def withdraw(self, amount):
        if 0 < amount <= self.balance:
            self.balance -= amount
            return True
        else:
            return False

    def get_balance(self):
        return self.balance

class TransferSystem:
    def __init__(self, accounts):
        self.accounts = {account.owner: account for account in accounts}

    def transfer(self, from_owner, to_owner, amount):
        from_account = self.accounts.get(from_owner)
        to_account = self.accounts.get(to_owner)
        if from_account and to_account and from_account.withdraw(amount):
            to_account.deposit(amount)
            print(f"Transfer successful: {amount} from {from_owner} to {to_owner}")
            return True
        else:
            print("Transfer failed")
            return False
""",

