class EmployeePerformance:
    def __init__(self, sales_figures, previous_performance):
        self.sales_figures = sales_figures
        self.previous_performance = previous_performance
        self.is_promoted = False

    def evaluate_performance(self):
        if self.sales_figures > 100000:
            self.is_promoted = True
        elif self.previous_performance == 'excellent' and self.sales_figures > 50000:
            self.is_promoted = True
        else:
            self.is_promoted = False

    def promotion_status(self):
        return self.is_promoted",

