def analyze_sales_data(data):
    total_sales = sum(data['sales'])
    max_sale = max(data['sales'])
    if max_sale > 100000:
        company_status = 'Leading'
    else:
        company_status = 'Normal'
    advertising = len(data['ads']) * 1500
    if advertising > total_sales * 0.1:
        marketing_efficiency = 'Low'
    else:
        marketing_efficiency = 'High'
    return {'Total Sales': total_sales, 'Company Status': company_status, 'Marketing Efficiency': marketing_efficiency}",

