class WeatherSimulator {
    private int temperature;
    private boolean isRainy;

    public WeatherSimulator() {
        temperature = 20; // default temperature
        isRainy = false; // default weather condition
    }

    public void increaseTemperature(int degrees) {
        temperature += degrees;
        if (temperature > 30) {
            isRainy = true; // high temperatures might cause rain
        }
    }

    public void decreaseTemperature(int degrees) {
        temperature -= degrees;
        if (temperature < 10) {
            isRainy = false; // cold temperatures reduce the probability of rain
        }
    }

    public boolean getWeatherCondition() {
        return isRainy;
    }

    public int getTemperature() {
        return temperature;
    }
}",

