def sales_prediction(weather, holiday, discount): 
  if weather == 'sunny':
    mood = 'happy'
  else:
    mood = 'normal'
  if holiday:
    free_time = 2
  else:
    free_time = 1
  if discount:
    spending_power = 1.5
  else:
    spending_power = 1
  sales = (mood == 'happy') * free_time * spending_power
  return sales",

