class Environment:
    def __init__(self, pollution_level, regulations_strictness):
        self.pollution_level = pollution_level
        self.regulations_strictness = regulations_strictness

    def check_air_quality(self):
        if self.pollution_level > 100:
            return "Poor"
        elif self.pollution_level > 50:
            return "Moderate"
        else:
            return "Good"

class Factory:
    def __init__(self, size):
        self.size = size
        self.pollution_generated = self.calculate_pollution()

    def calculate_pollution(self):
        base_pollution = 20
        additional_pollution = 5 * self.size  # More pollution based on factory size
        total_pollution = base_pollution + additional_pollution
        return total_pollution

    def operate_factory(self, environment):
        environment.pollution_level += self.pollution_generated
        return environment.pollution_level

env = Environment(40, 'high')
factory = Factory(10)
pollution_before = env.pollution_level
factory.operate_factory(env)
pollution_after = env.pollution_level
air_quality = env.check_air_quality()
""",

