class ShoppingCart:
    def __init__(self):
        self.items = []
        self.total = 0

    def add_item(self, price):
        self.items.append(price)
        self.update_total()

    def update_total(self):
        self.total = sum(self.items)

    def apply_discount(self, discount):
        if discount > 0 and discount <= 1:
            self.total = self.total * (1 - discount)

    def remove_item(self, price):
        if price in self.items:
            self.items.remove(price)
            self.update_total()

cart = ShoppingCart()
cart.add_item(100)
cart.add_item(200)
cart.apply_discount(0.15)
cart.remove_item(100)

