        class Product {
            constructor(name, basePrice) {
                this.name = name;
                this.basePrice = basePrice;
                this.discountRate = 0;
            }

            applyDiscount(discountPercentage) {
                this.discountRate = discountPercentage;
                this.finalPrice = this.basePrice * (1 - (this.discountRate / 100));
            }

            calculateTax(taxRate) {
                if (!this.finalPrice) {
                    this.finalPrice = this.basePrice;
                }
                this.finalPrice = this.finalPrice * (1 + (taxRate / 100));
            }
        }

        const smartphone = new Product('Smartphone', 500);
        smartphone.applyDiscount(10);
        smartphone.calculateTax(5);
