class Ecosystem:
    def __init__(self, rabbits=50, foxes=10):
        self.rabbits = rabbits
        self.foxes = foxes

    def grow_rabbits(self, growth_rate=1.1):
        self.rabbits *= growth_rate

    def grow_foxes(self, hunt_success_rate=0.2):
        eaten_rabbits = self.rabbits * hunt_success_rate
        self.rabbits -= eaten_rabbits
        self.foxes += eaten_rabbits / 10

    def simulate_year(self):
        self.grow_rabbits()
        self.grow_foxes()

ecosystem = Ecosystem()
for _ in range(5):
    ecosystem.simulate_year()",

