def update_values(data, factor, operation): 
    if operation == 'scale': 
        result = {k: v * factor for k, v in data.items()} 
    elif operation == 'add': 
        result = {k: v + factor for k, v in data.items()} 
    else: 
        result = data 
    return result 

input_data = {'a': 1, 'b': 2, 'c': 3} 
operation_type = 'scale' 
scaling_factor = 2 
updated_data = update_values(input_data, scaling_factor, operation_type)",

