class Thermostat:
    def __init__(self, target_temp):
        self.target_temp = target_temp
        self.current_temp = 20
        self.heater_on = False

    def update_temperature(self, ambient_temp):
        self.current_temp = self.current_temp + 0.1 * (ambient_temp - self.current_temp)
        self.check_heater()

    def check_heater(self):
        if self.current_temp < self.target_temp:
            self.heater_on = True
        else:
            self.heater_on = False",

