    class HealthTracker {
      constructor(age, hasExerciseRoutine) {
        this.age = age;
        this.hasExerciseRoutine = hasExerciseRoutine;
        this.healthScore = 0;
        this.updateHealthScore();
      }

      updateHealthScore() {
        this.healthScore = 50; // base health score
        if(this.age > 50) {
          this.healthScore -= 10;
        }
        if(this.hasExerciseRoutine) {
          this.healthScore += 20;
        }
      }

      introduceNewHabit(habit) {
        if(habit === 'Diet') {
          this.healthScore += 5;
        }
        this.hasExerciseRoutine = habit === 'Exercise';
        this.updateHealthScore();
      }
    }

    const bob = new HealthTracker(55, true);
    bob.introduceNewHabit('Diet');
  `,

