def calculate_health(age, smoking_status, exercise_freq):
    base_health = 100
    if age > 50:
        base_health -= (age - 50) * 0.5
    if smoking_status:
        base_health -= 20
    if exercise_freq >= 3:
        base_health += 15
    return base_health",

