class TemperatureController:
    def __init__(self, set_point):
        self.set_point = set_point
        self.current_temperature = 0

    def update_temperature(self, env_temp, heater_on):
        if heater_on:
            self.current_temperature = env_temp + 10
        else:
            self.current_temperature = env_temp - 5

    def check_status(self):
        if self.current_temperature > self.set_point:
            return 'Too hot'
        elif self.current_temperature < self.set_point:
            return 'Too cold'
        else:
            return 'Perfect'
