public class TemperatureControlSystem {
    private int temperature;
    private boolean acState;
    private boolean heaterState;

    public TemperatureControlSystem() {
        temperature = 70; // Default room temperature in Fahrenheit
        acState = false;
        heaterState = false;
    }

    public void increaseTemperature(int degrees) {
        if (!acState && degrees > 0) {
            temperature += degrees;
            heaterState = true;
        }
    }

    public void decreaseTemperature(int degrees) {
        if (!heaterState && degrees > 0) {
            temperature -= degrees;
            acState = true;
        }
    }

    public boolean isACOn() {
        return acState;
    }

    public boolean isHeaterOn() {
        return heaterState;
    }

    public int getTemperature() {
        return temperature;
    }
}",

