class WeatherSystem {
    int temperature;
    int humidity;
    boolean raining;

    public WeatherSystem(int temp, int humid) {
        temperature = temp;
        humidity = humid;
        raining = determineRain();
    }

    private boolean determineRain() {
        if (humidity > 70 && temperature < 20) {
            return true;
        } else {
            return false;
        }
    }

    public void increaseTemperature(int degrees) {
        temperature += degrees;
        raining = determineRain();
    }

    public void setHumidity(int humid) {
        humidity = humid;
        raining = determineRain();
    }
}",

