class ClimateControlSystem {
\
    int temperature;
\
    boolean acOn;
\
    boolean heaterOn;
\
    int externalTemp;
\
    public ClimateControlSystem(int externalTemp) {
\
      this.externalTemp = externalTemp;
\
      this.temperature = externalTemp;
\
      this.acOn = false;
\
      this.heaterOn = false;
\
    }
\
    public void toggleAC() {
\
      this.acOn = !this.acOn;
\
      if (this.acOn) {
\
        this.temperature -= 5;
\
      }
\
    }
\
    public void toggleHeater() {
\
      this.heaterOn = !this.heaterOn;
\
      if (this.heaterOn) {
\
        this.temperature += 5;
\
      }
\
    }
\
    public void updateExternalTemperature(int newTemp) {
\
      this.externalTemp = newTemp;
\
      if (!this.acOn && !this.heaterOn) {
\
        this.temperature = newTemp;
\
      }
\
    }
\
  }",

