class HealthSystem:
    def __init__(self, num_doctors, num_patients):
        self.num_doctors = num_doctors
        self.num_patients = num_patients
        self.appointments = 0

    def schedule_appointments(self):
        if self.num_doctors > 0:
            self.appointments = self.num_patients // self.num_doctors

    def increase_doctors(self, new_doctors):
        self.num_doctors += new_doctors
        self.schedule_appointments()

    def emergency(self, num_emergencies):
        if num_emergencies > self.num_doctors:
            self.num_patients += num_emergencies - self.num_doctors
            self.schedule_appointments()

health_sys = HealthSystem(10, 100)
health_sys.schedule_appointments()
health_sys.increase_doctors(2)
health_sys.emergency(5)
  """,

