class Weather {
  int temperature;
  boolean rainy;

  Weather(int temperature, boolean rainy) {
    this.temperature = temperature;
    this.rainy = rainy;
  }

  boolean isCold() {
    return this.temperature < 15;
  }

  boolean isWet() {
    return this.rainy && isCold();
  }

  void increaseTemperature(int increase) {
    this.temperature += increase;
  }
}

public static void main(String[] args) {
  Weather todayWeather = new Weather(10, true);
  todayWeather.increaseTemperature(5);

  System.out.println(todayWeather.isCold());
  System.out.println(todayWeather.isWet());
}
