class WeatherSimulator {
    private int temperature;

    public WeatherSimulator(int initialTemp) {
        temperature = initialTemp;
    }

    public void updateTemperature() {
        if (temperature < 20) {
            temperature += 3;
        } else if (temperature >= 20 && temperature <= 25) {
            temperature += 1;
        } else {
            temperature -= 2;
        }
    }

    public int getTemperature() {
        return temperature;
    }

    public String evaluateComfort() {
        updateTemperature();
        if (temperature <= 18) {
            return "Cold";
        } else if (temperature > 18 && temperature < 23) {
            return "Comfortable";
        } else {
            return "Hot";
        }
    }
