class Thermostat {
  private int temperature;
  private boolean power;

  public Thermostat() {
    temperature = 22; // Default room temperature in Celsius
    power = false; // Thermostat is initially turned off
  }

  public void turnPowerOn() {
    power = true;
  }

  public void turnPowerOff() {
    power = false;
  }

  public void setTemperature(int newTemp) {
    if (power) {
      temperature = newTemp;
    }
  }

  public boolean isPowerOn() {
    return power;
  }

  public int getTemperature() {
    return temperature;
  }

