def process_orders(order_data):
    total_items = sum([order['quantity'] for order in order_data])
    if total_items > 50:
        discount = 0.1
    else:
        discount = 0
    total_cost = sum([order['quantity'] * order['price'] * (1 - discount) for order in order_data])
    return total_cost",

