def compute_salaries(base_salaries, has_bonus, bonus_rate): 
    total_salaries = [] 
    for index, base_salary in enumerate(base_salaries): 
        if has_bonus[index]: 
            total_salary = base_salary + (base_salary * bonus_rate[index]) 
        else: 
            total_salary = base_salary 
        total_salaries.append(total_salary) 
    return total_salaries",

