class WeatherSimulator {
  private int temperature;
  private boolean isRainy;

  public WeatherSimulator() {
    temperature = 20; // Default temperature
    isRainy = false; // Default weather condition
  }

  public void setTemperature(int newTemp) {
    temperature = newTemp;
    if (temperature < 5) {
      isRainy = true; // It rains when it's very cold
    }
  }

  public void manualRainStart() {
    isRainy = true;
    if (!isWeatherWarm()) {
      temperature -= 5; // Temperature drops when it starts raining unless it's warm
    }
  }

  private boolean isWeatherWarm() {
    return temperature > 15;
  }
}",

