class WeatherSimulator { 
    boolean isSunny; 
    int temperature; 
    boolean isWeekend;

    public WeatherSimulator(boolean isWeekend) { 
        this.isWeekend = isWeekend; 
        if (isWeekend) { 
            this.isSunny = Math.random() > 0.3; 
            this.temperature = isSunny ? (22 + (int)(Math.random() * 10)) : (18 + (int)(Math.random() * 5)); 
        } else { 
            this.isSunny = Math.random() > 0.5; 
            this.temperature = isSunny ? (20 + (int)(Math.random() * 6)) : (16 + (int)(Math.random() * 4)); 
        }
    }
}",

