class Plant:
    def __init__(self, primary_need, secondary_need=None):
        self.primary_need = primary_need
        self.secondary_need = secondary_need
        self.is_healthy = False

    def check_health(self):
        if self.primary_need == 'water' and self.secondary_need == 'sunlight':
            self.is_healthy = True
        else:
            self.is_healthy = False

class Garden:
    def __init__(self):
        self.plants = []

    def add_plant(self, plant):
        self.plants.append(plant)

    def water_plants(self):
        for plant in self.plants:
            plant.primary_need = 'water'

    def sunbathe_plants(self):
        for plant in self.plants:
            plant.secondary_need = 'sunlight'

    def check_plant_healths(self):
        health_statuses = []
        for plant in self.plants:
            plant.check_health()
            health_statuses.append(plant.is_healthy)
        return health_statuses

# Usage
garden = Garden()
rose = Plant('water', 'sunlight')
cactus = Plant('sunlight', 'water')
garden.add_plant(rose)
garden.add_plant(cactus)
garden.water_plants()
garden.sunbathe_plants()
health_states = garden.check_plant_healths()
""",

