class WeatherControlSystem:
    def __init__(self, temperature, humidity):
        self.temperature = temperature
        self.humidity = humidity

    def adjust_temperature(self, change):
        if self.temperature + change > 100:
            self.temperature = 100
        elif self.temperature + change < 0:
            self.temperature = 0
        else:
            self.temperature += change

    def adjust_humidity(self, change):
        if self.humidity + change > 100:
            self.humidity = 100
        elif self.humidity + change < 0:
            self.humidity = 0
        else:
            self.humidity += change

    def is_rainy_day(self):
        return self.humidity > 70 and self.temperature < 50",

