class SalesData:
    def __init__(self, base_price, discount_rate):
        self.base_price = base_price
        self.discount_rate = discount_rate
        self.sales_price = self.calculate_final_price()

    def calculate_final_price(self):
        if self.discount_rate > 0:
            return self.base_price * (1 - self.discount_rate / 100)
        else:
            return self.base_price

    def apply_promotion(self, bonus_discount):
        self.discount_rate += bonus_discount
        self.sales_price = self.calculate_final_price()

def main():
    item = SalesData(200, 10)
    print(f"Initial sales price: {item.sales_price}")  # Output should be 180
    item.apply_promotion(5)
    print(f"New sales price: {item.sales_price}")  # Output should be 171

main()
