class Car:
  def __init__(self, brand, is_electric):
    self.brand = brand
    self.is_electric = is_electric
    self.speed = 0

  def start_engine(self):
    if self.is_electric:
      self.sound = 'Whirring'
    else:
      self.sound = 'Vroom'

  def increase_speed(self, increment):
    self.speed += increment
    if self.speed > 100:
      self.speed = 100

# Usage
