import random

def check_stock(item, threshold=10):
    if inventory[item] < threshold:
        return True
    else:
        return False

inventory = {'apples': 20, 'oranges': 5}
threshold_value = 15
need_restock = check_stock('oranges', threshold=threshold_value)

if need_restock:
    inventory['oranges'] += 25
else:
    inventory['oranges'] += 10

order_cancelled = random.choice([True, False])
if order_cancelled:
    inventory['oranges'] -= 5
",

