class TrafficSystem:
    def __init__(self, initial_green_light='North-South'):
        self.green_light = initial_green_light
        self.cars_waiting = {'North-South': 0, 'East-West': 0}

    def car_arrives(self, direction):
        self.cars_waiting[direction] += 1

    def switch_light(self):
        if self.green_light == 'North-South':
            self.green_light = 'East-West'
        else:
            self.green_light = 'North-South'

    def clear_cars(self):
        cleared_cars = self.cars_waiting[self.green_light]
        self.cars_waiting[self.green_light] = 0
        return cleared_cars
",

