class InvestmentAnalysis { 
  int initialInvestment; 
  double growthRate; 
  public InvestmentAnalysis(int investment, double rate) { 
    initialInvestment = investment; 
    growthRate = rate; 
  } 
  public int calculateGrowth(int years) { 
    double value = initialInvestment; 
    for (int y = 0; y < years; y++) { 
      value *= (1 + growthRate); 
    } 
    return (int)value; 
  } 
}",

