class Weather:
    def __init__(self, temperature, humidity):
        self.temperature = temperature
        self.humidity = humidity

    def feels_like(self):
        adjustment = 0
        if self.humidity > 70:
            adjustment = 5
        elif self.humidity < 30:
            adjustment = -3
        return self.temperature + adjustment

    def weather_status(self):
        feels = self.feels_like()
        if feels >= 30:
            return "Hot"
        elif feels <= 10:
            return "Cold"
        else:
            return "Moderate"

# Sample instances
weather1 = Weather(25, 80)
status1 = weather1.weather_status()
""",

