def adjust_temperature(current_temperature, desired_temperature):
    if current_temperature < desired_temperature:
        return 'increase', desired_temperature - current_temperature
    elif current_temperature > desired_temperature:
        return 'decrease', current_temperature - desired_temperature
    else:
        return 'maintain', 0

def control_system(temperature_reading, set_point):
    action, adjustment = adjust_temperature(temperature_reading, set_point)
    if action == 'increase':
        heating_system(adjustment)
    elif action == 'decrease':
        cooling_system(adjustment)
    else:
        maintain_temperature()

def heating_system(degrees):
    print(f'Heating by {degrees} degrees.')

def cooling_system(degrees):
    print(f'Cooling by {degrees} degrees.')

def maintain_temperature():
    print('Temperature is optimal.')",

