class InvestmentStrategy:
    def __init__(self, initial_investment):
        self.investment = initial_investment
        self.market_trend = 'neutral'

    def adjust_investment(self, market_condition):
        if market_condition == 'bull':
            self.investment *= 1.1
        elif market_condition == 'bear':
            self.investment *= 0.9

    def predict_market(self, economic_indicators):
        if economic_indicators['interest_rate'] > 0.05:
            self.market_trend = 'bear'
        elif economic_indicators['gdp_growth'] > 3:
            self.market_trend = 'bull'
        else:
            self.market_trend = 'neutral'

    def invest_more(self, additional_amount):
        self.investment += additional_amount
        self.adjust_investment(self.market_trend)",

