class Classroom(object):
    def __init__(self, students, teacher):
        self.students = students
        self.teacher = teacher

    def class_begins(self):
        self.teacher.present_lesson()

    def quiz_given(self, questions):
        self.students.answer_questions(questions)
        if len(questions) > 5:
            for student in self.students:
                student.stress_level += 1
            self.teacher.evaluate_performance(self.students)

class Teacher(object):
    def __init__(self, name):
        self.name = name

    def present_lesson(self):
        print("Lesson presented")

    def evaluate_performance(self, students):
        for student in students:
            if student.stress_level > 2:
                print(f"{student.name} needs support.")

