{
    "code_snippet": """
    class WeatherSimulator {
      private int temperature;
      private boolean isRaining;

      public WeatherSimulator() {
        temperature = 20; // Celsius
        isRaining = false;
      }

      public void updateWeather(int day) {
        if (day % 7 == 0) {
          isRaining = !isRaining;
        }
        if (isRaining) {
          temperature -= 2; // Temperature drops by 2 degrees if it's raining
        } else {
          temperature += 1; // Temperature rises by 1 degree if it's not raining
        }
      }

      public boolean willItRainTomorrow(int day) {
        return day % 7 == 0 ? !isRaining : isRaining;
      }

      public int getTemperature() {
        return temperature;
      }
    }
    """
