class StoreManagement {
  private int totalSales = 0;
  private int numTransactions = 0;

  public void recordSale(int amount) {
     this.totalSales += amount;
     this.numTransactions++;
  }

  public float calculateAverageSale() {
     return (numTransactions > 0) ? (float) totalSales / numTransactions : 0;
  }

  public void applyDiscount(int discountRate) {
    totalSales -= (totalSales * discountRate / 100);
  }
}",

