    private int age;
    private boolean hasChronicDisease;

    public HealthSystem(boolean insurance, int age, boolean chronicDisease) {
      this.hasInsurance = insurance;
      this.age = age;
      this.hasChronicDisease = chronicDisease;
    }

    public boolean isEligibleForPremiumCare() {
      if (hasInsurance && age > 65) {
        return true;
      } else if (hasInsurance && hasChronicDisease) {
        return true;
      } else {
        return false;
      }
    }

    public boolean isAtRisk() {
      if (age > 65 || hasChronicDisease) {
        return true;
      } else {
        return false;
      }
    }
  }
