    temperature = temp;
    isRaining = false;
    isSunny = temperature > 20;
  }

  void startRain(){
    isRaining = true;
    isSunny = false;
  }

  void stopRain(){
    isRaining = false;
    isSunny = temperature > 20;
  }

  void increaseTemperature(int increment){
    temperature += increment;
    isSunny = temperature > 20;
  }

  void decreaseTemperature(int decrement){
    temperature -= decrement;
    isSunny = temperature > 20;
  }

}",

class WeatherSimulator {
    bool rain = false;
    double temperature = 20.0; // Celsius

    void adjustWeather(bool cloudy, double humidity) {
        if (cloudy && humidity > 50) {
            rain = true;
            temperature -= 5;
        } else {
            rain = false;
            if (humidity < 30) temperature += 3;
        }
    }

    String report() {
        return "Rain: " + rain + ", Temperature: " + temperature + "C";
    }
}",

