class SalesAnalysis { 
    constructor(data) { 
        this.salesData = data; 
    } 
    analyzeTrends() { 
        this.totalSales = this.salesData.reduce((sum, record) => sum + record.amount, 0); 
        return this.salesData.every(record => record.amount > 0) ? 'Profit' : 'Loss'; 
    } 
    implementStrategy(action) { 
        if (action === 'Increase Prices') { 
            this.salesData = this.salesData.map(record => ({...record, amount: record.amount * 1.1})); 
        } else if (action === 'Reduce Prices') { 
            this.salesData = this.salesData.map(record => ({...record, amount: record.amount * 0.9})); 
        } 
    } 
}",

