class TemperatureController:
    def __init__(self, threshold):
        self.threshold = threshold
        self.temperature = 25  # Default temperature in Celsius
        self.is_heating_on = False

    def update_temperature(self, external_temp):
        if external_temp < self.threshold:
            self.is_heating_on = True
            self.temperature += 2  # Simulate heating effect
        else:
            self.is_heating_on = False
            self.temperature -= 1  # Simulate cooling effect

    def reset(self):
        self.temperature = 25
        self.is_heating_on = False",

