import random

def stress_level(temperature):
    if temperature > 30:
        return 'high'
    elif temperature > 20:
        return 'medium'
    else:
        return 'low'

def air_quality(index):
    if index > 150:
        return 'poor'
    elif index > 80:
        return 'moderate'
    else:
        return 'good'

def productivity(stress, air_quality):
    if stress == 'high' or air_quality == 'poor':
        return 'low'
    elif stress == 'medium' and air_quality == 'moderate':
        return 'medium'
    else:
        return 'high'

# Main program execution
# Simulation of environmental factors
temperature = random.randint(15, 35)
aqi_index = random.randint(50, 200)

# Determine stress level and air quality
current_stress = stress_level(temperature)
current_air_quality = air_quality(aqi_index)

# Calculate productivity
current_productivity = productivity(current_stress, current_air_quality)
""",

