def process_data(data, factor, method):
    if method == 'normalize':
        max_value = max(data)
        normalized = [x / max_value * factor for x in data]
        return normalized
    elif method == 'standardize':
        mean = sum(data) / len(data)
        std_dev = (sum((x - mean) ** 2 for x in data) / len(data)) ** 0.5
        standardized = [(x - mean) / std_dev * factor for x in data]
        return standardized
    else:
        return data",

