  private int temperature;
  private boolean isRaining;

  public WeatherSimulator(int temperature, boolean isRaining) {
    this.temperature = temperature;
    this.isRaining = isRaining;
  }

  public boolean isCold() {
    return temperature < 50;
  }

  public void increaseTemperature(int increaseBy) {
    temperature += increaseBy;
  }

  public boolean startRain() {
    if (!isRaining && temperature < 60) {
      isRaining = true;
    }
    return isRaining;
  }

  public static void main(String[] args) {
    WeatherSimulator simulator = new WeatherSimulator(40, false);
    simulator.increaseTemperature(20);
    boolean raining = simulator.startRain();
    System.out.println("Is it cold? " + simulator.isCold());
    System.out.println("Is it raining? " + raining);
  }
}"
  },

