def calculate_salary(hours_worked, rate_per_hour, bonus, is_overtime): 
    if is_overtime: 
        overtime_hours = hours_worked - 40 
        hourly_rate = 1.5 * rate_per_hour 
        total_pay = 40 * rate_per_hour + overtime_hours * hourly_rate + bonus 
    else: 
        total_pay = hours_worked * rate_per_hour + bonus 
    return total_pay",

