class Car:
    def __init__(self, fuel_level, engine_status):
        self.fuel_level = fuel_level
        self.engine_status = engine_status

    def start_engine(self):
        if self.fuel_level > 0:
            self.engine_status = 'running'
        else:
            self.engine_status = 'stopped'

class Driver:
    def __init__(self, age, has_license):
        self.age = age
        self.has_license = has_license

    def drive_car(self, car):
        if self.has_license and car.engine_status == 'running':
            return 'driving'
        return 'cannot drive'

