class Simulation: 
    def __init__(self, initial_population): 
        self.population = initial_population 
        self.resource = self.population * 2 
        self.pollution = self.population * 0.1 
    def develop(self, years): 
        for _ in range(years): 
            self.population *= 1.05 
            self.resource *= 0.9 
            self.pollution += self.population * 0.05 
    def introduce_policy(self, pollution_reduction_factor): 
        self.pollution *= pollution_reduction_factor 
        self.resource += self.pollution",

