class TemperatureController {
  double temperature;
  boolean heaterOn;
  boolean windowOpen;

  TemperatureController(double initialTemp) {
    temperature = initialTemp;
    heaterOn = false;
    windowOpen = false;
  }

  void updateTemperature() {
    if (heaterOn) {
      temperature += 5;
    }
    if (windowOpen) {
      temperature -= 3;
    }
  }

  void interveneHeater(boolean state) {
    heaterOn = state;
  }

  void interveneWindow(boolean state) {
    windowOpen = state;
  }
}",

