    class HealthSystem {
      int patientCount = 0;
      boolean fluSeason = false;

      void increasePatientCount(int newPatients) {
        patientCount += newPatients;
        if (fluSeason) {
          patientCount += newPatients * 0.2; // 20% increase during flu season
        }
      }

      void setFluSeason(boolean isInFluSeason) {
        fluSeason = isInFluSeason;
      }

      void vaccinate(int percentage) {
        if (fluSeason) {
          patientCount -= Math.floor(patientCount * (percentage / 100.0) * 0.3);
        }
      }
    }
  `,

