    private int totalSales = 0;
    private int discountThreshold = 100;
    private boolean discountActive = false;

    public void makePurchase(int purchaseAmount) {
        if (purchaseAmount >= discountThreshold) {
            discountActive = true;
        }
        if (discountActive) {
            purchaseAmount *= 0.9;
        }
        totalSales += purchaseAmount;
    }

    public int getTotalSales() {
        return totalSales;
    }

    public boolean isDiscountActive() {
        return discountActive;
    }

    public void setDiscountThreshold(int threshold) {
        discountThreshold = threshold;
    }
}",

