class HealthMonitor:
    def __init__(self, age):
        self.age = age
        self.heart_rate = 70

    def update_heart_rate(self, activity_level):
        if activity_level == 'high':
            self.heart_rate += 20
        elif activity_level == 'medium':
            self.heart_rate += 10
        else:
            self.heart_rate += 0

    def drink_coffee(self):
        self.heart_rate += 5

    def take_medicine(self, medicine_type):
        if medicine_type == 'beta_blocker':
            self.heart_rate -= 10
        elif medicine_type == 'placebo':
            self.heart_rate += 0
",

