def inventory_update(stock, shipment):
    updated_stock = stock.copy()
    for item, quantity in shipment.items():
        if item in updated_stock:
            updated_stock[item] += quantity
        else:
            updated_stock[item] = quantity
    return updated_stock

stock = {'apples': 20, 'oranges': 15}
shipment = {'apples': 10, 'bananas': 5, 'oranges': -5}
result = inventory_update(stock, shipment)",

