import random

def weather_condition():
    conditions = ['sunny', 'rainy', 'cloudy']
    return random.choice(conditions)

def decide_outfit(weather):
    if weather == 'sunny':
        return 't-shirt'
    elif weather == 'rainy':
        return 'raincoat'
    else:
        return 'sweater'

def activity(plan, outfit):
    if outfit == 'raincoat':
        return 'going to the cinema'
    elif plan == 'outdoor' and outfit != 'raincoat':
        return 'hiking'
    else:
        return 'visiting a museum'

# Setting a fixed plan
fixed_plan = 'outdoor'

# Invoking the code
current_weather = weather_condition()
chosen_outfit = decide_outfit(current_weather)
today_activity = activity(fixed_plan, chosen_outfit)
""",

