class Device:
    def __init__(self, temperature):
        self.temperature = temperature
        self.performance = 100
        self.maintenance_status = False

    def update_performance(self):
        if self.temperature > 75:
            self.performance -= 20
        elif self.temperature < 30:
            self.performance -= 10

    def maintenance_check(self):
        self.maintenance_status = True
        if self.temperature > 75:
            self.performance += 10
        elif self.temperature < 30:
            self.performance += 5

# Example usage
myDevice = Device(80)
myDevice.update_performance()
myDevice.maintenance_check()",

