class HeatingSystem: 
    def __init__(self, temp_outside): 
        self.temp_outside = temp_outside 
        self.heater_on = False 

    def adjust_temperature(self, desired_temp): 
        if self.temp_outside < desired_temp: 
            self.heater_on = True 
        else: 
            self.heater_on = False 

