class WeatherSimulator {
  int temperature;
  bool isRainy;
  bool isHoliday;

  WeatherSimulator(int temp, bool rain) {
    temperature = temp;
    isRainy = rain;
    isHoliday = determineHoliday(temp);
  }

  bool determineHoliday(int temp) {
    if (temp > 30) return false;
    return true;
  }

  bool shouldBringUmbrella() {
    return isRainy && temperature < 25;
  }
}",

