class WarehouseManagementSystem { 
                     private int stock;
                     private boolean orderPlaced;

                     public WarehouseManagementSystem() {
                         stock = 50;
                         orderPlaced = false;
                     }

                     void orderStock(int orderAmount) {
                         if(stock < 20) {
                             stock += orderAmount;
                             orderPlaced = true;
                         }
                     }

                     void sellItem(int itemsSold) {
                         if (stock >= itemsSold) {
                             stock -= itemsSold;
                             if (stock < 20 && !orderPlaced)
                                 orderStock(30);
                         }
                     }

                     int checkStock() {
                         return stock;
                     }

                     boolean isOrderPlaced() {
                         return orderPlaced;
                     }
                 }",

