class TemperatureController:
    def __init__(self):
        self.temperature = 20  # Default room temperature in Celsius
        self.heater_on = False  # Indicates if the heater is on

    def update_temperature(self, external_temp, heater_override=None):
        if heater_override is not None:
            if heater_override:
                self.temperature += 3  # Heater effect
            else:
                self.temperature -= 1  # Cooling effect when heater is off
        else:
            if self.heater_on:
                self.temperature += 2  # Normal heating
            else:
                self.temperature -= 0.5  # Natural cooling

        # Adjust based on external temperature
        if external_temp < 0:
            self.temperature -= 2  # Extra cooling in freezing weather
        elif external_temp > 30:
            self.temperature += 1  # Minimal effect in hot weather

        self.temperature = round(self.temperature, 1)  # Round to 1 decimal place

    def toggle_heater(self):
        self.heater_on = not self.heater_on
        return self.heater_on
""",

