class HealthApp:
    def __init__(self):
        self.active = False
        self.steps_count = 0
        self.heart_rate = 60

    def start_activity(self):
        self.active = True
        self.adjust_heart_rate()

    def stop_activity(self):
        self.active = False
        self.heart_rate = 60

    def increment_steps(self):
        if self.active:
            self.steps_count += 1
            self.adjust_heart_rate()

    def adjust_heart_rate(self):
        if self.active:
            self.heart_rate = 80 + self.steps_count // 100
        else:
            self.heart_rate = 60

    def get_heart_rate(self):
        return self.heart_rate

    def reset_steps(self):
        self.steps_count = 0
        if self.active:
            self.adjust_heart_rate()
  """,

