class ShoppingCart:
    def __init__(self):
        self.items = []

    def add_item(self, item_price):
        self.items.append(item_price)

    def calculate_total(self):
        if not self.items:
            return 0
        discount = 0.1 if sum(self.items) > 100 else 0
        total = sum(self.items) - (sum(self.items) * discount)
        return total

    def apply_discount_code(self, discount_code):
        if discount_code == 'SAVE20':
            self.items = [price * 0.8 for price in self.items]

shop_cart = ShoppingCart()
shop_cart.add_item(50)
shop_cart.add_item(80)
shop_cart.apply_discount_code('SAVE20')
final_total = shop_cart.calculate_total()",

class WeatherStation {
    private int temperature;
    private boolean isRaining;

    public WeatherStation(int temperature, boolean isRaining) {
        this.temperature = temperature;
        this.isRaining = isRaining;
    }

    public void updateWeather(int newTemperature, boolean newRainStatus) {
        if (newRainStatus && newTemperature < 15) {
            this.isRaining = true;
            this.temperature = newTemperature;
        } else if (!newRainStatus) {
            this.isRaining = false;
            this.temperature = Math.max(newTemperature, 20);
        }
    }

    public boolean willItRain() {
        return this.isRaining && this.temperature < 20;
    }

    public void artificialChange(boolean useHeater) {
        if (useHeater) {
            this.temperature += 5;
        }
    }
}",

