class WeatherStation {
    private int temperature;
    private boolean isRaining;

    public WeatherStation(int temperature, boolean isRaining) {
        this.temperature = temperature;
        this.isRaining = isRaining;
    }

    public void updateWeather(int newTemperature, boolean newRainStatus) {
        if (newRainStatus && newTemperature < 15) {
            this.isRaining = true;
            this.temperature = newTemperature;
        } else if (!newRainStatus) {
            this.isRaining = false;
            this.temperature = Math.max(newTemperature, 20);
        }
    }

    public boolean willItRain() {
        return this.isRaining && this.temperature < 20;
    }

    public void artificialChange(boolean useHeater) {
        if (useHeater) {
            this.temperature += 5;
        }
    }
