import random

def adjust_temperature(season):
    if season == 'winter':
        return random.uniform(0, 10)
    elif season == 'summer':
        return random.uniform(25, 35)
    else:
        return random.uniform(15, 25)

def determine_clothing(temperature):
    if temperature < 15:
        return 'coat'
    elif temperature > 25:
        return 't-shirt'
    else:
        return 'jacket'

def get_activity(season):
    if season == 'winter':
        return 'skiing'
    elif season == 'summer':
        return 'swimming'
    else:
        return 'hiking'

season = 'winter'
temperature = adjust_temperature(season)
clothing = determine_clothing(temperature)
activity = get_activity(season)",

