import random

class WeatherSimulator:
    def __init__(self):
        self.temperature = 25  # Starting temperature in Celsius
        self.is_sunny = True
        self.wind_speed = 5  # Starting wind speed in km/h

    def update_weather(self):
        if self.is_sunny:
            self.temperature += random.randint(0, 5)
        else:
            self.temperature -= random.randint(0, 5)

        if self.wind_speed > 20:
            self.is_sunny = False
        elif self.wind_speed < 5:
            self.is_sunny = True

        self.wind_speed += random.randint(-2, 2)

    def change_wind_speed(self, new_speed):
        self.wind_speed = new_speed
        if new_speed > 25:
            self.is_sunny = False
        elif new_speed < 20:
            self.is_sunny = True

simulator = WeatherSimulator()
simulator.update_weather()
print("Temperature:", simulator.temperature)
print("Is it sunny?", 'Yes' if simulator.is_sunny else 'No')
print("Wind speed:", simulator.wind_speed)
""",

