def compute_sales(sale_items, discount_applied, holiday_season):
    if holiday_season:
        discount = 0.25
        if discount_applied:
            total_sales = sum(item['price'] * (1 - discount) for item in sale_items)
        else:
            total_sales = sum(item['price'] for item in sale_items)
    else:
        if discount_applied:
            total_sales = sum(item['price'] * 0.9 for item in sale_items)
        else:
            total_sales = sum(item['price'] for item in sale_items)
    return total_sales",

