def update_users(active_users, transactions, year):
    updated_users = set()
    for user in active_users:
        user_transactions = [t for t in transactions if t['user_id'] == user and t['year'] == year]
        revenue = sum(t['amount'] for t in user_transactions)
        if revenue > 5000:
            updated_users.add(user)
    return updated_users",

