class OnlineStore:
    def __init__(self, products):
        self.inventory = {product['name']: product['stock'] for product in products}
        self.sales = 0

    def purchase(self, product_name, quantity):
        if self.inventory[product_name] >= quantity:
            self.inventory[product_name] -= quantity
            self.sales += quantity * 10  # Assume each product costs $10
            return True
        return False

    def restock(self, product_name, additional_stock):
        if product_name in self.inventory:
            self.inventory[product_name] += additional_stock
            return True
        return False

# Example Data Flow:
products = [{'name': 'Laptop', 'stock': 30}, {'name': 'Phone', 'stock': 50}]
store = OnlineStore(products)
store.purchase('Laptop', 5)
store.restock('Phone', 10)
"""
  },

