class RetailStore:
    def __init__(self):
        self.stock = 100
        self.sales = 0
        self.discount = 0

    def apply_discount(self, percentage):
        self.discount = percentage
        if self.stock > 0:
            self.increase_sales()

    def increase_sales(self):
        if self.discount > 20:
            self.sales += 10
        else:
            self.sales += 5

