class ShoppingBasket {
  constructor() {
    this.items = [];
    this.total = 0;
  }
  addItem(item, price) {
    this.items.push({item: item, price: price});
    this.updateTotal();
  }
  removeItem(itemName) {
    this.items = this.items.filter(item => item.item !== itemName);
    this.updateTotal();
  }
  updateTotal() {
    this.total = this.items.reduce((sum, item) => sum + item.price, 0);
  }
  applyDiscount(code) {
    if (code === '10OFF') {
      this.total *= 0.9;
    }
  }
}",

