import random

class Environment:
    def __init__(self, pollution_level, weather):
        self.pollution_level = pollution_level
        self.weather = weather

class Health:
    def __init__(self, person):
        self.person = person
        self.diseases = []

    def update_health(self, environment):
        if environment.pollution_level > 70 and environment.weather == 'poor':
            if 'respiratory issues' not in self.diseases:
                self.diseases.append('respiratory issues')
            self.person.energy -= 20
        elif environment.pollution_level <= 70 and 'respiratory issues' in self.diseases:
            self.diseases.remove('respiratory issues')
            self.person.energy += 10

