class TemperatureRegulator:
    def __init__(self, temperature):
        self.temperature = temperature
        self.heater_on = False
    def update_temperature(self, external_temp):
        if external_temp < 18:
            self.heater_on = True
        else:
            self.heater_on = False
        if self.heater_on:
            self.temperature += 2
        else:
            self.temperature -= 1",

