class Account:
    def __init__(self, balance=0, status='standard', reward_points=0):
        self.balance = balance
        self.status = status
        self.reward_points = reward_points

    def deposit(self, amount):
        self.balance += amount
        if self.balance > 10000:
            self.status = 'premium'
        if self.balance > 5000:
            self.reward_points += 100

    def withdraw(self, amount):
        if amount > self.balance:
            return 'Insufficient funds'
        self.balance -= amount
        if self.balance < 2000:
            self.status = 'basic'

    def calculate_rewards(self):
        if self.status == 'premium':
            self.reward_points += 200
        elif self.status == 'standard':
            self.reward_points += 50
        return self.reward_points
