def weather_impact(weather, season):
    if weather == 'rainy' and season == 'winter':
        return 'snowy'
    elif weather == 'sunny' and season == 'summer':
        return 'hot'
    elif weather == 'cloudy' or (weather == 'rainy' and season == 'summer'):
        return 'cool'
    else:
        return 'mild'",

