# Code to manage inventory and sales
class InventoryManager:
    def __init__(self):
        self.inventory = {"apple": 50, "banana": 30, "orange": 20}
        self.sales_record = {}

    def sell_item(self, item, quantity):
        if item in self.inventory:
            if self.inventory[item] >= quantity:
                self.inventory[item] -= quantity
                if item in self.sales_record:
                    self.sales_record[item] += quantity
                else:
                    self.sales_record[item] = quantity
                return True
            else:
                return False
        return False

    def restock_item(self, item, quantity):
        if item in self.inventory:
            self.inventory[item] += quantity
            return True
        else:
            self.inventory[item] = quantity
            return True

inventoryManager = InventoryManager()
inventoryManager.sell_item("apple", 10)
inventoryManager.restock_item("banana", 20)
"""
