def update_data(data, factor, mode='replace'): 
  if mode == 'replace':
    return {k: v * factor for k, v in data.items()}
  elif mode == 'incremental':
    return {k: v + factor for k, v in data.items()}

data = {'A': 5, 'B': 10}
updated_data = update_data(data, 2)
data_effect = update_data(data, 10, 'incremental')",

