class WeatherSimulator {
  int temperature;
  String weatherCondition;

  WeatherSimulator(int temperature) {
    this.temperature = temperature;
    this.weatherCondition = determineWeather(temperature);
  }

  String determineWeather(int temperature) {
    if (temperature < 0) return 'Snow';
    else if (temperature >= 0 && temperature < 20) return 'Cold';
    else if (temperature >= 20 && temperature < 30) return 'Mild';
    else return 'Hot';
  }

  void setTemperature(int newTemp) {
    this.temperature = newTemp;
    this.weatherCondition = determineWeather(newTemp);
  }
}

WeatherSimulator ws = new WeatherSimulator(15);",

