    class Market {
      constructor() {
        this.demand = 100;
        this.supply = 100;
      }

      increasePrice() {
        this.supply += 10;
        this.demand -= 30;
      }

      decreasePrice() {
        this.supply -= 10;
        this.demand += 30;
      }

      addPromotion() {
        this.demand += 20;
        this.demand -= this.supply * 0.1;
