class Server {
    constructor() {
        this.requestsHandled = 0;
        this.serverLoad = 'Low';
    }
    handleRequest(request) {
        this.requestsHandled++;
        if (this.requestsHandled > 50) {
            this.serverLoad = 'High';
        }
        return 'Request Handled';
    }
}

class Database {
    constructor() {
        this.connections = 0;
        this.dataLoad = 'Low';
    }
    openConnection() {
        this.connections++;
        if (this.connections > 100) {
            this.dataLoad = 'High';
        }
    }
}

function simulateActivity(server, database) {
    for (let i = 0; i < 60; i++) {
        server.handleRequest('NewRequest');
        if (i % 5 == 0) {
            database.openConnection();
        }
    }
}",

