    class Product:
        def __init__(self, price, discount_strategy=None):
            self.price = price
            self.discount_strategy = discount_strategy

        def apply_discount(self):
            if self.discount_strategy:
                return self.discount_strategy(self.price)
            else:
                return self.price

    def no_discount(price):
        return price

    def percentage_discount(price, percent=10):
        return price * (100 - percent) / 100

    # Apply strategy pattern
    product_without_discount = Product(200, no_discount)
    product_with_discount = Product(200, lambda price: percentage_discount(price, 20))
    final_price_no_discount = product_without_discount.apply_discount()
    final_price_with_discount = product_with_discount.apply_discount()
  `,

