class Vehicle:
    def __init__(self, fuel_level=100):
        self.fuel_level = fuel_level

    def drive(self):
        if self.fuel_level > 0:
            self.fuel_level -= 10
            return 'Driving!'
        else:
            return 'Out of fuel!'

class ElectricVehicle(Vehicle):
    def charge(self):
        self.fuel_level = 100

