{
    "python_code": "class TrafficSimulation:
  def __init__(self, red_light_duration, green_light_duration):
      self.red_light_duration = red_light_duration
      self.green_light_duration = green_light_duration

  def update_traffic_light(self, current_state):
      if current_state == 'red':
          return 'green', self.green_light_duration
      else:
          return 'red', self.red_light_duration

  def manage_traffic(self, elapsed_time, current_light):
      time_for_change = self.red_light_duration if current_light == 'red' else self.green_light_duration
      if elapsed_time >= time_for_change:
          new_light, duration = self.update_traffic_light(current_light)
          return new_light, 0
      else:
          return current_light, time_for_change - elapsed_time"
  },

