if weather_condition == 'sunny':
    mood = 'good'
elif weather_condition == 'rainy':
    mood = 'depressed'
else:
    mood = 'neutral'

if traffic_condition == 'heavy':
    stress_level = 'high'
elif traffic_condition == 'moderate':
    stress_level = 'medium'
else:
    stress_level = 'low'

if mood == 'good' and coffee_consumed > 1:
    work_performance = 'excellent'
elif mood != 'good' and coffee_consumed < 2:
    if stress_level == 'high':
        work_performance = 'poor'
    else:
        work_performance = 'average'
else:
    work_performance = 'good'

print("Today's work performance is:", work_performance)
