{
    "script": "
    class PaymentSystem:
        def __init__(self, initial_balance=100):
            self.balance = initial_balance

        def purchase_item(self, price, discount=0):
            if discount > 0:
                final_price = price - (price * (discount / 100))
            else:
                final_price = price
            if self.balance >= final_price:
                self.balance -= final_price
                return True
            return False

        def refund_item(self, price, discount=0):
            if discount > 0:
                refund_amount = price - (price * (discount / 100))
            else:
                refund_amount = price
            self.balance += refund_amount

    # Example usage
    payment_system = PaymentSystem(500)
    transaction_1 = payment_system.purchase_item(150)
    payment_system.refund_item(150)
    "
