def sales_discount(prices, discount_rate=0.1): 
    discounted_prices = [] 
    for price in prices: 
        if price >= 50: 
            new_price = price - price * discount_rate 
            discounted_prices.append(new_price) 
        else: 
            discounted_prices.append(price) 
    return discounted_prices",

