class EconomySystem {
  int taxRate;
  double govSpending;
  double gdp;

  EconomySystem(int taxRate) {
    this.taxRate = taxRate;
    this.govSpending = calculateSpending(taxRate);
    this.gdp = calculateGDP(taxRate, govSpending);
  }

  double calculateSpending(int taxRate) {
    return taxRate * 1000.0;
  }

  double calculateGDP(int taxRate, double spending) {
