class Patient:
    def __init__(self, age):
        self.age = age
        self.blood_pressure = 120

    def update_blood_pressure(self, stress_level):
        self.blood_pressure += stress_level * 0.5

    def apply_medication(self, reduce_factor):
        self.blood_pressure -= reduce_factor

def visit_doctor(patient, stress_level):
    patient.update_blood_pressure(stress_level)
    if patient.blood_pressure > 140:
        patient.apply_medication(20)

# Example usage:
bob = Patient(54)
visit_doctor(bob, 50)
