class OrderManager:
    def __init__(self):
        self.orders = []
        self.is_holiday = False

    def add_order(self, customer, item):
        if self.is_holiday:
            print('Cannot process orders on holidays.')
        else:
            self.orders.append((customer, item))
            print(f'Order added for {customer}: {item}')

    def check_holiday_and_notify(self):
        if self.is_holiday:
            return 'Today is a holiday, no orders will be processed.'
        else:
            return 'Orders will be processed today.'

    def process_orders(self):
        if not self.is_holiday:
            for order in self.orders:
                # Simulate sending order details to warehouse for processing
                print(f'Processing order for {order[0]}: {order[1]}')
            self.orders.clear()
        else:
            print('Cannot process orders, today is a holiday.')
