class HealthMonitor(object):
    def __init__(self, age, smoker_status):
        self.age = age
        self.smoker_status = smoker_status
        self.health_risk = 'Unknown'

    def update_health_risk(self):
        if self.age > 50 and self.smoker_status == 'smoker':
            self.health_risk = 'High'
        elif self.age <= 50 and self.smoker_status == 'smoker':
            self.health_risk = 'Medium'
        elif self.age > 50 and self.smoker_status == 'non-smoker':
            self.health_risk = 'Low'
