class HealthSystem {
  constructor(age, smoker) {
    this.age = age;
    this.smoker = smoker;
    this.healthScore = 100;
    this.updateHealthScore();
  }

  updateHealthScore() {
    if (this.smoker) {
      this.healthScore -= 20;
    }
    if (this.age > 50) {
      this.healthScore -= 30;
    }
  }

  applyMedication() {
    if (this.smoker) {
      this.healthScore += 10;
    }
    if (this.age > 50) {
      this.healthScore += 5;
    }
  }

  quitSmoking() {
    if (this.smoker) {
      this.smoker = false;
      this.healthScore += 10;
    }
  }
}",

