class WeatherSimulator {
  public static void main(String[] args) {
    double temperature = getAverageTemperature();
    boolean isRainy = willItRain(temperature);
    int umbrellaCount = peopleCarryingUmbrellas(isRainy);
    displayWeatherReport(temperature, isRainy, umbrellaCount);
  }

  static double getAverageTemperature() {
    return 20.0; // Average temperature in degrees
  }

  static boolean willItRain(double temperature) {
    return temperature < 18.0;
  }

  static int peopleCarryingUmbrellas(boolean rainy) {
    if (rainy) return 150;
    else return 20;
  }

  static void displayWeatherReport(double temp, boolean rain, int umbrellas) {
    System.out.println("Weather Report:\
Temperature: " + temp + " degrees\
Rainy: " + rain + "\
Umbrellas Spotted: " + umbrellas);
  }
}",

