import random

class Elections:
    def __init__(self):
        self.voter_turnout = random.randint(50, 100)
        self.campaign_funds = random.randint(500, 1000)
        self.opposition_strength = random.randint(1, 10)

    def campaign_effectiveness(self):
        if self.campaign_funds > 750:
            return 'high'
        else:
            return 'medium'

    def win_election(self):
        effective = self.campaign_effectiveness()
        if effective == 'high' and self.opposition_strength <= 5:
            return True
        elif effective == 'medium' and self.voter_turnout > 75 and self.opposition_strength <= 3:
            return True
        else:
            return False

election2023 = Elections()
result = election2023.win_election()
""",

import random

class Elections:
    def __init__(self):
        self.voter_turnout = random.randint(50, 100)
