class WeatherSimulator {
  private double temperature;
  private boolean isRainy;

  public WeatherSimulator(double temperature) {
    this.temperature = temperature;
    this.isRainy = false;
  }

  public void updateWeather(double deltaTemperature, boolean useUmbrella) {
    if (useUmbrella && isRainy) {
      deltaTemperature = deltaTemperature > 0 ? -0.5 : 0.5;
    }
    this.temperature += deltaTemperature;
    checkRainCondition();
  }

  private void checkRainCondition() {
    if (temperature < 20) isRainy = true;
    else isRainy = false;
  }

  public double getTemperature() {
    return temperature;
  }

  public boolean getIsRainy() {
    return isRainy;
  }
}",

