class HealthMonitor(object):
    def __init__(self, age):
        self.age = age
        self.heart_rate = 70

    def update_age(self, new_age):
        self.age = new_age
        self.update_heart_rate_based_on_age()

    def update_heart_rate_based_on_age(self):
        if self.age > 50:
           self.heart_rate += (self.age - 50) * 0.3

    def exercise(self, intensity):
        if intensity == 'high':
            self.heart_rate += 20
        elif intensity == 'low':
            self.heart_rate += 5

    def recover(self, minutes):
        decrease_rate = 0.5 * minutes
        if self.heart_rate - decrease_rate > 60:
            self.heart_rate -= decrease_rate
        else:
            self.heart_rate = 60
",

