class HealthSystem:
    def __init__(self):
        self.patient_records = {}

    def add_patient(self, id, age):
        self.patient_records[id] = {
            'age': age,
            'has_flu': False,
            'vaccinated': False
        }

    def vaccinate_patient(self, id):
        if id in self.patient_records:
            self.patient_records[id]['vaccinated'] = True
            if self.patient_records[id]['age'] > 60:
                self.patient_records[id]['has_flu'] = False

    def diagnose_flu(self, id):
        if id in self.patient_records:
            if not self.patient_records[id]['vaccinated']:
                self.patient_records[id]['has_flu'] = True

# Example usage:
hospital = HealthSystem()
hospital.add_patient(1, 65)
hospital.vaccinate_patient(1)
hospital.diagnose_flu(1)
""",

