class ProcessManager {
    private int taskCount = 0;
    private boolean systemReady = false;

    public void initializeSystem() {
        systemReady = true;
        taskCount = 5;
    }

    public void addTasks(int newTasks) {
        taskCount += systemReady ? newTasks : 0;
    }

    public void resetSystem() {
        systemReady = false;
        taskCount = 0;
    }

    public boolean isSystemReady() {
        return systemReady;
    }

    public int getTaskCount() {
        return taskCount;
    }
}",

class ProcessManager {
    private int taskCount = 0;
    private boolean systemReady = false;

    public void initializeSystem() {
        systemReady = true;
        taskCount = 5;
    }

    public void addTasks(int newTasks) {
        taskCount += systemReady ? newTasks : 0;
    }

    public void resetSystem() {
        systemReady = false;
        taskCount = 0;
