def analyze_purchases(user, products, preference_threshold):
    total_spent = 0
    preferred_products = []
    for product in products:
        if product['price'] > preference_threshold:
            user['budget'] -= product['price']
            total_spent += product['price']
            if product['category'] in user['preferences']:
                preferred_products.append(product)
    return total_spent, preferred_products",

