class TemperatureController:
    def __init__(self, threshold):
        self.threshold = threshold
        self.temperature = 25  # Default temperature in Celsius

    def update_temperature(self, external_temp):
        if external_temp > self.threshold:
            self.temperature -= 1  # cooling mechanism
        elif external_temp < self.threshold:
            self.temperature += 1  # heating mechanism
        return self.temperature

    def modify_threshold(self, new_threshold):
        self.threshold = new_threshold

controller = TemperatureController(30)
controller.update_temperature(35)
controller.modify_threshold(25)
controller.update_temperature(20)",

