        self.budget = random.randint(1000, 5000)
        self.campaign_length = random.randint(10, 60)  # in days
        self.ad_quality = random.choice(['Low', 'Medium', 'High'])

    def estimated_reach(self):
        base_reach = self.budget * self.campaign_length
        if self.ad_quality == 'High':
            return base_reach * 1.5
        elif self.ad_quality == 'Medium':
            return base_reach * 1.2
        else:
            return base_reach * 0.8

    def actual_sales_conversion(self, market_conditions):
        estimated_sales = self.estimated_reach() * 0.02
        if market_conditions == 'Good':
            return estimated_sales * 1.1
        elif market_conditions == 'Average':
            return estimated_sales
        else:
            return estimated_sales * 0.9
""",

class WeatherSimulator {
  int temperature;
  bool isRaining;

  WeatherSimulator(int initialTemp) {
    temperature = initialTemp;
    isRaining = false;
  }

  void updateWeather() {
    if (temperature < 20) {
      isRaining = true;
    } else {
      isRaining = false;
    }
  }

  void changeTemperature(int newTemp) {
    temperature = newTemp;
    this.updateWeather();
  }
}",

