class Car:
    def __init__(self, color, engine_status='off', speed=0):
        self.color = color
        self.engine_status = engine_status
        self.speed = speed

    def start_engine(self):
        self.engine_status = 'on'
        self.speed = 0

    def stop_engine(self):
        self.engine_status = 'off'
        self.speed = 0

    def accelerate(self, increment):
        if self.engine_status == 'on':
            self.speed += increment
        else:
            print("Engine is off, cannot accelerate.")

    def decelerate(self, decrement):
        if self.engine_status == 'on' and self.speed >= decrement:
            self.speed -= decrement
        elif self.speed < decrement:
            print("Speed too low, cannot decelerate that much.")
        else:
            print("Engine is off, cannot decelerate.")

my_car = Car('red')
my_car.start_engine()
my_car.accelerate(20)
my_car.decelerate(5)
my_car.stop_engine()
""",

