class CookieManager {
  constructor() {
    this.cookies = {};
  }

  setCookie(name, value, days) {
    var expires = '';
    if (days) {
      var date = new Date();
      date.setTime(date.getTime() + (days * 24 * 60 * 60 * 1000));
      expires = 'expires=' + date.toUTCString() + ';';
    }
    document.cookie = name + '=' + value + ';' + expires + 'path=/';
  }

  getCookie(name) {
    var nameEQ = name + '=';
    var ca = document.cookie.split(';');
    for(var i = 0; i < ca.length; i++) {
      var c = ca[i].trim();
      if (c.indexOf(nameEQ) == 0) return c.substring(nameEQ.length, c.length);
    }
    return null;
  }

  deleteCookie(name) {
    this.setCookie(name, '', -1);
  }
}",

{
    "Code": "\
class SalesData {
\
  constructor() {
\
    this.sales = [];
\
  }
\
  recordSale(amount) {
\
    this.sales.push(amount);
\
  }
\
  totalSales() {
\
    return this.sales.reduce((a, b) => a + b, 0);
\
  }
\
  applyDiscount(discountRate) {
\
    this.sales = this.sales.map(sale => sale * (1 - discountRate));
\
  }
\
}
\

\
const sales = new SalesData();
\
sales.recordSale(100);
\
sales.recordSale(200);
\
sales.applyDiscount(0.1);
\
console.log(sales.totalSales());"
