class HealthTracker:
    def __init__(self):
        self.daily_water_intake = 0  # in liters
        self.daily_calories_burned = 0  # in calories

    def drink_water(self, liters):
        self.daily_water_intake += liters
        if self.daily_water_intake > 2:
            self.feel_hydrated()

    def feel_hydrated(self):
        self.is_hydrated = True

    def exercise(self, minutes):
        self.daily_calories_burned += (minutes * 10)
        if self.daily_calories_burned > 500:
            self.feel_energetic()

    def feel_energetic(self):
        self.is_energetic = True
""",

