  public void setRainStatus(boolean status) { isRaining = status; }

  public String activitySuggestion() {
    if (isRaining) return "Stay indoors";
    else return "Go hiking";
  }

  public void changeWeather() {
    isRaining = !isRaining;
  }
}",

class WeatherSystem {
