import numpy as np

class WeatherPredictor:
    def __init__(self, temperature, humidity):
        self.temperature = temperature
        self.humidity = humidity
        self.rain_likelihood = 0

    def analyze_weather(self):
        if self.temperature < 10 and self.humidity > 70:
            self.rain_likelihood = 0.75
        elif self.temperature >= 10 and self.humidity > 80:
            self.rain_likelihood = 0.50
        else:
            self.rain_likelihood = 0.10

    def intervene_temperature(self, new_temp):
        self.temperature = new_temp
        self.analyze_weather()

    def intervene_humidity(self, new_hum):
        self.humidity = new_hum
        self.analyze_weather()

predictor = WeatherPredictor(15, 65)
",

