import random

def weather_condition():
    return random.choice(['sunny', 'rainy', 'cloudy'])

def decide_on_activity(weather):
    if weather == 'sunny':
        activity = 'go to the park'
    elif weather == 'rainy':
        activity = 'watch movies'
    else:
        activity = 'visit a museum'
    return activity

def prepare_items(activity):
    if activity == 'go to the park':
        items = ['sunscreen', 'frisbee']
    elif activity == 'watch movies':
        items = ['popcorn', 'soft drinks']
    else:
        items = ['camera', 'guide book']
    return items

weather = weather_condition()
activity = decide_on_activity(weather)
necessary_items = prepare_items(activity)

