class WeatherSystem:
    def __init__(self, temperature, humidity):
        self.temperature = temperature
        self.humidity = humidity
        self.weather_status = 'sunny' if temperature > 20 else 'cold'

    def adjust_humidity(self, change):
        self.humidity += change
        if self.humidity > 70:
            self.weather_status = 'rainy'

    def set_temperature(self, temp):
        self.temperature = temp
        self.weather_status = 'sunny' if self.temperature > 20 else 'cold'
