class TemperatureControlSystem {
 private int temperature;
 private boolean heaterStatus;

 public TemperatureControlSystem() {
   temperature = 20; // Default room temperature in Celsius
   heaterStatus = false;
 }

 public void increaseTemperature() {
   if (!heaterStatus) {
     heaterStatus = true;
   }
   temperature += 5;
 }

 public void decreaseTemperature() {
   if (temperature > 5) {
     temperature -= 5;
   }
 }

 public String checkSystemState() {
   return "Temperature: " + temperature + "C, Heater Status: " + (heaterStatus ? "on" : "off");
 }
}",

