class BookStore:
    def __init__(self):
        self.inventory = {'novel': 100, 'textbook': 50, 'magazine': 80}
        self.sales = {'novel': 0, 'textbook': 0, 'magazine': 0}
        self.discount = {'novel': 0.1, 'textbook': 0.2, 'magazine': 0.05}

    def sell_item(self, item, quantity):
        if self.inventory[item] >= quantity:
            self.inventory[item] -= quantity
            self.sales[item] += quantity
            return f'Sold {quantity} {item}s'
        else:
            return 'Insufficient stock'

    def restock_item(self, item, quantity):
        self.inventory[item] += quantity
        return f'Restocked {quantity} {item}s'

    def apply_discount(self, item):
        old_price = self.get_price(item)
        new_price = old_price * (1 - self.discount[item])
        return f'Price for {item} dropped from {old_price} to {new_price}'

    def get_price(self, item):
        base_price = {'novel': 15, 'textbook': 50, 'magazine': 5}
        return base_price[item] * (1 - self.discount[item])",

