class WeatherSimulator:
    def __init__(self, temperature, humidity):
        self.temperature = temperature
        self.humidity = humidity
        self.cloud_cover = None
        self.rain_probability = 0

    def calculate_cloud_cover(self):
        if self.temperature < 20 and self.humidity > 50:
            self.cloud_cover = 'high'
        else:
            self.cloud_cover = 'low'

    def update_rain_probability(self):
        self.calculate_cloud_cover()
        if self.cloud_cover == 'high':
            self.rain_probability = 75
        elif self.humidity > 80:
            self.rain_probability = 50
        else:
            self.rain_probability = 10",

