def process_data(data, flag): 
    result = [] 
    if flag: 
        for d in data: 
            if d % 2 == 0: 
                result.append(d ** 2) 
    else: 
        for d in data: 
            if d % 2 != 0: 
                result.append(d + 1) 
    return result",

