def calculate_health_index(smoking, exercise_hours, diet_quality):
    base_health = 100
    if smoking:
        base_health -= 30
    base_health += (exercise_hours * 2)
    if diet_quality == 'good':
        base_health += 20
    elif diet_quality == 'poor':
        base_health -= 20
    return base_health",

