class WaterPump:
    def __init__(self, has_power, is_on):
        self.has_power = has_power
        self.is_on = is_on

    def start_pump(self):
        if self.has_power and not self.is_on:
            self.is_on = True
            return 'Pump Started'
        else:
            return 'Pump Cannot Start'

    def stop_pump(self):
        if self.is_on:
            self.is_on = False
            return 'Pump Stopped'
        else:
            return 'Pump is Already Off'

