class EmailSystem:
    def __init__(self):
        self.subscribers = []

    def add_subscriber(self, email):
        if email not in self.subscribers:
            self.subscribers.append(email)
            return True
        return False

    def remove_subscriber(self, email):
        if email in self.subscribers:
            self.subscribers.remove(email)
            return True
        return False

    def send_email(self):
        for email in self.subscribers:
            print(f'Sending email to {email}')
        return len(self.subscribers)",

class HealthMonitor {
   boolean isSmokeExposure;
   int dailyCigaretteCount;
   boolean isLungProblem;

   public HealthMonitor(boolean exposure, int cigarette) {
       isSmokeExposure = exposure;
       dailyCigaretteCount = cigarette;
       isLungProblem = evaluateHealth();
   }

   private boolean evaluateHealth() {
       if (isSmokeExposure && dailyCigaretteCount > 10) {
           return true; // High risk of lung problem
       }
       return false;
   }

   public void intervene() {
       dailyCigaretteCount = 0; // Quit smoking
       isLungProblem = evaluateHealth();
   }
}",

