def update_scores(scores, action, delta):
    if action == 'add':
        for i in range(len(scores)):
            scores[i] += delta
    elif action == 'multiply':
        for i in range(len(scores)):
            scores[i] *= delta
    return scores

scores_list = [10, 20, 30]
update_scores(scores_list, 'add', 5)
update_scores(scores_list, 'multiply', 2)",

