class ProductDatabase:
    def __init__(self):
        self.products = {}

    def add_product(self, product_name, price):
        if product_name not in self.products:
            self.products[product_name] = price

    def get_product_price(self, product_name):
        return self.products.get(product_name, None)

    def apply_discount(self, product_name, discount):
        if product_name in self.products:
            self.products[product_name] *= (1 - discount)

    def update_price(self, product_name, new_price):
        if product_name in self.products:
            self.products[product_name] = new_price

    def remove_product(self, product_name):
        if product_name in self.products:
            del self.products[product_name]",

