    import random

    def weather_condition():
        conditions = ['sunny', 'rainy', 'cloudy']
        return random.choice(conditions)

    def traffic_jam(weather):
        if weather == 'rainy':
            return True
        elif weather == 'sunny':
            return False
        else:
            return bool(random.choice([0, 1]))

