  this.season = season; 
  initializeWeather(); 
 } 

 void initializeWeather() { 
  if (season == 1) { 
   temperature = 15; 
   isRaining = false; 
  } else if (season == 2) { 
   temperature = 30; 
   isRaining = true; 
  } else if (season == 3) { 
   temperature = 10; 
   isRaining = false; 
  } else { 
   temperature = 25; 
   isRaining = true; 
  } 
 } 

 bool updateWeather(int newSeason) { 
  season = newSeason; 
  initializeWeather(); 
  return isRaining; 
 } 
