import random

def generate_data():
    age = random.randint(20, 60)
    health_index = 100 - (age - 20) + random.randint(-10, 10)
    exercise_freq = random.randint(0, 5)
    if exercise_freq > 3:
        health_index += 5
    return {'age': age, 'health_index': health_index, 'exercise_freq': exercise_freq}

def analyze_data(person):
    if person['age'] > 40:
        risk = 'high' if person['health_index'] < 70 else 'medium'
    else:
        risk = 'low'
    return risk",

