class HealthSystem {
    private int age;
    private boolean hasChronicDisease;
    private double physicalActivityHoursPerWeek;

    public HealthSystem(int age, boolean hasChronicDisease, double physicalActivityHoursPerWeek) {
        this.age = age;
        this.hasChronicDisease = hasChronicDisease;
        this.physicalActivityHoursPerWeek = physicalActivityHoursPerWeek;
    }

    public String evaluateRisk() {
        if (age > 50 && hasChronicDisease) {
            return "High Risk";
        } else if (age > 50 || (hasChronicDisease && physicalActivityHoursPerWeek < 2)) {
            return "Moderate Risk";
        } else if (physicalActivityHoursPerWeek >= 3) {
            return "Low Risk";
        } else {
            return "Normal Risk";
        }
    }
}
""",

