class InvestmentPortfolio:
    def __init__(self, initial_investment):
        self.funds = initial_investment

    def add_funds(self, amount):
        self.funds += amount
        self.adjust_risk_profile()

    def adjust_risk_profile(self):
        if self.funds > 100000:
            self.risk_profile = 'High'
        else:
            self.risk_profile = 'Low'

    def make_investment(self, investment_amount):
        if self.funds >= investment_amount:
            self.funds -= investment_amount
            self.investment_success = True
        else:
            self.investment_success = False

    def get_risk_profile(self):
        self.adjust_risk_profile()
        return self.risk_profile

# Create an instance of InvestmentPortfolio with an initial investment
portfolio = InvestmentPortfolio(50000)
# Add funds
portfolio.add_funds(60000)
# Make investment
portfolio.make_investment(40000)

