class WeatherSimulator {
    int temperature;
    String weatherCondition;
    boolean holiday;

    WeatherSimulator() {
        temperature = 25;  // Default temperature in Celsius
        weatherCondition = "sunny";  // Default weather condition
        holiday = false;  // Default non-holiday
    }

    void updateWeather(int newTemperature, String newCondition) {
        temperature = newTemperature;
        weatherCondition = newCondition;
    }

    void setHoliday(boolean isHoliday) {
        holiday = isHoliday;
        if (holiday && temperature > 30) {
            weatherCondition = "sunny and hot";
        }
    }

    String simulateDay() {
        if (holiday) {
            return "It's a holiday with " + weatherCondition;
        } else {
            return "Regular day with " + weatherCondition;
        }
    }
}",

