def recommend_articles(user_preferences, past_interactions, intervention=None):
    if intervention:
        user_preferences.update(intervention)

    recommendations = []
    for article in articles_database:
        score = 0
        for topic in article['topics']:
            if topic in user_preferences:
                score += user_preferences[topic]
        if article['id'] in past_interactions:
            score *= 0.8  # decrease score for already interacted articles

        recommendations.append((article, score))

    recommendations.sort(key=lambda x: x[1], reverse=True)  # Sort articles by score
    return [article for article, _ in recommendations[:3]]  # Recommend top 3 articles",

