class HealthMonitor {
    def __init__(self, age, blood_pressure):
        self.age = age
        self.blood_pressure = blood_pressure
        self.stress_level = 0

    def update_blood_pressure(self, medication, stress_level):
        if medication:
            self.blood_pressure -= 10
        if stress_level > 5:
            self.blood_pressure += 5

    def update_stress_level(self, workload, life_events):
        self.stress_level = workload + life_events

    def is_at_risk(self):
        return self.blood_pressure > 140 or self.age > 55
