`
  class HealthSimulator {
      constructor(smokerStatus, avgExerciseHours, geneticRisk) {
          this.smokerStatus = smokerStatus;   // true if smoker, false otherwise
          this.avgExerciseHours = avgExerciseHours;  // average hours of exercise per week
          this.geneticRisk = geneticRisk;  // from 0 (low) to 1 (high)
      }

      calculateLifeExpectancy() {
          let baseLifeExpectancy = 80;
          if (this.smokerStatus) {
              baseLifeExpectancy -= 10;
          }
          baseLifeExpectancy += this.avgExerciseHours;

          // Genetic risk reduces life expectancy further by up to 20%
          return baseLifeExpectancy * (1 - this.geneticRisk * 0.2);
      }
  }

  let personA = new HealthSimulator(true, 3, 0.5);
  let lifeExpectancyOfPersonA = personA.calculateLifeExpectancy();
  `,

