class HealthTracker:
    def __init__(self, initial_health):
        self.health = initial_health

    def exercise(self, duration):
        if duration > 60:
            self.health += 10
        else:
            self.health += 5

    def work(self, hours):
        if hours > 8:
            self.health -= 10
        else:
            self.health -= 5

    def relax(self, technique, time_spent):
        if technique == 'meditation':
            self.health += 15
        elif time_spent > 30:
            self.health += 8
        else:
            self.health += 3
