class Store:
    def __init__(self, inventory):
        self.inventory = inventory  # Dictionary {product: [price, quantity]}
        self.sales = 0

    def buy_product(self, product, quantity):
        if self.inventory[product][1] >= quantity:
            self.inventory[product][1] -= quantity
            self.sales += quantity * self.inventory[product][0]
            return 'Purchase successful'
        else:
            return 'Not enough inventory'

    def adjust_price(self, product, new_price):
        if self.inventory[product][1] < 10:
            self.inventory[product][0] = new_price
            return 'Price adjusted'
        else:
            return 'No adjustment needed'
",

