    if (newWeatherType === 'rainy') {
      this.umbrellaRequired = true;
    } else {
      this.umbrellaRequired = false;
    }
  }

  prepareForDay() {
    if (this.weatherType === 'sunny') {
      return 'Wear sunglasses';
    } else if (this.weatherType === 'rainy') {
      return 'Carry an umbrella';
    }
    return 'Wear appropriate clothing';
  }
}",

