class WeatherSimulator {
\
    private double temperature;
\
    private boolean isRainy;
\

\
    public WeatherSimulator(double initialTemp) {
\
      this.temperature = initialTemp;
\
      this.isRainy = false;
\
    }
\

\
    public void updateWeather(int hour) {
\
      if (hour > 12) {
\
        this.temperature -= 5;
\
      } else {
\
        this.temperature += 3;
\
      }
\
      if (this.temperature < 20) {
\
        this.isRainy = true;
\
      }
\
    }
\
  }
\

\
  public static void main(String[] args) {
\
    WeatherSimulator simulator = new WeatherSimulator(25);
\
    simulator.updateWeather(14);
\
    System.out.println("Is it rainy? " + simulator.isRainy);
\
  }
\
}",

