def update_inventory(stock, item, quantity, sold):
    if item in stock:
        if sold:
            stock[item] -= quantity
            return 'Item sold'
        else:
            stock[item] += quantity
            return 'Stock updated'
    else:
        if not sold:
            stock[item] = quantity
            return 'New item added'
        else:
            return 'Item not in stock'",

