class WeatherForecast {
    constructor(temperature, humidity, rainProbability) {
        this.temperature = temperature;
        this.humidity = humidity;
        this.rainProbability = rainProbability;
    }

    willItRain() {
        if (this.humidity > 70 && this.temperature < 20) {
            this.rainProbability = 80;
        } else if (this.humidity > 50) {
            this.rainProbability = 50;
