class WeatherSimulator {
   private int temperature;
   private boolean isRaining;

   public WeatherSimulator(int temp, boolean rain) {
       temperature = temp;
       isRaining = rain;
   }

   public void adjustWeather(int newTemp, boolean newRainStatus) {
       if (newTemp > 30) {
           isRaining = false;
       } else if (newTemp < 10) {
           isRaining = true;
       }
       temperature = newTemp;
       isRaining = newRainStatus;
   }

   public boolean checkUmbrellaNeed() {
       if (temperature < 15 && isRaining) {
           return true;
       }
       return false;
   }
}

