import random

class Weather:
    def __init__(self):
        self.temperature = random.randint(15, 35)
        self.is_raining = random.choice([True, False])

class Mood:
    def __init__(self, weather):
        if weather.is_raining:
            self.happiness = 40
        else:
            self.happiness = 70

class Productivity:
    def __init__(self, mood):
        if mood.happiness > 50:
            self.level = 'High'
        else:
            self.level = 'Medium'

# Main function
if __name__ == '__main__':
    current_weather = Weather()
    today_mood = Mood(current_weather)
    work_productivity = Productivity(today_mood)
    print(work_productivity.level)",

class ClimateControlSystem {
  private int temperature;
  private boolean airConditioningOn;

  public ClimateControlSystem() {
    this.temperature = 20; // Default temperature in Celsius
    this.airConditioningOn = false;
  }

  public void setTemperature(int newTemperature) {
    this.temperature = newTemperature;
    if(newTemperature > 25) {
      this.airConditioningOn = true;
    } else if(newTemperature < 18) {
      this.airConditioningOn = false;
    }
  }

  public int getTemperature() {
    return temperature;
  }

  public boolean isAirConditioningOn() {
    return airConditioningOn;
  }
}",

