class HealthMonitor:
    def __init__(self, initial_temp, has_sickness=False):
        self.body_temperature = initial_temp
        self.cold = False
        self.fever = False
        self.has_sickness = has_sickness

    def update_temperature(self, external_temp):
        if external_temp < 20:
            self.body_temperature -= 0.5
        elif external_temp > 30:
            self.body_temperature += 0.5

        if self.has_sickness:
            self.body_temperature += 1

        self.check_symptoms()

    def check_symptoms(self):
        if self.body_temperature < 36:
            self.cold = True
            self.fever = False
        elif self.body_temperature > 38:
            self.fever = True
            self.cold = False
        else:
            self.cold = False
            self.fever = False",

