        this.hasHealthyDiet = false;
        this.exercisesRegularly = false;
        this.healthStatus = 'poor';
      }

      updateDiet(dietType) {
        if (dietType === 'healthy') {
          this.hasHealthyDiet = true;
          this.updateHealthStatus();
        } else {
          this.hasHealthyDiet = false;
        }
      }

      updateExercise(habit) {
        this.exercisesRegularly = habit;
        this.updateHealthStatus();
      }

      updateHealthStatus() {
        if (this.hasHealthyDiet && this.exercisesRegularly) {
          this.healthStatus = 'excellent';
        } else if (this.hasHealthyDiet || this.exercisesRegularly) {
          this.healthStatus = 'good';
        } else {
          this.healthStatus = 'poor';
        }
      }
    }
