def analyze_user_activity(logs): 
    sum_purchases = 0
    num_logins = 0
    for log in logs:
        if log['action'] == 'login':
            num_logins += 1
        elif log['action'] == 'purchase':
            sum_purchases += log['amount']
    average_purchase = sum_purchases / num_logins if num_logins > 0 else 0
    return {'average_purchase': average_purchase, 'total_logins': num_logins}",

