class WeatherSimulator:
    def __init__(self, temperature, rainfall):
        self.temperature = temperature
        self.rainfall = rainfall

    def is_icy(self):
        return self.temperature < 32 and self.rainfall > 0.2

    def update_weather(self, new_temp, new_rainfall):
        self.temperature = new_temp
        self.rainfall = new_rainfall

class TrafficController:
    def __init__(self, weather):
        self.weather = weather

    def accident_risk(self):
        if self.weather.is_icy():
            return 'High'
