def update_inventory(items_sold, current_stock):
    result_stock = current_stock.copy()
    for item, quantity in items_sold.items():
        if item in result_stock:
            result_stock[item] -= quantity
        else:
            raise ValueError('Item not in stock')
    return result_stock

