class EnvironmentControlSystem {
    int targetTemperature;
    int targetHumidity;
    int currentTemperature;
    int currentHumidity;

    EnvironmentControlSystem(int temp, int hum) {
        targetTemperature = temp;
        targetHumidity = hum;
    }

    void update(int externalTemp, int externalHumidity) {
        if (externalTemp > targetTemperature) {
            currentTemperature = targetTemperature;
        } else {
            currentTemperature = externalTemp;
        }
        if (externalHumidity > targetHumidity) {
            currentHumidity = targetHumidity;
        } else {
            currentHumidity = externalHumidity;
        }
    }
}",

