import random
def determine_price(age, income):
    if age > 30:
        base_price = 100
    else:
        base_price = 50
    if income > 50000:
        adjusted_price = base_price + 20
    else:
        adjusted_price = base_price - 20
    return adjusted_price

def customer_response(price):
    satisfaction_level = random.choice(['low', 'medium', 'high'])
    if price < 80:
        return satisfaction_level == 'high'
    return satisfaction_level == 'low'

age = input('Enter your age: ')
income = input('Enter your income: ')
price = determine_price(int(age), int(income))
response = customer_response(price)",

