class PlantSystem {
  double growthRate = 1.0;
  boolean isSunny;
  boolean hasFertilizer;

  double simulateGrowth() {
    if (isSunny) {
      growthRate *= 1.2;
    }
    if (hasFertilizer) {
      growthRate *= 1.5;
    }
    return growthRate;
  }

  void applyFertilizer() {
    hasFertilizer = true;
  }

  void setWeather(boolean sunny) {
    isSunny = sunny;
  }
