def compute_statistics(data):
    if 'temperature' in data:
        max_temp = max(data['temperature'])
    else:
        max_temp = None

    if 'humidity' in data:
        avg_humidity = sum(data['humidity']) / len(data['humidity'])
    else:
        avg_humidity = None

    if max_temp and avg_humidity:
        warning_level = 'high' if max_temp > 30 and avg_humidity > 50 else 'low'
    else:
        warning_level = 'undetermined'

    return max_temp, avg_humidity, warning_level",

