        if amount > 0:
            self.balance += amount
            return True
        else:
            return False

    def withdraw(self, amount):
        if amount > 0 and self.balance >= amount:
            self.balance -= amount
            return True
        else:
            return False

    def add_interest(self):
        self.balance += self.balance * self.interest_rate

    def check_balance(self):
        self.add_interest()
        return self.balance
