def process_data(data, mode):
    if mode == 'normalize':
        max_val = max(data)
        return [x / max_val for x in data]
    elif mode == 'standardize':
        mean_val = sum(data) / len(data)
        std_dev = (sum((x - mean_val) ** 2 for x in data) / len(data)) ** 0.5
        return [(x - mean_val) / std_dev for x in data]
    else:
        return data",

