def process_orders(customer_orders):
  total = 0
  discount = 0
  for order in customer_orders:
    if order['amount'] > 100:
      discount = 0.1
    elif order['item'] == 'special product':
      discount = 0.2
    total += order['amount'] * (1 - discount)
  if total > 500:
    total -= 50  # additional discount for high total
  return total

customer_orders_example = [
  {'item': 'normal product', 'amount': 110},
  {'item': 'special product', 'amount': 150}
]
result = process_orders(customer_orders_example)
print(result)",

