class SystemOptimizer:
    def __init__(self, user_activity):
        self.user_activity = user_activity
        self.system_load = self.calculate_system_load()
        self.performance_mode = 'Normal'

    def calculate_system_load(self):
        hours = self.user_activity['hours']
        if hours > 5:
            return 'High'
        else:
            return 'Low'

    def adjust_settings(self):
        if self.system_load == 'High':
            self.performance_mode = 'High Performance'
        else:
            self.performance_mode = 'Energy Saving'

    def log_mode(self):
        print(f'System mode set to {self.performance_mode}')",

