import random

class Ecosystem:
    def __init__(self):
        self.weather = self.__set_weather()
        self.plant_growth = 0
        self.predator_population = 100

    def __set_weather(self):
        return random.choice(['sunny', 'rainy', 'windy'])

    def grow_plants(self):
        if self.weather == 'sunny':
            self.plant_growth += 20
        elif self.weather == 'rainy':
            self.plant_growth += 50
        else:
            self.plant_growth += 10

    def adjust_predators(self):
        if self.plant_growth > 30:
            self.predator_population += 20
        else:
            self.predator_population -= 30

def simulate_day():
    eco = Ecosystem()
    eco.grow_plants()
    eco.adjust_predators()
    return eco

simulation_result = simulate_day()
