class PollutionController {
  int cars; 
  int factories; 
  int pollutionLevel;

  public PollutionController(int cars, int factories) {
    this.cars = cars;
    this.factories = factories;
    calculatePollution();
  }

  private void calculatePollution() {
    pollutionLevel = (cars * 2) + (factories * 5);
  }

  public void reduceCars(int reduction) {
    cars -= reduction;
    calculatePollotion();
  }

  public void increaseFactories() {
    factories++;
    calculatePollution();
  }

  public int getPollutionLevel() {
    return pollutionLevel;
  }
}",

