class TrafficLightsSystem:
    def __init__(self, is_rainy):
        self.is_rainy = is_rainy
        self.light_color = 'Green'

    def change_light(self):
        if self.is_rainy:
            self.light_color = 'Yellow'
        else:
            if self.light_color == 'Green':
                self.light_color = 'Red'
            elif self.light_color == 'Red':
                self.light_color = 'Green'

    def is_safe_to_go(self):
        if self.is_rainy and self.light_color == 'Yellow':
            return False
        elif self.light_color == 'Red':
            return False
        return True",

