class HealthApp:
    def __init__(self, steps_goal, cal_goal):
        self.steps_goal = steps_goal
        self.cal_goal = cal_goal
        self.is_active = False

    def update_steps(self, steps):
        self.steps = steps
        if self.steps >= self.steps_goal:
            self.meet_steps_goal = True
        else:
            self.meet_steps_goal = False

    def update_calories(self, calories):
        self.calories = calories
        if self.calories >= self.cal_goal:
            self.meet_cal_goal = True
        else:
            self.meet_cal_goal = False

    def report_activity(self):
        if self.meet_steps_goal and self.meet_cal_goal:
            self.is_active = True
        else:
            self.is_active = False",

