class RoomController {
  int temperature = 20;
  boolean heaterOn = false;

  public void increaseTemp() {
    heaterOn = true;
    temperature += 5;
  }

  public void decreaseTemp() {
    if (heaterOn) {
      heaterOn = false;
    }
    temperature -= 3;
  }

  public String checkStatus() {
    if (heaterOn) {
      return "Heater is on and temperature is " + temperature;
    } else {
      return "Heater is off and temperature is " + temperature;
    }
  }
}",

