class HealthSystem:
    def __init__(self):
        self.patients = {}

    def add_patient(self, patient_id, health_status):
        self.patients[patient_id] = health_status

    def update_health_status(self, patient_id, new_status):
        if patient_id in self.patients:
            self.patients[patient_id] = new_status
            return True
        return False

    def prescribe_medication(self, patient_id, medication):
        if self.patients.get(patient_id) == 'Sick':
            self.patients[patient_id] = 'Under Treatment'
            return 'Medication Prescribed'
        return 'Medication Not Necessary'

    def recover_patient(self, patient_id):
        if self.patients.get(patient_id) == 'Under Treatment':
            self.patients[patient_id] = 'Recovered'
            return 'Patient Recovered'
        return 'Recovery Process Not Applicable'

