def compute_sales(price, discount, base_demand, economy_boost):
    if discount >= 20:
        demand_increase = 15
    elif discount >= 10:
        demand_increase = 10
    else:
        demand_increase = 5

    adjusted_demand = base_demand + demand_increase
    if economy_boost:
        adjusted_demand *= 1.1

    revenue = adjusted_demand * (price * (1 - (discount / 100)))
    return revenue",

