class Car{
  int speed = 0;
  boolean engineOn = false;
  void startEngine() {
    engineOn = true;
    speed = 0;
  }
  void stopEngine() {
    engineOn = false;
    speed = 0;
  }
  void accelerate(int increment) {
    if (engineOn) {
      speed += increment;
    }
  }
