class HealthApp:
    def __init__(self, age, active_status, diet_quality):
        self.age = age
        self.active_status = active_status
        self.diet_quality = diet_quality

    def activity_level(self):
        if self.age < 30:
            return 'high' if self.active_status else 'low'
        else:
            return 'moderate' if self.active_status else 'low'

    def health_risk(self):
        if self.activity_level() == 'high' and self.diet_quality > 7:
            return 'low'
        elif self.activity_level() == 'low' or self.diet_quality <= 5:
            return 'high'
        else:
            return 'moderate'

# Example instance
user1 = HealthApp(25, True, 8)
user2 = HealthApp(45, False, 6)
""",

