class Environment:
    def __init__(self, pollution_level):
        self.pollution_level = pollution_level

class Plant:
    def __init__(self, type_of_plant):
        self.type_of_plant = type_of_plant
        self.growth_rate = 0.1

    def grow(self, sunlight, water, environment):
        if environment.pollution_level > 70:
            self.growth_rate *= 0.5
        else:
            self.growth_rate *= 1.2

        if self.type_of_plant == 'Cactus':
            if water < 20:
                self.growth_rate *= 1.5
        else:
            if water > 50:
                self.growth_rate *= 1.3

        return sunlight * water * self.growth_rate

# Create an environment object and a plant object
my_environment = Environment(80)
my_plant = Plant('Flower')
# Plant growth scenario
growth = my_plant.grow(100, 60, my_environment)
""",

