import random

class HealthStatus:
    def __init__(self, age):
        self.age = age
        self.is_smoker = False
        self.caffeine_intake = random.choice(['low', 'medium', 'high'])
        self.sleep_quality = 'poor' # default

    def update_smoking_status(self, status):
        self.is_smoker = status

    def update_sleep_quality_based_on_age_and_caffeine(self):
        if self.age > 40 and self.caffeine_intake != 'low':
            self.sleep_quality = 'poor'
        elif self.caffeine_intake == 'low':
            self.sleep_quality = 'good'
        else:
            self.sleep_quality = 'average'

    def check_health_risk(self):
        if self.is_smoker or (self.age > 50 or self.sleep_quality == 'poor'):
            return 'high'
        else:
            return 'low'

person = HealthStatus(45)
person.update_smoking_status(True)
person.update_sleep_quality_based_on_age_and_caffeine()
risk = person.check_health_risk()
""",

