public class HealthReport {
        private int age;
        private boolean smoker;
        private double cholesterol;
        public HealthReport(int age, boolean smoker, double cholesterol) {
            this.age = age;
            this.smoker = smoker;
            this.cholesterol = cholesterol;
        }
        public double calculateHealthRisk() {
            double risk = 1.0;
            if (age > 50) {
                risk += 0.5;
            }
            if (smoker) {
                risk += 2.0;
            }
            if (cholesterol > 200) {
                risk += 1.5;
            }
            return risk;
        }
    }",

