class WeatherSystem:
    def __init__(self, temperature, humidity):
        self.temperature = temperature
        self.humidity = humidity

    def cloud_formation(self):
        if self.humidity > 80 and self.temperature < 20:
            return True
        else:
            return False

    def rain_fall(self):
        clouds = self.cloud_formation()
        if clouds and self.temperature < 15:
            return True
        else:
            return False

weather = WeatherSystem(18, 85)
is_rain = weather.rain_fall()",

