# Python code for a simple simulation of traffic signal with pedestrian count affecting the duration
import random

def generate_pedestrian_count():
    return random.randint(0, 20)

def adjust_signal_duration(pedestrian_count):
    if pedestrian_count > 10:
        return 60  # longer duration in seconds for high pedestrian traffic
    else:
        return 30  # shorter duration

def is_emergency():
    return random.choice([True, False])

def traffic_signal(duration, emergency_status):
    if emergency_status:
        return 'blink'  # emergency mode blinks the light
    else:
        return duration

# Simulating the signal operation
pedestrian_count = generate_pedestrian_count()
duration = adjust_signal_duration(pedestrian_count)
emergency_status = is_emergency()
signal_status = traffic_signal(duration, emergency_status)
""",

