def sales_analysis(price, quantity, holiday): 
    if holiday: 
        discount = 0.1 
        final_price = price * (1 - discount) 
    else: 
        final_price = price 
    revenue = final_price * quantity 
    if revenue > 1000: 
        big_sale = True 
    else: 
        big_sale = False 
    return {'final_price': final_price, 'big_sale': big_sale, 'revenue': revenue}",

