class WeatherSimulator {
  private int temperature;
  private boolean raining;
  public WeatherSimulator(int temp, boolean rain) {
    temperature = temp;
    raining = rain;
  }
  public void updateWeather(int newTemp, boolean newRain) {
    temperature = newTemp;
    raining = newRain;
  }
  public String getWeatherStatus() {
    if (temperature > 20 && !raining) {
      return "sunny";
    } else if (temperature <= 20 || raining) {
      return "cloudy";
    }
    return "unclear";
  }
}",

