class HealthSystem {
  int dailyExerciseMinutes;
  boolean supplementsTaken;
  int healthScore;
  int stressLevel;
  boolean healthyDiet;

  public HealthSystem(int exercise, boolean supplements, boolean diet) {
    dailyExerciseMinutes = exercise;
    supplementsTaken = supplements;
    healthyDiet = diet;
    updateHealthScore();
  }

  public void updateHealthScore() {
    healthScore = (dailyExerciseMinutes > 30 ? 20 : 10) + (supplementsTaken ? 10 : 0) + (healthyDiet ? 20 : 0);
    stressLevel = 100 - healthScore;
  }
}",

