class Store:
    def __init__(self, inventory_level, price_per_unit):
        self.inventory_level = inventory_level
        self.price_per_unit = price_per_unit

    def update_inventory(self, sold_units):
        self.inventory_level -= sold_units
        return self.inventory_level

    def update_price(self, new_price):
        self.price_per_unit = new_price

    def predict_sales(self, external_factor):
        if external_factor > 5:
            return self.inventory_level * 0.5
        else:
            return self.inventory_level * 0.3

store = Store(100, 20)
sales = store.predict_sales(7)
store.update_inventory(sales)
store.update_price(22)",

