class FarmSimulation {
  private int sunlightHours;
  private int rainfall;
  private boolean fertilizerAdded;
  private int cropYield;

  public FarmSimulation(int sunlight, int rain) {
    this.sunlightHours = sunlight;
    this.rainfall = rain;
    this.fertilizerAdded = false;
    this.cropYield = 0;
  }

  public void addFertilizer() {
    this.fertilizerAdded = true;
  }

  public void calculateYield() {
    this.cropYield = (sunlightHours * 2) + (rainfall * 3);
    if (fertilizerAdded) {
      cropYield += 20;
    }
  }

  public int getYield() {
    return cropYield;
  }
}",

