class SaleAnalysis:
    def __init__(self, sales_data):
        self.sales_data = sales_data
        self.discount = 0.1  # 10% discount rate

    def apply_discount(self):
        for item in self.sales_data:
            item['price'] -= item['price'] * self.discount

    def total_sales(self):
        total = 0
        for item in self.sales_data:
            total += item['price']
        return total

    def add_promotion(self, promotion_rate):
        self.discount += promotion_rate

    def average_price(self):
        return self.total_sales() / len(self.sales_data)

# Example data
sales_data = [{'item_id': 1, 'price': 100}, {'item_id': 2, 'price': 200}]
sales = SaleAnalysis(sales_data)
sales.apply_discount()
sales.add_promotion(0.05)  # Additional 5% promotion
sales.apply_discount()
"""
,

