import numpy as np

class WeatherSimulator:
    def __init__(self, initial_temperature, humidity):
        self.temperature = initial_temperature
        self.humidity = humidity

    def heat_wave(self, increase):
        self.temperature += increase

    def rain(self, amount):
        self.humidity += amount
        if amount > 20:
            self.temperature -= 1

    def report(self):
        if self.temperature > 30:
            return "hot"
        elif self.temperature < 10:
            return "cold"
        else:
            return "mild"

    def adjust_humidity(self, adjustment):
        self.humidity += adjustment
        if self.humidity > 80:
            self.temperature -= 2

simulator = WeatherSimulator(25, 50)
simulator.heat_wave(10)
simulator.rain(15)
simulator.adjust_humidity(35)
status = simulator.report()
""",

