class SalesData:
    def __init__(self, base_price, tax_rate):
        self.base_price = base_price
        self.tax_rate = tax_rate
        self.final_price = None

    def apply_discount(self, discount_rate):
        if discount_rate < 0 or discount_rate > 1:
            raise ValueError("Discount rate must be between 0 and 1")
        self.base_price *= (1 - discount_rate)

    def calculate_final_price(self):
        self.final_price = self.base_price * (1 + self.tax_rate)

    def apply_coupon(self, coupon_value):
        if coupon_value > self.base_price:
            raise ValueError("Coupon value cannot exceed base price")
        self.base_price -= coupon_value

    def update_tax_rate(self, new_tax_rate):
        self.tax_rate = new_tax_rate
""",

