def sales_prediction(store_rating, ad_budget, season):
    base_sales = 500
    if store_rating > 8:
        base_sales += 200
    else:
        base_sales += 100

    if ad_budget > 30000:
        base_sales *= 1.2
    else:
        base_sales *= 1.1

    if season == 'high':
        base_sales *= 1.5
    elif season == 'medium':
        base_sales *= 1.3
    else:
        base_sales *= 1.1
    return base_sales",

