def calculate_sales(tax_rate, base_price, discount_rate, holiday): 
    if holiday: 
        discount_rate *= 1.5 
    total_price = base_price * (1 - discount_rate) 
    tax_amount = total_price * tax_rate 
    final_price = total_price + tax_amount 
    return final_price",

