class WeatherApp:
    def __init__(self, temperature, humidity):
        self.temperature = temperature
        self.humidity = humidity
        self.weather_status = ''

    def update_weather_status(self):
        if self.temperature > 30:
            self.weather_status = 'Hot'
        elif self.temperature < 10:
            self.weather_status = 'Cold'
        else:
            self.weather_status = 'Moderate'

        if self.humidity > 70:
            self.weather_status += ' and Humid'
        elif self.humidity < 30:
            self.weather_status += ' and Dry'

app = WeatherApp(25, 80)
app.update_weather_status()
print(app.weather_status)
