def process_sales_data(prices, discounts, region):
    base_prices = [p - (p * d / 100) for p, d in zip(prices, discounts)]
    if region == 'East':
        tax = 0.07
    elif region == 'West':
        tax = 0.09
    else:
        tax = 0.05
    final_prices = [bp * (1 + tax) for bp in base_prices]
    average_price = sum(final_prices) / len(final_prices)
    return average_price",

