class SalesPredictor:
    def __init__(self, base_sales, season):
        self.base_sales = base_sales
        self.season = season

    def forecast(self):
        if self.season == 'Holiday':
            adjustment_factor = 1.5
        else:
            adjustment_factor = 1.1
        return self.base_sales * adjustment_factor

predictor = SalesPredictor(100, 'Holiday')
projected_sales = predictor.forecast()",

