def compute_metrics(values, method='average'): 
    if method == 'average':
        result = sum(values) / len(values)
    elif method == 'sum':
        result = sum(values)
    else:
        result = None
    if result > 50:
        label = 'high'
    elif result > 20:
        label = 'medium'
    else:
        label = 'low'
    return result, label",

