class EmployeeSalesData {
  int sales; 
  int promotionCount; 
  int marketingSpend;
  double calculate_bonus() {
    return (sales * 0.1) + (promotionCount * 50); 
  }

  void applyPromotion() {
    promotionCount += 1;
    sales += 500; // Sales increase due to promotion
  }

  void increaseMarketingSpend(int amount) {
    marketingSpend += amount;
    sales += (amount / 10); // Effective increment in sales due to increasing marketing spend
  }
}",

