class TrafficSimulation {
    int cars, trafficLight;
    boolean accident;
    TrafficSimulation(int c, int t) {
        cars = c;
        trafficLight = t;
        accident = false;
    }
    void updateTraffic() {
        if (trafficLight == 0 && cars > 50) {
            accident = true;
        } else {
            accident = false;
        }
    }
    void setTrafficLight(int state) {
        trafficLight = state;
        this.updateTraffic();
    }
    void addCar() {
        cars++;
        this.updateTraffic();
    }
    boolean checkAccident() {
        return accident;
    }
}",

