def predict_sales(price, ad_budget, season):
    if season == 'high':
        base_sales = 120
    else:
        base_sales = 100
    adjusted_price_effect = price * -0.5
    ad_effect = ad_budget * 0.4
    total_sales = base_sales + adjusted_price_effect + ad_effect
    return total_sales",

