class TemperatureControlSystem:
    def __init__(self, desired_temp):
        self.desired_temp = desired_temp
        self.current_temp = 72  # Default room temperature in Fahrenheit
        self.heater_on = False
        self.ac_on = False

    def update_temp(self, external_temp):
        self.current_temp += (external_temp - self.current_temp) * 0.05
        self.check_system()

    def set_desired_temp(self, temp):
        self.desired_temp = temp
        self.check_system()

    def check_system(self):
        if self.current_temp < self.desired_temp:
            self.heater_on = True
            self.ac_on = False
        elif self.current_temp > self.desired_temp:
            self.ac_on = True
            self.heater_on = False
        else:
            self.ac_on = False
            self.heater_on = False",

