class HealthSystem:
    def __init__(self):
        self.vaccination_rate = 0.0
        self.infection_rate = 0.0

    def update_vaccination_rate(self, new_rate):
        self.vaccination_rate = new_rate
        self.update_infection_rate()

    def update_infection_rate(self):
        if self.vaccination_rate > 0.7:
            self.infection_rate = 0.05
        elif self.vaccination_rate > 0.4:
            self.infection_rate = 0.2
        else:
            self.infection_rate = 0.5

    def introduce_variant(self, variant_strength):
        if variant_strength > 0.5:
            self.infection_rate *= 1.5
        else:
            self.infection_rate *= 0.9

