class HealthMonitor {
  private int hydrationLevel = 100;
  private boolean thirsty = false;

  public void exercise(int duration) {
    this.hydrationLevel -= duration * 5;
    if (this.hydrationLevel < 30) {
      this.thirsty = true;
    }
  }

  public void drinkWater(int amount) {
    this.hydrationLevel += amount;
    if (this.hydrationLevel > 80) {
      this.thirsty = false;
    }
  }

  public boolean checkThirst() {
    return this.thirsty;
  }

  public int getHydrationLevel() {
    return this.hydrationLevel;
  }
}

HealthMonitor monitor = new HealthMonitor();
monitor.exercise(10); // Exercising for 10 minutes
monitor.drinkWater(50); // Drinking 50 units of water",

