class WeatherCalculator { 
  int temperature; 
  bool isRainy; 
  int humidity; 
  int calculateComfortIndex() { 
    if (isRainy) { 
      return (temperature - 5) - (humidity / 10); 
    } else { 
      return temperature - (humidity / 20); 
    } 
  } 
  void changeWeather(bool rain, int tempChange) { 
    isRainy = rain; 
    temperature += tempChange; 
  } 
}",

