def compute_sales(tax_rate, base_price, discount_rate, season):
    if season == 'winter':
        discount_rate += 0.05
    elif season == 'summer':
        discount_rate -= 0.03
    final_price = base_price * (1 - discount_rate)
    tax_amount = final_price * tax_rate
    total_price = final_price + tax_amount
    return total_price",

