def compute_health_score(age, bmi, exercise_freq): 
    base_score = 100 
    if age > 50: 
        age_factor = 0.9 
    else: 
        age_factor = 1 
    if bmi > 25: 
        bmi_factor = 0.8 
    else: 
        bmi_factor = 1 
    exercise_factor = 1 + (exercise_freq * 0.05) 
    health_score = base_score * age_factor * bmi_factor * exercise_factor 
    return health_score",

