class HealthTracker {
    int steps;
    double caloriesBurned;
    boolean isActive;

    HealthTracker() {
        steps = 0;
        caloriesBurned = 0.0;
        isActive = false;
    }

    void updateSteps(int newSteps) {
        steps += newSteps;
        if (steps > 10000) {
            isActive = true;
        }
        calculateCalories();
    }

    void calculateCalories() {
        caloriesBurned = steps * 0.04;
    }

    void resetTracker() {
