class HealthSystem:
    def __init__(self):
        self.daily_water_intake = 0
        self.exercise_minutes = 0
        self.heart_rate = 70

    def drink_water(self, liters):
        self.daily_water_intake += liters
        if self.daily_water_intake > 2:
            self.heart_rate -= 5

    def exercise(self, minutes):
        self.exercise_minutes += minutes
        if minutes >= 30:
            self.heart_rate += 10
        elif minutes > 0:
            self.heart_rate += 5

    def rest(self):
        if self.exercise_minutes > 60:
            self.heart_rate -= 10
