class WeatherControlSystem:
    def __init__(self):
        self.temperature = 25  # Default temperature
        self.rainfall = 0  # Default rainfall in mm

    def adjust_temperature(self, increase):
        self.temperature += increase
        if self.temperature > 30:
            self.rainfall += 5  # Increase rainfall if it gets too hot

    def decrease_rainfall(self, decrease):
        if self.rainfall > 0:
            self.rainfall -= decrease
            if self.rainfall < 10:
                self.temperature -= 2  # Decrease temperature if rainfall is reduced too much
