    "python_code": """
    # Simulating an environment sensor system with temperature and humidity impacting alert system and fan status

    import random

    def get_weather():
        weather = random.choice(['sunny', 'rainy', 'cloudy'])
        return weather

    def get_temperature(weather):
        if weather == 'sunny':
            temp = random.randint(25, 35)
        elif weather == 'rainy':
            temp = random.randint(15, 25)
        else:
            temp = random.randint(20, 30)
        return temp

    def get_humidity(weather):
        if weather == 'sunny':
            humidity = random.randint(30, 50)
        elif weather == 'rainy':
            humidity = random.randint(60, 90)
        else:
            humidity = random.randint(40, 70)
        return humidity

    def fan_status(temperature):
        return "on" if temperature > 30 else "off"

    def alert_system(temperature, humidity):
        if temperature > 30 and humidity < 40:
            return "high_temp_low_humidity"
        elif temperature < 20 or humidity > 85:
            return "risk"
        else:
            return "normal"

