class CarManufacturingProcess {
  boolean hasEngine = false;
  boolean hasTransmission = false;
  boolean qualityCheckPassed = false;

  void installEngine() {
    if (!hasEngine) {
      hasEngine = true;
    }
  }

  void installTransmission() {
    if (!hasTransmission) {
      hasTransmission = true;
    }
  }

  void performQualityCheck() {
    if (hasEngine && hasTransmission) {
      qualityCheckPassed = true;
    }
  }
}",

