class WeatherSimulator {
    def __init__(self, temperature, humidity): 
        self.temperature = temperature 
        self.humidity = humidity 
        self.weather_condition = '' 
    def update_weather(self): 
        if self.temperature > 30 and self.humidity > 50: 
            self.weather_condition = 'Hot and Humid' 
        elif self.temperature <= 30 and self.humidity <= 50: 
            self.weather_condition = 'Cool and Dry' 
        elif self.temperature > 30: 
            self.weather_condition = 'Hot and Dry' 
        else: 
            self.weather_condition = 'Cool and Humid' 
}",

