class Vehicle:
    def __init__(self, wheels, color):
        self.wheels = wheels
        self.color = color
        self.speed = 0

    def accelerate(self, increment):
        self.speed += increment

    def apply_brakes(self, decrement):
        self.speed -= decrement

if __name__ == '__main__':
    car = Vehicle(4, 'red')
    car.accelerate(10)
    car.apply_brakes(3)
    print(car.speed)",

