class Store:
    def __init__(self, inventory):
        self.inventory = inventory  # number of items in the store

    def purchase(self, quantity):
        if self.inventory >= quantity:
            self.inventory -= quantity  # items are sold
            return True
        return False

    def restock(self, quantity):
        self.inventory += quantity  # items are added to inventory

def check_stock_before_purchase(store, quantity):
    if store.inventory > 0:
        return store.purchase(quantity)
    return False

store = Store(100)  # Store initially has 100 items
store.restock(50)  # 50 more items added
purchase_result = check_stock_before_purchase(store, 30)  # attempting to purchase 30 items
""",

