class TrafficSystem:
    def __init__(self, traffic_light_status):
        self.traffic_light_status = traffic_light_status  # 'Green', 'Yellow', 'Red'

    def pedestrian_signal(self):
        if self.traffic_light_status == 'Red':
            return 'Walk'
        return 'Don't Walk'

    def update_light(self, new_status):
        if new_status != self.traffic_light_status:
            self.traffic_light_status = new_status
            return True
        return False
