def update_inventory(products, sales):
    inventory = {'apple': 30, 'banana': 45, 'orange': 25}
    for product, quantity_sold in sales.items():
        if product in inventory:
            if inventory[product] >= quantity_sold:
                inventory[product] -= quantity_sold
            else:
                print(f'Not enough {product} in stock')
        else:
            print(f'{product} is not part of the inventory')
    return inventory

daily_sales = {'apple': 20, 'banana': 30, 'grape': 5}
remaining_stock = update_inventory(['apple', 'banana', 'orange'], daily_sales)
