class Restaurant {
    int customerCount;
    boolean open;

    Restaurant() {
        this.customerCount = 0;
        this.open = false;
    }

    void openRestaurant() {
        if (!this.open) {
            this.open = true;
            this.customerCount = 0; // Reset customer count upon opening
        }
    }

    void closeRestaurant() {
        if (this.open) {
            this.open = false;
        }
    }

    void newCustomer(int numCustomers) {
        if (this.open) {
            this.customerCount += numCustomers;
        }
    }

    int getCustomerCount() {
        return this.customerCount;
    }

    boolean isOpen() {
        return this.open;
    }
}
""",

