        self.factory_count += 1

    def manufacture(self):
        return self.products_per_day * self.factory_count

env = Environment(50)
factory = Factory(100)
factory.open_new_factory()
env.increase_pollution(factory.factory_count)",

class HealthMonitor {
  int heartRate;
  bool isExercising;

  HealthMonitor(this.heartRate, this.isExercising);

  void updateHeartRate(int newRate) {
    if (isExercising) {
      heartRate = newRate > 100 ? newRate : 100;
    } else {
      heartRate = newRate < 60 ? 60 : newRate;
    }
  }

  bool checkIfCritical() {
    return heartRate >= 100;
  }
}

void main() {
  HealthMonitor monitor = new HealthMonitor(75, false);
  monitor.updateHeartRate(80);
  bool critical = monitor.checkIfCritical();
}",

