class OnlineStore:
    def __init__(self):
        self.stock = {'apple': 100, 'banana': 150}
        self.prices = {'apple': 1, 'banana': 0.5}
        self.sales_report = {}

    def update_price(self, item, new_price):
        if item in self.prices:
            self.prices[item] = new_price
            return True
        return False

    def sell_item(self, item, quantity):
        if item in self.stock and self.stock[item] >= quantity:
            self.stock[item] -= quantity
            self.sales_report[item] = self.sales_report.get(item, 0) + quantity * self.prices[item]
            return True
        return False

    def add_stock(self, item, quantity):
        if item in self.stock:
            self.stock[item] += quantity
            return True
        return False

    def calculate_revenue(self):
        return sum(self.sales_report.values())
  """,

