class BankAccount:
  def __init__(self, initial_balance=0):
    self.balance = initial_balance

  def deposit(self, amount):
    if amount > 0:
      self.balance += amount
      return True
    return False

  def withdraw(self, amount):
    if amount <= self.balance and amount > 0:
      self.balance -= amount
      return True
    return False

  def get_balance(self):
    return self.balance",

