class ProductSalesForecast {
  int initialInventory;
  int salesRate;
  int marketingImpact;

  ProductSalesForecast(int inventory, int rate) {
    initialInventory = inventory;
    salesRate = rate;
    marketingImpact = 0;
  }

  void applyMarketing(int effect) {
    marketingImpact = effect;
    salesRate += effect / 2;
  }

  int predictSales() {
    int adjustedSales = initialInventory - (salesRate + marketingImpact);
    return Math.max(0, adjustedSales);
  }
}",

