            if self.humidity > 70:
                self.weather_status = 'hot and humid'
            else:
                self.weather_status = 'just hot'
        elif self.humidity > 80:
            self.weather_status = 'very humid, not so hot'
        else:
            self.weather_status = 'moderate'
