def compute_sales(price, demand_increment, advertising, season):
    base_demand = 50
    if season == 'high':
        seasonal_factor = 1.5
    else:
        seasonal_factor = 1.0
    demand = base_demand + demand_increment * seasonal_factor
    if advertising > 20:
        demand *= 1.2
    sales = demand * price
    return sales",

