class WeatherSimulator(object):
    def __init__(self, temperature=20, humidity=50):
        self.temperature = temperature
        self.humidity = humidity

    def increase_temp(self, delta):
        self.temperature += delta
        if self.temperature > 30:
            self.humidity -= 10

