def compute_sales(price, demand, advertisement_expense, season):
    if season == 'high':
        season_factor = 1.2
    else:
        season_factor = 0.8
    base_sales = price * demand * season_factor
    if advertisement_expense > 1000:
        return base_sales * 1.1
    else:
        return base_sales",

