class Student:
    def __init__(self, name, age):
        self.name = name
        self.age = age
        self.grade = None

    def update_age(self, new_age):
        self.age = new_age

    def assign_grade(self, score):
        if score >= 90:
            self.grade = 'A'
        elif score >= 80:
            self.grade = 'B'
        elif score >= 70:
            self.grade = 'C'
        else:
            self.grade = 'D'

students = [Student('Alice', 20), Student('Bob', 22)]
stu_1_score = 85
students[0].assign_grade(stu_1_score)
students[1].update_age(23)",

