def compute_score(health, age, activity_level):
    base_score = 100
    if age > 50:
        base_score -= (age - 50) * 1.5
    if health == 'poor':
        base_score -= 30
    elif health == 'average':
        base_score -= 10
    if activity_level == 'high':
        base_score += 20
    elif activity_level == 'low':
        base_score -= 20
    return base_score",

