class PublicHealthSimulation {
  int population = 1000;
  boolean masksMandatory = false;
  double infectionRate = 0.10;
  int simulatedDay = 0;

  void updateInfectionRate() { 
    if (masksMandatory) {
      infectionRate -= 0.05;
    } else {
      infectionRate += 0.03;
    }
    infectionRate = Math.max(0, Math.min(infectionRate, 1));
  }

  void mandateMasks() {
    masksMandatory = true;
    updateInfectionRate();
  }

  void liftMaskMandate() {
    masksMandatory = false;
    updateInfectionRate();
  }

  void simulateDay() {
    updateInfectionRate();
    simulatedDay++;
  }
}",

