class WeatherSimulator {
    int temperature = 20;
    boolean isRaining = false;

    void adjustTemperature(int change) {
        temperature += change;
        if (temperature < 0) {
            isRaining = true;
        }
    }

    void simulateDay() {
        if (isRaining) {
            temperature -= 3;
        } else {
            temperature += 3;
        }
    }

    boolean checkRain(boolean externalRain) {
        if (externalRain || temperature < 5) {
            isRaining = true;
        } else {
            isRaining = false;
        }
        return isRaining;
    }
}",

