class Weather:
  def __init__(self, temperature):
    self.temperature = temperature
    self.humidity = 70
    self.wind_speed = 10

  def update_weather(self, new_temp, rainfall):
    if rainfall > 20:
      self.humidity += 10
    else:
      self.humidity -= 5

    if self.temperature < 20: 
      self.wind_speed += 5
    elif self.temperature > 30:
      self.wind_speed -= 2

    self.temperature = new_temp

  def is_stormy(self):
    storm = (self.humidity > 85) and (self.wind_speed > 15)
    return storm

# Example:
weather = Weather(25)
weather.update_weather(18, 25)
storm = weather.is_stormy()
  """,

