class PlantManager {
  private boolean waterSupply;

  public PlantManager(boolean initialSupply) {
    waterSupply = initialSupply;
  }

  public void setWaterSupply(boolean status) {
    waterSupply = status;
    if(status) {
      alertSystem('Water supply restored.');
    } else {
      alertSystem('Water supply cut off.');
    }
  }

  private void alertSystem(String message) {
    // Send alert message to the system
    System.out.println(message);
  }

  public boolean isWaterAvailable() {
    return waterSupply;
  }
}
