class Environment:
    def __init__(self, temperature):
        self.temperature = temperature

    def adjust_heating(self, new_temp):
        self.temperature = new_temp

class HumidityController:
    def __init__(self, humidity_level):
        self.humidity_level = humidity_level

    def increase_humidity(self, increment):
        self.humidity_level += increment

    def decrease_humidity(self, decrement):
        self.humidity_level -= decrement

class SmartHomeSystem:
    def __init__(self, temp, humidity):
        self.env = Environment(temp)
        self.humidity_control = HumidityController(humidity)

    def optimize_conditions(self):
        if self.env.temperature < 20:
            self.env.adjust_heating(22)
            self.humidity_control.increase_humidity(5)
        elif self.env.temperature > 25:
            self.env.adjust_heating(18)
            self.humidity_control.decrease_humidity(10)

    def query_env_conditions(self):
        return (self.env.temperature, self.humidity_control.humidity_level)
""",

