class TemperatureControlSystem:
    def __init__(self, target_temp, ambient_temp):
        self.target_temp = target_temp
        self.ambient_temp = ambient_temp
        self.cooling_on = False

    def update_ambient_temp(self, new_temp):
        self.ambient_temp = new_temp
        self.adjust_cooling_system()

    def adjust_cooling_system(self):
        if self.ambient_temp > self.target_temp:
            self.cooling_on = True
        else:
            self.cooling_on = False

    def external_event(self, event):
        if event == 'sunny':
            self.update_ambient_temp(self.ambient_temp + 5)
        elif event == 'cloudy':
            self.update_ambient_temp(self.ambient_temp - 3)",

