# Python function to determine promotion eligibility based on performance and tenure
def promotion_eligibility(performance_score, years_of_service, managerial_experience):
    if performance_score >= 85:
        if years_of_service > 5:
            if managerial_experience:
                return 'Eligible for Senior Management Promotion'
            else:
                return 'Eligible for Regular Promotion'
        else:
            return 'Increase in Performance Needed'
    else:
        return 'Not Eligible for Promotion'

# Example usage
status = promotion_eligibility(90, 6, True)
