class WeatherForecast {
  public bool isRainy;
  public int temperature;

  public WeatherForecast(bool rain, int temp) {
    isRainy = updateRainStatus(rain);
    temperature = adjustTemperature(temp, rain);
  }

  private bool updateRainStatus(bool rain) {
    return rain && (temperature < 20);
  }

  private int adjustTemperature(int temp, bool rain) {
    if (rain) return temp - 5;
    return temp;
  }
