class TradingSystem:
    def __init__(self, initial_stock_price, user_balance):
        self.stock_price = initial_stock_price
        self.user_balance = user_balance
        self.own_stocks = 0

    def buy_stock(self, amount):
        total_cost = self.stock_price * amount
        if self.user_balance >= total_cost:
            self.user_balance -= total_cost
            self.own_stocks += amount
            return True
        else:
            return False

    def sell_stock(self, amount):
        if amount <= self.own_stocks:
            total_income = self.stock_price * amount
            self.user_balance += total_income
            self.own_stocks -= amount
            return True
        else:
            return False

    def update_stock_price(self, new_price):
        self.stock_price = new_price
