class WeatherSimulator {
    int temperature;
    bool isRaining;
    int humidity;

    public WeatherSimulator(int temp, bool rain) {
        temperature = temp;
        isRaining = rain;
        if (isRaining) {
            humidity = 95;
        } else {
            humidity = 60;
        }
    }

    public void increaseTemperature(int increment) {
        temperature += increment;
        if (temperature > 30) {
            isRaining = true;
        }
    }

    public void setRain(boolean rain) {
        isRaining = rain;
        if (rain) {
            humidity = 95;
        } else {
            humidity = 50;
        }
    }

    public int getHumidity() {
        return humidity;
    }

    public boolean isRaining() {
        return isRaining;
    }
}",

