class WeatherSimulator {
    int temperature = 20; // Start at 20 degrees
    boolean isRaining = false;

    void updateWeather(int timeOfDay) {
        if (timeOfDay < 6) {
            temperature -= 5; // Cooler in the early morning
        } else if (timeOfDay > 18) {
            temperature -= 3; // Cooler at night
        } else {
            temperature += 8; // Warmer during the day
        }

        if (temperature < 15) {
            isRaining = true; // More likely to rain when cold
        } else {
            isRaining = false;
        }
    }

    void setRaining(boolean status) { 
        isRaining = status;
        if (isRaining) {
            temperature -= 2; // Drop in temperature when it starts raining
        }
    }
}",

