def calculate_sales(tax_rate, base_price, discount_rate, season):
    if season == 'holiday':
        discount_rate += 0.05
    final_price = base_price * (1 - discount_rate)
    tax_amount = final_price * tax_rate
    total_price = final_price + tax_amount
    return total_price",

