class HealthStatus:
    def __init__(self, age):
        self.age = age
        self.immune_response = self.calculate_immune_response(age)
        self.medications = []

    def calculate_immune_response(self, age):
        if age > 60:
            return 'low'
        elif age > 30:
            return 'medium'
        else:
            return 'high'

    def add_medication(self, medication):
        self.medications.append(medication)
        if medication == 'immune_boost':
            return 'immune response boosted'

    def query_immune_status(self):
        if 'immune_boost' in self.medications:
            return 'boosted'
        else:
            return self.immune_response
