def update_inventory(store, item, quantity, operation):
    if operation == 'add':
        store[item] = store.get(item, 0) + quantity
    elif operation == 'remove':
        if item in store:
            store[item] -= quantity
            if store[item] <= 0:
                del store[item]
        else:
            print('Item not found')",

