# Coffee Shop Simulation

class CoffeeShop:
    def __init__(self):
        self.inventory = {'coffee': 100, 'milk': 100, 'sugar': 100}
        self.staff = 3
        self.sales = 0

    def sell_coffee(self, cups):
        if self.inventory['coffee'] >= cups and self.inventory['milk'] >= cups:
            self.inventory['coffee'] -= cups
            self.inventory['milk'] -= cups
            self.sales += cups * 5
            return True
        return False

    def restock(self, item, amount):
        if self.staff > 1 and item in self.inventory:
            self.inventory[item] += amount
            return True
        return False

    def adjust_staff(self, number):
        self.staff += number
        if self.staff < 1:
            self.staff = 1
        elif self.staff > 10:
            self.staff = 10

shop = CoffeeShop()
shop.sell_coffee(10)
shop.restock('coffee', 50)
shop.adjust_staff(2)
""",

class MarketingCampaign:
    def __init__(self, budget, region):
        self.budget = budget
        self.region = region
        self.ad_conversion_rate = 0.05 if region == 'Asia' else 0.03
        self.revenue_increase_factor = 1.2 if budget > 50000 else 1.1

    def simulate_effect(self, additional_budget):
        self.budget += additional_budget
        self.revenue_increase_factor = 1.3 if self.budget > 100000 else self.revenue_increase_factor
        adjusted_revenue = self.budget * self.ad_conversion_rate * self.revenue_increase_factor
        return adjusted_revenue

    def estimate_budget_for_target(self, target_revenue):
        required_budget = (target_revenue) / (self.ad_conversion_rate * self.revenue_increase_factor)
        return required_budget",

