        self.temperature -= degree

class Thermostat:
    def __init__(self, environment):
        self.env = environment
        self.target_temp = 22
        self.is_heating = False

    def update_temperature(self):
        current_temp = self.env.temperature
        if current_temp < self.target_temp:
