    thermo = Thermostat(env)
    for _ in range(10):
        initial_temp = env.temperature
        thermo.update_temperature()
        print(f'Initial Temperature: {initial_temp}, New Temperature: {env.temperature}, Heating: {thermo.is_heating}')
