class WeatherPredictor {
  int temperature;
  int humidity;
  boolean precipitation;

  public WeatherPredictor(int temp, int hum) {
    this.temperature = temp;
    this.humidity = hum;
    this.precipitation = predictPrecipitation();
  }

  private boolean predictPrecipitation() {
    return this.humidity > 85 && this.temperature < 20;
  }

  void setTemperature(int newTemp) {
    this.temperature = newTemp;
    this.precipitation = predictPrecipitation();
  }

  void setHumidity(int newHum) {
    this.humidity = newHum;
    this.precipitation = predictPrecipitation();
  }

  boolean willItRain() {
    return this.precipitation;
  }
}
",

