import random

def market_conditions():
    weather = random.choice(['sunny', 'rainy', 'windy'])
    if weather == 'sunny':
        return 'good'
    else:
        return 'bad'

def sales_volume():
    market = market_conditions()
    if market == 'good':
        base_sales = 100
    else:
        base_sales = 50

    external_factor = random.choice(['holiday', 'weekday'])
    if external_factor == 'holiday':
        return base_sales * 1.5
    else:
        return base_sales

def marketing_campaign(sales):
    if sales > 100:
        campaign = 'large'
    else:
        campaign = 'small'
    return campaign

def revenue():
    sales = sales_volume()
    campaign = marketing_campaign(sales)

    if campaign == 'large':
        revenue_increase = 0.25
    else:
        revenue_increase = 0.10

    total_revenue = sales * (1 + revenue_increase)
    return total_revenue
""",

