    public WeatherSimulator(int temperature) {
        this.temperature = temperature;
        this.isRainy = false;
    }

    public void adjustWeather() {
        if (this.temperature < 20) {
            this.isRainy = true;
        } else {
            this.isRainy = false;
        }
    }

    public boolean willRain() {
        adjustWeather();
        return isRainy;
    }

    public void increaseTemperature(int degrees) {
        this.temperature += degrees;
