class HealthSystem:
    def __init__(self):
        self.vaccine_efficiency = 0.85
        self.disease_spread_rate = 0.3
        self.mask_wearing = False
        self.social_distancing = False

    def vaccinate_population(self, percentage):
        if self.mask_wearing and self.social_distancing:
            adjusted_efficiency = self.vaccine_efficiency + 0.1
        else:
            adjusted_efficiency = self.vaccine_efficiency
        protected_population = adjusted_efficiency * percentage
        return protected_population

    def simulate_infection(self, interactions, infected_initially):
        transmission_probability = interactions * self.disease_spread_rate
        if self.mask_wearing:
            transmission_probability *= 0.5
        if self.social_distancing:
            transmission_probability *= 0.7
        new_infections = transmission_probability * infected_initially
        return new_infections
""",

