def calculate_health_condition(age, smoker, activity_level):
    risk_factor = 2 if smoker else 1
    if age > 50:
        risk_factor *= 1.5
    if activity_level == 'low':
        risk_factor *= 1.2
    elif activity_level == 'high':
        risk_factor *= 0.8
    return 'high-risk' if risk_factor > 2.5 else 'low-risk'",

