        self.temperature = temperature
        self.humidity = humidity
        self.weather_condition = ""

    def update_weather(self):
        if self.temperature > 30:
            self.weather_condition = "Sunny"
        elif self.temperature < 10:
            self.weather_condition = "Snowy"
        else:
            self.weather_condition = "Cloudy"

        if self.humidity > 70:
            self.weather_condition = "Rainy"
        elif self.humidity < 20 and self.temperature > 30:
            self.weather_condition = "Dry"

