class WeatherSimulator {
  int temperature;
  boolean isRaining;

  WeatherSimulator(int temp, boolean rain) {
    temperature = temp;
    isRaining = rain;
  }

  String getWeatherStatus() {
    if (temperature > 20 && !isRaining) {
      return 'Sunny';
    } else if (temperature <= 20 && isRaining) {
      return 'Rainy';
    } else if (temperature > 20 && isRaining) {
      return 'Humid';
    } else {
      return 'Cloudy';
    }
  }
}
