class WeatherSimulator {
  private boolean isRaining;
  private int temperature;

  public WeatherSimulator(boolean isRaining, int temperature) {
    this.isRaining = isRaining;
    this.temperature = temperature;
  }

  public void changeWeather(int newTemperature) {
    if (newTemperature < 0) {
      this.isRaining = false; // it's too cold, so it snows instead.
    } else if (newTemperature > 30) {
      this.isRaining = true; // assume rain due to evaporation.
    }
    this.temperature = newTemperature;
  }

  public boolean willItRainLater() {
    if (this.temperature > 20) {
      return true; // warmer temperatures might indicate rain.
    }
    return false;
  }

  public boolean increaseTemperature(int increment) {
    this.temperature += increment;
    return this.willItRainLater();
  }
}",

