import random

class Weather:
    def __init__(self, temperature):
        self.temperature = temperature

    def is_raining(self):
        return self.temperature < 20

class Mood:
    def __init__(self, weather):
        self.weather = weather
        self.happy = None

    def evaluate_mood(self):
        if self.weather.is_raining():
            self.happy = False
        else:
            self.happy = True

class Productivity:
    def __init__(self, mood):
        self.mood = mood
        self.level = 0

    def calculate_productivity(self):
        if self.mood.happy:
            self.level = random.randint(70, 100)
        else:
            self.level = random.randint(10, 40)

# Simulation
current_weather = Weather(18)  # Low temperature
current_mood = Mood(current_weather)
current_mood.evaluate_mood()
current_productivity = Productivity(current_mood)
current_productivity.calculate_productivity()
""",

