        self.happy = True if not weather.is_raining and weather.temperature > 20 else False

    def go_out(self):
        if self.happy:
            return 'Going out for a walk!'
        else:
            return 'Staying in today.'

def main():
    today_weather = Weather(25)
    my_mood = Mood(today_weather)
    print(my_mood.go_out())

if __name__ == '__main__':
    main()
",

class EnvironmentController:
    def __init__(self, temperature):
        self.temperature = temperature
        self.humidity = 50
        self.ac_on = False
        self.heater_on = False

    def update_conditions(self, outside_temp):
        if outside_temp < 0:
            self.humidity += 5
        elif outside_temp > 30:
            self.ac_on = True
            self.temperature -= 5
        else:
            if self.temperature < 20:
                self.heater_on = True
                self.temperature += 5
            else:
                self.heater_on = False
                self.ac_on = False

    def control_humidity(self):
        if self.humidity > 60:
            if self.ac_on:
                self.humidity -= 5
            else:
                self.humidity -= 2

        elif self.humidity < 40:
            self.humidity += 3
",

