    int humidity;
    boolean isRaining;

    WeatherSystem(int temperature, int humidity) {
        this.temperature = temperature;
        this.humidity = humidity;
        this.isRaining = calculateRain();
    }

    boolean calculateRain() {
        if (humidity > 70 && temperature < 20) {
            return true;
        }
        return false;
    }
