class Store {
    constructor() {
        this.stock = {'apples': 50, 'oranges': 30};
        this.orders = [];
    }

    placeOrder(item, quantity) {
        if (this.stock[item] >= quantity) {
            this.stock[item] -= quantity;
            this.orders.push({item: item, quantity: quantity});
            return true;
        }
        return false;
    }

    restock(item, quantity) {
        this.stock[item] += quantity;
    }
}",

