class User:
    def __init__(self, age):
        self.age = age
        self.is_minor = self.check_if_minor(age)

    def check_if_minor(self, age):
        return age < 18

    def update_age(self, new_age):
        self.age = new_age
        self.is_minor = self.check_if_minor(new_age)

def notify_law_enforcement(user):
    if user.is_minor:
        print("Notifying law enforcement about a minor.")
    else:
        print("No need for notification.")
