class WeatherForecast {
    private boolean isRaining; 
    private int temperature; 

    public WeatherForecast(boolean rain, int temp) {
        this.isRaining = rain; 
        this.temperature = temp; 
    }

    public boolean willRainTomorrow() {
        if (this.temperature < 20 && this.isRaining) {
            return true; 
        }
        return false; 
    }

    public boolean shouldWearJacket() {
        if (this.isRaining || this.temperature < 15) {
            return true; 
        }
        return false; 
    }
}",

