def process_data(data):
    if 'price' in data:
        data['adjusted_price'] = data['price'] * 1.1
    if 'quantity' in data and 'adjusted_price' in data:
        data['total_cost'] = data['quantity'] * data['adjusted_price']
    return data

def analyze_results(data):
    result = 'Low'
    if data.get('total_cost', 0) > 500:
        result = 'Medium'
    if data.get('total_cost', 0) > 1000:
        result = 'High'
    return result

# Example data manipulation
data_input = {'price': 100, 'quantity': 5}
processed_data = process_data(data_input)
final_result = analyze_results(processed_data)
",

