  class HealthMonitor:
      def __init__(self):
          self.waterIntake = 0
          self.sleepHours = 0
          self.stepCount = 0
          self.heartRate = 70

      def drink_water(self, ounces):
          self.waterIntake += ounces
          if self.waterIntake > 64:
              self.heartRate -= 5

      def walk(self, steps):
          self.stepCount += steps
          if self.stepCount > 10000:
              self.heartRate += 10
          self.drink_water(2)

      def sleep(self, hours):
          self.sleepHours += hours
          if self.sleepHours > 8:
              self.heartRate -= 3
          self.waterIntake -= 5

