class HealthData:
    def __init__(self, age, smoking_status, exercise_level):
        self.age = age
        self.smoking_status = smoking_status  # 0 for non-smoker, 1 for smoker
        self.exercise_level = exercise_level  # 0 for low, 1 for medium, 2 for high

    def health_risk_assessment(self):
        risk = 0
        if self.age > 50:
            risk += 1
        if self.smoking_status == 1:
            risk += 2
        if self.exercise_level == 0:
            risk += 1
        elif self.exercise_level == 2:
            risk -= 1
        return risk

    def intervene_exercise(self):
        self.exercise_level = 2

    def intervene_smoking(self):
        self.smoking_status = 0
