class WeatherSimulator {
    private boolean isRainy;
    private int temperature;

    public WeatherSimulator() {
        this.isRainy = Math.random() > 0.5;
        this.temperature = isRainy ? (int) (Math.random() * 10) + 5 : (int) (Math.random() * 15) + 20;
    }

    public boolean isRainyDay() {
        return isRainy;
    }

    public int getTemperature() {
        return temperature;
    }

    public void setRainy(boolean rainy) {
        this.isRainy = rainy;
        this.temperature = rainy ? (int) (Math.random() * 10) + 5 : (int) (Math.random() * 15) + 20;
    }

    public void resetWeather() {
        isRainy = Math.random() > 0.5;
        temperature = isRainy ? (int) (Math.random() * 10) + 5 : (int) (Math.random() * 15) + 20;
    }
}",

