class WeatherSimulator {
    int temperature = 20;
    boolean isRaining = false;

    void setTemperature(int newTemp) {
        temperature = newTemp;
        if (temperature < 5) {
            isRaining = true;
        }
    }

    boolean checkWeather() {
        if (temperature < 10) {
            isRaining = true;
        } else {
            isRaining = false;
        }
        return isRaining;
    }

    void artificialRain() {
        isRaining = true;
        if (isRaining) {
            temperature -= 3;
        }
    }
}",

