class Product:
    def __init__(self, price, is_discounted):
        self.price = price
        self.is_discounted = is_discounted
        if is_discounted:
            self.discount_rate = 0.2
        else:
            self.discount_rate = 0.0

def update_price(product, new_price):
    product.price = new_price
    if new_price < 20:
        product.is_discounted = True
        product.discount_rate = 0.3
    else:
        product.is_discounted = False
        product.discount_rate = 0.0

def apply_discount(product):
    product.price *= (1 - product.discount_rate)
