# Sales volume predicting system based on advertising expenditure
def predict_sales(ad_expenditure, economic_growth):
    base_sales_volume = 500
    if ad_expenditure > 50000:
        if economic_growth >= 2.0:
            sales_multipler = 2.5
        else:
            sales_multipler = 2.0
    else:
        if economic_growth >= 2.0:
            sales_multipler = 1.5
        else:
            sales_multipler = 1.0
    return base_sales_volume * sales_multipler

ad_spend = 60000
growth = 1.5
predicted_sales = predict_sales(ad_spend, growth)
