def online_retail_system(visitors, promo_event=False):
    base_sales = 50
    if visitors > 100:
        sales = base_sales + (visitors - 100) * 0.5
    else:
        sales = base_sales
    if promo_event:
        sales *= 1.5
        visitors += 50
    return sales, visitors",

