def process_data(data, threshold, flag): 
    if flag: 
        modified_data = [x * 2 for x in data] 
    else: 
        modified_data = [x / 2 for x in data] 
    result = [] 
    for value in modified_data: 
        if value > threshold: 
            result.append(True) 
        else: 
            result.append(False) 
    return result",

