class EventOrganizer:
    def __init__(self, budget):
        self.budget = budget
        self.attendees = 0
        self.premium_seats_sold = False

    def update_budget(self, amount):
        self.budget += amount

    def sell_tickets(self, number_of_tickets, premium=False):
        if premium and self.budget >= 1000:
            self.premium_seats_sold = True
            self.attendees += number_of_tickets
            self.update_budget(number_of_tickets * 150)
        else:
            self.attendees += number_of_tickets
            self.update_budget(number_of_tickets * 50)

    def cancel_event(self):
        if self.attendees > 200:
            self.update_budget(-1000)
        else:
            self.update_budget(-500)

    def finalize_event(self):
        if self.premium_seats_sold:
            additional_income = 0.2 * self.budget
            self.update_budget(additional_income)
        return self.budget
""",

