def update_temperature(settings, current_temp, is_heating_on):
    if is_heating_on:
        if current_temp < settings['desired_temp'] - settings['threshold']:
            current_temp += settings['increase_rate']
        elif current_temp > settings['desired_temp'] + settings['threshold']:
            current_temp -= settings['decrease_rate']
    return current_temp",

