class WeatherSimulation:
    def __init__(self, initial_temperature):
        self.temperature = initial_temperature  # degrees Celsius

    def increase_temperature(self, degrees):
        self.temperature += degrees

    def decrease_temperature(self, degrees):
        self.temperature -= degrees

    def set_humidity(self, humidity_level):
        self.humidity = humidity_level  # percentage, e.g., 70 for 70%

    def determine_weather_condition(self):
        if self.temperature > 30 and self.humidity < 50:
            return 'Sunny'
        elif self.temperature < 0:
            return 'Snowy'
        elif self.humidity > 80:
            return 'Rainy'
        else:
            return 'Cloudy'
# Example execution
sim = WeatherSimulation(25)
sim.set_humidity(85)
sim.increase_temperature(10) # Now temperature is 35
weather = sim.determine_weather_condition()
""",

