import random

def set_temperature():
    return random.choice([18, 22, 26])

def set_humidity(temperature):
    if temperature < 20:
        return 'low'
    elif temperature < 25:
        return 'medium'
    else:
        return 'high'

def activate_sprinklers(humidity):
    if humidity == 'low':
        return False
    elif humidity == 'medium':
        return True
    else:
        return True

