    if temperature >= 25 and sprinklers_on:
        return 'open'
    elif temperature < 25 and not sprinklers_on:
        return 'closed'
    else:
        return 'partially open'

temperature = set_temperature()
humidity = set_humidity(temperature)
sprinklers_on = activate_sprinklers(humidity)
vents_status = adjust_vents(temperature, sprinklers_on)
""",

