    def __init__(self):
        self.inventory = {}
        self.credits = 0

    def add_shipment(self, books):
        for book, quantity in books.items():
            if book in self.inventory:
                self.inventory[book] += quantity
            else:
                self.inventory[book] = quantity
            if self.inventory[book] > 50:
                self.credits += (self.inventory[book] - 50) // 10
                self.inventory[book] = 50

    def sell_book(self, book, quantity):
        if book in self.inventory and self.inventory[book] >= quantity:
            self.inventory[book] -= quantity
            sales_revenue = quantity * 15
            return sales_revenue
        else:
            return 'Not Enough Stock'

    def return_book(self, book, quantity):
        if book in self.inventory:
            self.inventory[book] += quantity
            self.credits -= quantity // 10
            if self.credits < 0:
                self.credits = 0
        else:
            self.inventory[book] = quantity
