class HealthSystem:
    def __init__(self, diet, exercise, genetics):
        self.diet = diet
        self.exercise = exercise
        self.genetics = genetics

    def risk_of_disease(self):
        if self.genetics == 'High':
            risk = 0.8
        else:
            risk = 0.3

        if self.diet == 'Poor':
            risk += 0.2
        elif self.diet == 'Good':
            risk -= 0.1

        if self.exercise == 'Low':
            risk += 0.1
        elif self.exercise == 'High':
            risk -= 0.1

        return min(risk, 1.0)

# Initialize a patient
patient = HealthSystem('Good', 'High', 'Low')
print(patient.risk_of_disease())
""",

