class HealthTracker {
    private int calorieIntake;
    private int caloriesBurned;

    public HealthTracker(int intake, int burned) {
        this.calorieIntake = intake;
        this.caloriesBurned = burned;
    }

    public int getNetCalories() {
        return calorieIntake - caloriesBurned;
    }

    public boolean isWeightGain() {
        return getNetCalories() > 0;
    }

    public void eatMore(int calories) {
        this.calorieIntake += calories;
    }

    public void exerciseMore(int calories) {
        this.caloriesBurned += calories;
    }
}",

