class ShoppingCart:
    def __init__(self):
        self.items = {}
        self.discount = 0

    def add_item(self, item_name, quantity, price):
        if item_name in self.items:
            self.items[item_name]['quantity'] += quantity
        else:
            self.items[item_name] = {'quantity': quantity, 'price': price}

    def apply_discount(self, discount_rate):
        self.discount = discount_rate

    def calculate_total(self):
        total = sum(item['quantity'] * item['price'] for item in self.items.values())
        return total - (total * self.discount / 100)

    def remove_item(self, item_name, quantity):
        if item_name in self.items and self.items[item_name]['quantity'] >= quantity:
            self.items[item_name]['quantity'] -= quantity
        if self.items[item_name]['quantity'] == 0:
            del self.items[item_name]",

