class WeatherSensor:
    def __init__(self, location):
        self.location = location
        self.temperature = 0
        self.humidity = 0
    def update_sensor(self, current_temp, current_humidity):
        self.temperature = current_temp if current_temp > -10 else -10
        self.humidity = current_humidity if current_humidity <= 100 else 100
    def alert(self):
        if self.temperature < 0:
            if self.humidity > 80:
                return 'High risk of frost'
            else:
                return 'Low temperature'
        elif self.humidity > 90:
            return 'High humidity'
        return 'Normal conditions'",

