class HealthSystem: 
    def __init__(self, num_doctors, num_patients): 
        self.num_doctors = num_doctors 
        self.num_patients = num_patients 
        self.medicine_stock = 100 

    def treat_patients(self, treatment_type): 
        if treatment_type == 'intensive': 
            return 'high' if self.num_doctors >= 10 else 'low' 

    def order_medicine(self, amount): 
        self.medicine_stock += amount 

    def diagnose(self, patient_symptoms): 
        outcome = 'complex' if len(patient_symptoms) > 3 else 'simple' 
        return outcome 
