class OnlineShop { 
\
    constructor() {
\
      this.products = [];
\
      this.cartTotal = 0;
\
    }
\

\
    addProduct(price) {
\
      this.products.push(price);
\
      this.updateCartTotal();
\
    }
\

\
    removeProduct(index) {
\
      if (index >= 0 && index < this.products.length) {
\
        this.products.splice(index, 1);
\
        this.updateCartTotal();
\
      }
\
    }
\

\
    applyDiscount(discountCode) {
\
      if (discountCode === 'SAVE10') {
\
        this.cartTotal *= 0.9;
\
      }
\
    }
\

\
    updateCartTotal() {
\
      this.cartTotal = this.products.reduce((acc, price) => acc + price, 0);
\
    }
\
  }",

