class Product:
    def __init__(self, price, inventory):
        self.price = price
        self.inventory = inventory

class Store:
    def __init__(self):
        self.products = {}

    def add_product(self, sku, price, inventory):
        if sku not in self.products:
            self.products[sku] = Product(price, inventory)
        else:
            self.products[sku].inventory += inventory

    def sell_product(self, sku, quantity):
        if sku in self.products and self.products[sku].inventory >= quantity:
            self.products[sku].inventory -= quantity
            return "Sold", self.products[sku].inventory
        return "Not enough inventory", 0

    def discount_product(self, sku, discount):
        if sku in self.products:
            old_price = self.products[sku].price
            self.products[sku].price *= (1 - discount)
            return "Price updated", old_price, self.products[sku].price
        return "Product not found"
""",

