def update_inventory(order, inventory):
    for item, quantity in order.items():
        if item in inventory:
            inventory[item] -= quantity
            if inventory[item] < 0:
                restock(item, -inventory[item])
                inventory[item] = 0
        else:
            inventory[item] = -quantity
            restock(item, quantity)

def restock(item, quantity):
    # Function to simulate restocking the item if inventory is low or not in stock.
    print(f'Restocking {quantity} units of {item}.')
""",

