      if weather > 70:
          return 'Cooling'
      else:
          return 'Heating'

  random_weather_temperature = random.randint(30, 100)
  thermostat_setting = 'High' if random_weather_temperature > 80 else 'Low'
  temperature = adjust_temperature(thermostat_setting)
  mode = set_mode(random_weather_temperature)
""",

class WeatherSimulator {
    private boolean cloudy = false;
    private boolean rain = false;

    public void setCloudy(boolean cloudy) {
        this.cloudy = cloudy;
        if (cloudy) {
            this.rain = Math.random() > 0.5;
        } else {
            this.rain = false;
        }
    }

    public boolean isRaining() {
        return rain;
    }

    public void interveneRain(boolean startRain) {
        rain = startRain;
        if (startRain) {
            cloudy = true;
        }
    }
}",

