class WeatherSimulator {
    int temperature;
    boolean isRaining;
    int humidity;

    WeatherSimulator() {
        this.temperature = (int)(Math.random() * 35) + 10;
        this.isRaining = (temperature < 20);
        this.humidity = isRaining ? 80 : 50;
    }

    void increaseTemperature(int increaseBy) {
        temperature += increaseBy;
        if (temperature >= 20) {
            isRaining = false;
            humidity = 50;
        }
    }

    void artificialRain() {
        isRaining = true;
        temperature -= 5;
        humidity = 80;
    }
}",

