class TemperatureController:
    def __init__(self, desired_temp):
        self.desired_temp = desired_temp
        self.current_temp = 70
    def adjust_temp(self, ambient_temp):
        if ambient_temp < self.desired_temp - 5:
            self.heating_on()
        elif ambient_temp > self.desired_temp + 5:
            self.cooling_on()
        else:
            self.system_off()
    def heating_on(self):
        self.current_temp += 5
    def cooling_on(self):
        self.current_temp -= 5
    def system_off(self):
        pass",

