def compute_sales(price, discount, loyalty_points):
    if discount > 20:
        price = price * 0.8  # 20% discount
    else:
        price = price * (1 - discount / 100)
    if loyalty_points > 100:
        price = price * 0.95  # 5% loyalty bonus
    return price",

