def calculate_discount(prices, status, season):
    if status == 'VIP':
        base_discount = 0.2
    else:
        base_discount = 0.05

    if season == 'holiday':
        seasonal_discount = 0.1
    else:
        seasonal_discount = 0.03

    total_discount = base_discount + seasonal_discount
    discounted_prices = [price * (1 - total_discount) for price in prices]
    return discounted_prices",

