class Health:
    def __init__(self, activity_level):
        self.activity_level = activity_level

    def person_health(self, weather):
        if self.activity_level > 5:
            return 'healthy' if weather == 'sunny' else 'unwell'
        else:
            return 'unwell'

def intervention(activity=None, pollution=None):
    if pollution is not None:
        environment = Environment(pollution)
    else:
        environment = Environment(random.randint(10, 100))

    weather = environment.change_weather()

    if activity is not None:
        health_status = Health(activity)
    else:
        health_status = Health(random.randint(1, 10))

    return health_status.person_health(weather)
