class Vehicle:
    def __init__(self, type='car', fuel='gasoline'):
        self.type = type
        self.fuel = fuel
        self.speed = 0

    def accelerate(self, increase):
        if self.fuel != 'electric':
            self.speed += increase
        else:
            self.speed += increase * 0.9

    def decelerate(self, decrease):
        if self.speed - decrease >= 0:
            self.speed -= decrease
        else:
            self.speed = 0

car = Vehicle('car', 'gasoline')
car.accelerate(10)
car.decelerate(5)
",

