        this.temperature = temperature;
        this.humidity = humidity;
        this.isRaining = checkRain();
    }

    boolean checkRain() {
        return temperature < 20 && humidity > 70;
    }

    void changeWeather(int newTemp, int newHumid) {
        this.temperature = newTemp;
        this.humidity = newHumid;
        this.isRaining = checkRain();
    }
}

WeatherSimulator todayWeather = new WeatherSimulator(15, 80);
boolean willItRain = todayWeather.isRaining;",

