# Python code to simulate a basic health simulation system

import random

def exercise_level():
    return random.choice(['none', 'light', 'moderate', 'intense'])

def diet_quality():
    return random.choice(['poor', 'average', 'excellent'])

def stress_level():
    return random.choice(['low', 'medium', 'high'])

def health_status(exercise, diet, stress):
    if exercise == 'none' and diet == 'poor':
        health = 'poor'
    elif exercise == 'intense' or diet == 'excellent':
        health = 'good'
    else:
        health = 'average'

    if stress == 'high':
        health = 'poor' if health == 'average' else 'average'

    return health

# Inputs from the user simulation
ex = exercise_level()
di = diet_quality()
st = stress_level()

# Final health status
final_health = health_status(ex, di, st)
""",

