     if weather == 'rainy':
         traffic_jam = True
     else:
         traffic_jam = False
     coffee = random.choice(['yes', 'no'])
     if coffee == 'yes' and traffic_jam == False:
         mood = 'good'
     elif coffee == 'no' and traffic_jam == True:
         mood = 'bad'
     else:
         mood = 'neutral'
