class ShopCart {
    static int itemCount = 0;
    double totalCost = 0.0;

    void addItem(double price) {
        itemCount++;
        totalCost += price;
    }

    void applyDiscount(double percentage) {
        totalCost -= totalCost * percentage / 100;
    }

    static void resetCart() {
        itemCount = 0;
    }

    static int getItemCount() {
        return itemCount;
    }

    double getTotalCost() {
        return totalCost;
    }
}",

