def compute_scores(data, weights):
    results = {}
    for key, values in data.items():
        score = sum(v * weights[i] for i, v in enumerate(values))
        results[key] = score
    sorted_results = sorted(results.items(), key=lambda x: x[1], reverse=True)
    return sorted_results

data = {'Alice': [3, 4, 5], 'Bob': [5, 3, 3], 'Charlie': [4, 5, 4]}
weights = [0.2, 0.5, 0.3]
scores = compute_scores(data, weights)",

