`
    class SaleAnalysis {
      constructor(salesData) {
        this.salesData = salesData;
      }

      applyDiscount(discountRate) {
        for (let sale of this.salesData) {
          sale.price -= sale.price * discountRate;
        }
      }

      averageSalePrice() {
        let total = 0;
        for (let sale of this.salesData) {
          total += sale.price;
        }
        return total / this.salesData.length;
      }

      increaseTargetSales(targetIncrease, targetItem) {
        for (let sale of this.salesData) {
          if (sale.item === targetItem) {
            sale.price += targetIncrease;
          }
        }
      }

      getSalesCountByItem(item) {
        return this.salesData.filter(sale => sale.item === item).length;
      }
    }
