class Store:
    def __init__(self):
        self.inventory = {}
        self.sales = 0

    def add_product(self, product_name, quantity):
        if product_name in self.inventory:
            self.inventory[product_name] += quantity
        else:
            self.inventory[product_name] = quantity

    def sell_product(self, product_name, quantity):
        if product_name in self.inventory and self.inventory[product_name] >= quantity:
            self.inventory[product_name] -= quantity
            self.sales += quantity * 10  # each product sold for $10
        else:
            return "Product not available or insufficient stock"

    def stock_check(self, product_name):
        return self.inventory.get(product_name, 0)

    def revenue(self):
        return self.sales
  """,

