class NewsletterService:
    def __init__(self):
        self.users = {}
        self.newsletters = {}

    def add_user(self, user_id, email):
        if user_id not in self.users:
            self.users[user_id] = email
            return True
        return False

    def subscribe(self, user_id, newsletter):
        if user_id in self.users and newsletter not in self.newsletters:
            self.newsletters[newsletter] = [user_id]
        elif user_id in self.users:
            self.newsletters[newsletter].append(user_id)
        else:
            return False
        return True

    def send_update(self, newsletter, message):
        if newsletter in self.newsletters:
            for user_id in self.newsletters[newsletter]:
                email = self.users[user_id]
                print(f'Sending {message} to {email}')
            return True
        return False",

