def compute_health_scores(age, diet_quality, exercise_freq): 
    risk_factor = age / 2 + diet_quality * 0.5 - exercise_freq 
    if risk_factor > 20: 
        health_score = 100 - risk_factor 
    else: 
        health_score = 80 + (20 - risk_factor / 2) 
    return health_score",

