    class EnvironmentalControlSystem {
        private int temperature;
        private boolean airPurifierOn;

        public EnvironmentalControlSystem(int initialTemp) {
            temperature = initialTemp;
            airPurifierOn = false;
        }

        public void adjustTemperature(int newTemp) {
            temperature = newTemp;
            if (newTemp < 18) {
                turnOnHeater();
            } else if (newTemp > 26) {
                turnOnAirConditioner();
            }
        }

        private void turnOnHeater() {
            temperature = 21; // Default warm temperature
        }

        private void turnOnAirConditioner() {
            temperature = 24; // Default cool temperature
        }

        public void toggleAirPurification() {
            airPurifierOn = !airPurifierOn;
        }
    }
    """
