def process_data(data): 
    normalized = (data - np.mean(data)) / np.std(data) 
    if np.mean(data) > 0: 
        adjustment = 10 
    else: 
        adjustment = -10 
    adjusted_data = normalized * adjustment 
    return adjusted_data",

