class HealthMonitor:
    def __init__(self):
        self.heart_rate = 70
        self.intake_calories = 2500
        self.slept_hours = 8

    def exercise(self, duration_minutes):
        self.heart_rate += 0.1 * duration_minutes
        self.intake_calories += 0.2 * duration_minutes

    def diet(self, calorie_intake):
        self.intake_calories -= calorie_intake

    def sleep(self, hours):
        self.slept_hours += hours
        if self.slept_hours >= 8:
            self.heart_rate -= 5
        else:
            self.heart_rate -= 2

