class ProductSalesAnalysis {
  int unitsSold;
  double salePrice;
  double discountRate;

  ProductSalesAnalysis(int units, double price, double discount) {
    unitsSold = units;
    salePrice = price;
    discountRate = discount;
  }

  double calculateRevenue() {
    return unitsSold * salePrice * (1 - discountRate);
  }

  void updatePrice(double newPrice) {
    salePrice = newPrice;
  }

  void applyDiscount(double newDiscount) {
    discountRate = newDiscount;
  }
}",

