import random

def calculate_discount(items_count):
    if items_count > 20:
        return 0.1
    elif items_count > 10:
        return 0.05
    else:
        return 0

def process_order(cart, promo_code):
    base_price = sum(item['price'] * item['quantity'] for item in cart)
    items_count = sum(item['quantity'] for item in cart)
    discount = calculate_discount(items_count)
    if promo_code:
        discount += 0.05
    final_price = base_price * (1 - discount)
    return final_price

