class WeatherSystem {
  boolean rainy;
  double temperature;

  public WeatherSystem(boolean rainy, double temperature) {
    this.rainy = rainy;
    this.temperature = temperature;
  }

  public boolean willRainLater() {
    if (this.temperature < 20 && this.rainy) {
      return true;
    }
    return false;
  }

  public void setTemperature(double temperature) {
    this.temperature = temperature;
  }

  public double effectOnMood() {
    if (willRainLater()) {
      return -0.5;
    } else if (this.temperature >= 20) {
      return 0.7;
    }
    return 0;
  }
}",

