def process_data(data, method='average'): 
    if method == 'average': 
        return sum(data) / len(data) 
    elif method == 'total': 
        return sum(data) 
    else: 
        min_val = min(data) 
        max_val = max(data) 
        return (min_val, max_val) 

result = process_data([10, 20, 30], 'min_max')",

