            base_calories = 1800
        else:
            base_calories = 2200
        if self.activity_level == 'high':
            return base_calories + 400
        elif self.activity_level == 'medium':
            return base_calories + 200
        else:
            return base_calories

    def update_weight(self, change):
        self.weight += change
        return self.weight",

