# Python program to demonstrate multiple causal relationships with user data

class User:
    def __init__(self, age):
        self.age = age
        self.is_adult = None
        self.subscription_status = "inactive"
        self.discount = 0

    def update_age(self, new_age):
        self.age = new_age
        self.check_adult_status()

    def check_adult_status(self):
        if self.age >= 18:
            self.is_adult = True
        else:
            self.is_adult = False
        self.update_subscription_status()

    def update_subscription_status(self):
        if self.is_adult and not self.has_active_subscription():
            self.offer_discount(10)

    def has_active_subscription(self):
        return self.subscription_status == "active"

    def offer_discount(self, percentage):
        self.discount = percentage

def trigger_user_updates(user, new_age):
    user.update_age(new_age)
