public class WeatherControlSystem { 
 private boolean isRainy; 
 private int temperature; 
 public void adjustTemperature(int newTemp) { 
   temperature = newTemp; 
   if (temperature < 0) { 
     isRainy = false; 
   } 
 } 
 public boolean checkUmbrellas() { 
   if (isRainy) { 
     System.out.println("Bring an umbrella."); 
     return true; 
   } else { 
     System.out.println("No umbrella needed."); 
     return false; 
   } 
 } 
}",

