def manage_resources(clients, servers):
    if clients > 30:
        servers += 2
    elif clients < 10:
        servers -= 1
    else:
        servers += 1
    load = clients / servers
    if load > 5:
        need_upgrade = True
    else:
        need_upgrade = False
    return need_upgrade",

