class ShoppingCart:
    def __init__(self):
        self.items = []
        self.total = 0

    def add_item(self, item, price):
        self.items.append(item)
        self.update_total(price)

    def remove_item(self, item, price):
        if item in self.items:
            self.items.remove(item)
            self.update_total(-price)

    def update_total(self, price_change):
        self.total += price_change

    def apply_discount(self, discount):
        if discount < 1:
            self.total *= (1 - discount)

    def checkout(self, payment):
        if payment >= self.total:
            change = payment - self.total
            self.total = 0
            self.items = []
            return change
        return None

    def is_empty(self):
        return len(self.items) == 0
