# Python code simulating sales analysis
import random

def generate_sales():
    return random.randint(100, 500)

def apply_discount(sales, discount_rate):
    return sales * (1 - discount_rate)

def advertising_impact(sales):
    if sales < 200:
        return sales * 1.1
    elif sales < 300:
        return sales * 1.2
    else:
        return sales * 1.5

def produce_report(sales, final_sales):
    print(f"Original Sales: {sales}")
    print(f"Final Sales after adjustments: {final_sales}")

# Main execution flow
initial_sales = generate_sales()
discounted_sales = apply_discount(initial_sales, 0.1)
final_sales = advertising_impact(discounted_sales)
produce_report(initial_sales, final_sales)
""",

