class HealthMonitor:
    def __init__(self):
        self.is_sick = False
        self.temperature = 98.6

    def update_temperature(self, new_temp):
        self.temperature = new_temp
        if self.temperature > 100:
            self.is_sick = True
        else:
            self.is_sick = False

    def take_medicine(self):
        if self.is_sick:
            self.temperature -= 2
            if self.temperature <= 98.6:
                self.temperature = 98.6
                self.is_sick = False

    def exercise(self):
        if not self.is_sick:
            self.temperature += 1
            if self.temperature > 100:
                self.is_sick = True

patient = HealthMonitor()
patient.update_temperature(101)  # Patient becomes sick
patient.take_medicine()          # Patient takes medicine
patient.exercise()               # Patient exercises
""",

