class Environment:
    def __init__(self, pollution, wildlife):
        self.pollution = pollution
        self.wildlife = wildlife
    def increase_pollution(self, amount):
        self.pollution += amount
        if self.pollution > 80:
            self.wildlife -= 5

class Policy:
    def __init__(self, law_enforcement):
        self.law_enforcement = law_enforcement
    def implement_law(self, env):
        if self.law_enforcement:
            env.increase_pollution(-20)
        else:
            env.increase_pollution(10)

# Example use-case
environment = Environment(50, 100)
policy = Policy(True)
policy.implement_law(environment)
",

