public class WeatherControlSystem {
    private int temperature;
    private boolean isRaining;

    public WeatherControlSystem(int initTemp) {
        temperature = initTemp;
        isRaining = false;
    }

    public void adjustTemperature(int change) {
        temperature += change;
        if (temperature > 30) {
            isRaining = true;
        }
    }

    public void setRain(boolean rainStatus) {
        isRaining = rainStatus;
        if (!isRaining) {
            temperature += 5;
        }
    }

    public int getTemperature() {
        return temperature;
    }

    public boolean getIsRaining() {
        return isRaining;
    }
}",

