def process_data(data):
    state = 'valid' if validate_data(data) else 'invalid'
    if state == 'valid':
        processed_data = transform_data(adjust_data(data))
        result = analyze_data(processed_data)
    else:
        log_error('Invalid data')
        return None
    return result

def validate_data(data):
    return len(data) > 10 and all(isinstance(item, int) for item in data)

def adjust_data(data):
    return [item * 2 for item in data if item % 2 == 0]

def transform_data(data):
    return [item - 1 for item in data]

def analyze_data(data):
    mean_value = sum(data) / len(data)
    return mean_value > 50

def log_error(message):
    print(message)",

