class PopulationHealth:
    def __init__(self, initial_population, growth_rate):
        self.population = initial_population
        self.growth_rate = growth_rate

    def update_population(self, years):
        for _ in range(years):
            self.population += self.population * self.growth_rate

    def introduce_healthcare_policy(self, improvement_factor):
        self.growth_rate += improvement_factor

    def calculate_mortality(self, mortality_factor):
        return self.population * mortality_factor

health = PopulationHealth(1000, 0.01)
health.update_population(10)
mortality_rate = health.calculate_mortality(0.05)
",

