    if is_promotion_active:
        discount = 0.10  # 10% discount
    else:
        discount = 0
    return apply_discount(price, discount)

def calculate_final_price(base_price, category, is_promotion_active):
    category_discounts = {'electronics': 0.05, 'clothing': 0.15, 'books': 0.00}
    category_discount = category_discounts.get(category, 0)

    price_after_category_discount = apply_discount(base_price, category_discount)

    final_price = apply_promotion(price_after_category_discount, is_promotion_active)
    return final_price
