def calculate_health_score(age, weight, heart_rate, steps_per_day):
    if age > 50:
        base_score = 70
    else:
        base_score = 80
    if weight > 100:
        weight_penalty = 10
    else:
        weight_penalty = 0
    if heart_rate < 60:
        heart_bonus = 15
    elif heart_rate > 100:
        heart_penalty = 20
    else:
        heart_penalty = 0
        heart_bonus = 5
    if steps_per_day > 10000:
        activity_bonus = 20
    else:
        activity_bonus = 0
    health_score = base_score - weight_penalty + heart_bonus - heart_penalty + activity_bonus
    return health_score",

