class HealthApp: 
    def __init__(self, age, diet, exercise): 
        self.age = age 
        self.diet = diet 
        self.exercise = exercise 
        self.health_score = None

    def update_health_score(self): 
        base_score = 100 
        if self.age > 50: 
            base_score -= (self.age - 50) * 0.3 
        if self.diet == 'poor': 
            base_score -= 20 
        elif self.diet == 'moderate': 
            base_score -= 10 
        if self.exercise == 'low': 
            base_score -= 15 
        elif self.exercise == 'moderate': 
            base_score -= 5 
        self.health_score = base_score 

user1 = HealthApp(55, 'moderate', 'low') 
user1.update_health_score()",

