def resolve_issue(customer_satisfaction, response_time, agent_expertise):
    if agent_expertise >= 8:
        customer_satisfaction *= 1.1
    else:
        customer_satisfaction *= 0.9
    if response_time < 5:
        customer_satisfaction *= 1.2
    elif response_time > 10:
        customer_satisfaction *= 0.8
    resolution_success = customer_satisfaction > 85
