            self.traffic_status = 'low'
        elif time_of_day < 10:
            self.traffic_status = 'high'
        else:
            self.traffic_status = 'moderate'

    def report_status(self):
        if self.traffic_status == 'high':
            signal = 'red'
        elif self.traffic_status == 'moderate':
            signal = 'yellow'
        else:
            signal = 'green'
        return signal
",

