class Ecosystem {
  private int sunlightLevel;
  private int waterLevel;
  private int plantGrowth;

  public Ecosystem(int sunlight, int water) {
    this.sunlightLevel = sunlight;
    this.waterLevel = water;
    this.plantGrowth = calculateGrowth();
  }

  private int calculateGrowth() {
    return (sunlightLevel + waterLevel) / 2;
  }

  public void setSunlight(int level) {
    sunlightLevel = level;
    plantGrowth = calculateGrowth();
  }

  public void setWater(int level) {
    waterLevel = level;
    plantGrowth = calculateGrowth();
  }

  public int getPlantGrowth() {
    return plantGrowth;
  }
}",

