def calculate_discount(price, customer_type):
    if customer_type == 'regular':
        return price * 0.95
    elif customer_type == 'member':
        return price * 0.90
    else:
        return price

def apply_coupon(discounted_price, has_coupon):
    if has_coupon:
        return discounted_price * 0.90
    else:
        return discounted_price

def final_price(price, customer_type, has_coupon):
    discounted_price = calculate_discount(price, customer_type)
    final_amount = apply_coupon(discounted_price, has_coupon)
    return final_amount",

