class HealthSystem {
   constructor() { this.health = 100; this.isSick = false; }
   exposeToVirus(virus) {
     if (virus.strength > 10) { this.isSick = true; }
   }
   takeMedicine(medicine) {
     if (this.isSick && medicine.effectiveness > 8) { this.health += 20; this.isSick = false; }
   }
   dayPasses() {
     if (this.isSick) { this.health -= 10; }
   }
   changeWeather(weather) {
     if (weather === 'cold' && this.isSick) { this.health -= 5; }
   }
}

let winterVirus = { strength: 12 };
let aspirin = { effectiveness: 5 };
let antibiotic = { effectiveness: 9 };
let weather = 'cold';

let patient = new HealthSystem();
patient.exposeToVirus(winterVirus);
patient.takeMedicine(aspirin);
patient.dayPasses();
patient.changeWeather(weather);
patient.takeMedicine(antibiotic);
",

