class HealthSystem {
  constructor(patients) {
    this.patients = patients;
  }
  administerTreatment(treatment) {
    this.patients.forEach(patient => {
      if (patient.symptoms.includes('fever')) {
          patient.healthIndex += treatment.efficacy;
          patient.symptoms = patient.symptoms.filter(symptom => symptom !== 'fever');
          treatment.usageCount += 1;
      }
    });
  }
  addPatient(patient) {
    this.patients.push(patient);
  }
}",

