    "code": "
    class SalesData {
      constructor() {
        this.salesFigures = [];
        this.promotions = [];
      }

      addSale(amount) {
        this.salesFigures.push(amount);
      }

      addPromotion(promo) {
        this.promotions.push(promo);
        this.adjustSalesFigures();
      }

      adjustSalesFigures() {
        this.salesFigures = this.salesFigures.map(sale => sale * 1.1);
      }

      calculateTotalSales() {
        return this.salesFigures.reduce((a, b) => a + b, 0);
      }
    }

    const sales = new SalesData();
    sales.addSale(100);
    sales.addSale(200);
    sales.addPromotion('Winter Sale');
    const totalSales = sales.calculateTotalSales();
