  }

  double calculateUnvaccinatedInfections() {
    return population * infectionRate * (1 - vaccinationEffectiveness);
  }

  void increaseVaccinationEffectiveness(double increment) {
    vaccinationEffectiveness += increment;
  }
}",

class VaccineCampaign {
  int population;
  double infectionRate;
  double vaccinationEffectiveness;

  VaccineCampaign(int population, double infectionRate, double vaccinationEffectiveness) {
    this.population = population;
    this.infectionRate = infectionRate;
    this.vaccinationEffectiveness = vaccinationEffectiveness;
  }

  double calculateUnvaccinatedInfections() {
    return population * infectionRate * (1 - vaccinationEffectiveness);
  }

  void increaseVaccinationEffectiveness(double increment) {
    vaccinationEffectiveness += increment;
  }
}",

