    isRaining = rain;
  }

  boolean checkFreezing() {
    return temperature < 32;
  }

  String suggestActivity() {
    if (isRaining) {
      return "Stay indoors";
    } else if (checkFreezing()) {
      return "Go skiing";
    }
    return "Go hiking";
  }
