def compute_health_score(age, activity_level, diet_quality):
    if age < 30:
        base_score = 80
    else:
        base_score = 70

    if activity_level > 7:
        activity_score = 20
    else:
        activity_score = 10

    if diet_quality == 'good':
        diet_score = 30
    elif diet_quality == 'average':
        diet_score = 20
    else:
        diet_score = 10

    health_score = base_score + activity_score + diet_score
    return health_score",

