    class Employee:
        def __init__(self, name, years_of_service, department):
            self.name = name
            self.years_of_service = years_of_service
            self.department = department
            self.bonus = 0

        def update_bonus(self, department_performance):
            base_bonus = 1000
            if self.years_of_service > 5:
                base_bonus += 500
            if department_performance > 90:
                base_bonus += 300
            self.bonus = base_bonus

