def process_data(data_list):
    mean = sum(data_list) / len(data_list)
    adjusted_data = [x - mean for x in data_list]
    max_min_ratio = max(data_list) / min(data_list)
    if max_min_ratio > 5:
        balanced_data = [x + 5 for x in adjusted_data]
    else:
        balanced_data = [x + 1 for x in adjusted_data]
    return balanced_data",

