    {'name': 'Alice', 'attendance': 92, 'study_hours': 4},
    {'name': 'Bob', 'attendance': 88, 'study_hours': 6},
    {'name': 'Charlie', 'attendance': 85, 'study_hours': 3}
]

# Generating grades for each student
for student in students:
    student['grade'] = compute_grade(student['attendance'], student['study_hours'])
""",

