class HealthSystem:
    def __init__(self):
        self.environmental_quality = 80
        self.healthcare_funding = 100
        self.public_awareness = 50

    def update_environmental_quality(self, action):
        if action == 'improve':
            self.environmental_quality += 20
        elif action == 'degrade':
            self.environmental_quality -= 20

    def update_healthcare_funding(self, action):
        if action == 'increase':
            self.healthcare_funding += 50
        elif action == 'decrease':
            self.healthcare_funding -= 50

    def update_public_awareness(self, action):
        if action == 'campaign':
            self.public_awareness += 30
        elif action == 'no_action':
            pass

    def calculate_public_health(self):
        health_score = (self.environmental_quality + self.healthcare_funding + self.public_awareness) / 3
        return health_score
""",

