class Store {
  constructor() {
    this.stock = {'apple': 50, 'banana': 30, 'cherry': 20};
    this.cashOnHand = 500;
  }
  sellFruit(fruit, quantity) {
    if (this.stock[fruit] >= quantity) {
      this.stock[fruit] -= quantity;
      let price = this.getPrice(fruit);
      this.cashOnHand += price * quantity;
    }
  }
  getPrice(fruit) {
    const prices = {'apple': 2, 'banana': 1.5, 'cherry': 3};
    return prices[fruit] || 0;
  }
}

let myStore = new Store();
myStore.sellFruit('apple', 10);",

