class WeatherSimulator: 
    def __init__(self, temperature):
        self.temperature = temperature
        self.rain = False
    def update_weather(self, season):
        if season == 'Winter':
            self.temperature -= 5
        elif season == 'Summer':
            self.temperature += 5
        self.check_rain()
    def check_rain(self):
        if self.temperature < 20:
            self.rain = True
        else:
            self.rain = False",

