        data['luxury_spending'] = data['income'] * 0.2 
    else: 
        data['luxury_spending'] = data['income'] * 0.1 
    if data['age'] > 30: 
        data['savings'] = data['income'] * 0.15 
    else: 
        data['savings'] = data['income'] * 0.05 
    data['total_spending'] = data['luxury_spending'] + data['savings'] 
    return data",

