        this.cloudCoverage = Math.random() > 0.5;
        this.wind = Math.random() > 0.7;
        updateWeather();
    }

    private void updateWeather() {
        if (cloudCoverage && wind) {
            this.rain = Math.random() > 0.4;
        } else {
            this.rain = false;
        }
    }

    public void setCloudCoverage(boolean cloud) {
        this.cloudCoverage = cloud;
        updateWeather();
    }

    public void setWind(boolean wind) {
        this.wind = wind;
        updateWeather();
    }
