class OnlineStore:
    def __init__(self, products=[]):
        self.available_products = products

    def add_product(self, product_name, quantity):
        for product in self.available_products:
            if product['name'] == product_name:
                product['quantity'] += quantity
                return
        self.available_products.append({'name': product_name, 'quantity': quantity})

    def purchase_product(self, product_name, quantity):
        for product in self.available_products:
            if product['name'] == product_name and product['quantity'] >= quantity:
                product['quantity'] -= quantity
                return quantity
        return 0

store = OnlineStore()
store.add_product('Laptop', 10)
units_sold = store.purchase_product('Laptop', 5)",

