    elif student_status:
        return 20
    else:
        return 0

def check_eligibility(age, income):
    if age > 65 or income < 5000:
        return True
    return False

def calculate_insurance_premium(age, student_status, income):
    discount = set_discount(age, student_status)
    is_eligible = check_eligibility(age, income)

    if not is_eligible:
        base_premium = 200
    elif income < 3000:
        base_premium = 100
    else:
        base_premium = 150

    final_premium = base_premium - discount
    return final_premium
