    "code": """
    class CoffeeMachine:
        def __init__(self):
            self.cups_made = 0
            self.power_usage = 0
            self.temperature = 20  # ambient temperature in Celsius

        def make_coffee(self, cups):
            if self.temperature < 15:
                self.power_usage += 1.5 * cups
            else:
                self.power_usage += cups
            self.cups_made += cups

        def set_temperature(self, temp):
            self.temperature = temp

        def override_max_cups(self, max_cups):
            self.cups_made = min(self.cups_made, max_cups)

    # Example usage:
    machine = CoffeeMachine()
    machine.set_temperature(10)
    machine.make_coffee(5)
    machine.override_max_cups(3)
