class DataProcessor: 
  def __init__(self, data): 
    self.data = data 
  def normalize(self): 
    self.data = [x / max(self.data) for x in self.data] 
  def reverse_data(self): 
    self.data.reverse() 

class Analysis: 
  def __init__(self, processor): 
    self.processor = processor 
  def correlation(self, modify=False): 
    if modify: 
      self.processor.reverse_data() 
    sorted_data = sorted(self.processor.data) 
    return sum(x*y for x, y in zip(sorted_data, self.processor.data)) / len(sorted_data)",

