def student_grades(hours_studied, class_attendance, current_grade):
    if class_attendance > 75:
        performance_boost = 0.1
    else:
        performance_boost = 0

    if hours_studied > 5:
        study_boost = 0.2
    else:
        study_boost = 0

    final_grade = current_grade + (current_grade * (performance_boost + study_boost))
    return final_grade

