    class HealthMonitor:
        def __init__(self, age, smoker_status):
            self.age = age
            self.smoker_status = smoker_status
            self.health_score = 100

        def update_health_score(self, activity_level, diet_quality):
            if self.smoker_status:
                self.health_score -= 20
            if self.age > 50:
                self.health_score -= 10
            self.health_score += activity_level
            self.health_score += diet_quality * 2

        def diagnose(self):
            if self.health_score < 70:
                return 'At risk'
            else:
                return 'Healthy'

    # Example usage:
    person = HealthMonitor(55, True)
    person.update_health_score(5, 4)
    health_status = person.diagnose()
    """
