class WeatherSimulator {
  private boolean isCloudy;
  private boolean isRainy;

  public WeatherSimulator() {
    this.isCloudy = Math.random() > 0.5;
    this.isRainy = this.isCloudy && (Math.random() > 0.7);
  }

  public boolean willItRain() {
    return isRainy;
  }

  public void makeItCloudy() {
    this.isCloudy = true;
    this.isRainy = Math.random() > 0.7;
  }

  public void clearSkies() {
    this.isCloudy = false;
    this.isRainy = false;
  }
}",

