class Car:
    def __init__(self, model, fuel_efficiency):
        self.model = model
        self.fuel_efficiency = fuel_efficiency
        self.fuel_level = 100

    def drive(self, distance):
        consumption_rate = 0.05 * self.fuel_efficiency
        self.fuel_level -= consumption_rate * distance

    def refuel(self, amount):
        if self.fuel_level + amount > 100:
            self.fuel_level = 100
        else:
            self.fuel_level += amount

    def check_fuel(self):
        return self.fuel_level",

