class MachineLearningModel: 
    def __init__(self, data): 
        self.data = data 
        self.model = None 
    def preprocess_data(self): 
        self.data = self.data.dropna() 
        self.data = (self.data - self.data.mean()) / self.data.std() 
    def train_model(self, algorithm): 
        if algorithm == 'linear': 
            self.model = 'LinearModelTrained' 
        elif algorithm == 'tree': 
            self.model = 'DecisionTreeTrained' 
    def predict(self, new_data): 
        if self.model == 'LinearModelTrained': 
            return new_data @ 1.5 
        elif self.model == 'DecisionTreeTrained': 
            return new_data > 0.5 
        else: 
            return 'Model not trained'",

