def compute_score(age, is_student, has_job):
    if age < 18:
        base_score = 20
    elif age < 60:
        base_score = 50
    else:
        base_score = 30

    if is_student:
        if age < 30:
            bonus = 25
        else:
            bonus = 10
    elif has_job:
        bonus = 40
    else:
        bonus = 5

    total_score = base_score + bonus
    return total_score",

