class WeatherSimulation {
  int temperature;
  bool isRaining;
  double windSpeed;

  WeatherSimulation(int temp, bool rain, double wind) {
    temperature = temp;
    isRaining = rain;
    windSpeed = wind;
  }

  bool determineRainStatus() {
    if(temperature < 15 && windSpeed > 20.0) {
      return true;
    } else {
      return false;
    }
  }

  void updateWeather(int newTemp, double newWindSpeed) {
    temperature = newTemp;
    windSpeed = newWindSpeed;
    isRaining = determineRainStatus();
  }
}",

