class WeatherSystem {
    var temperature: Int
    var humidity: Int
    var isRaining: Bool

    init(temperature: Int, humidity: Int) {
        self.temperature = temperature
        self.humidity = humidity
        self.isRaining = false
        updateWeather()
    }

    func updateWeather() {
        if humidity > 70 && temperature < 20 {
            isRaining = true
        } else {
            isRaining = false
        }
    }

    func adjustTemperature(newTemp: Int) {
        temperature = newTemp
        updateWeather()
    }

    func adjustHumidity(newHum: Int) {
        humidity = newHum
        updateWeather()
    }
}
",

