class HealthMonitor:
    def __init__(self, heart_rate, sleep_hours):
        self.heart_rate = heart_rate
        self.sleep_hours = sleep_hours

    def risk_level(self):
        if self.heart_rate > 100 or self.sleep_hours < 6:
            return 'High'
        elif 60 <= self.heart_rate <= 100 and 6 <= self.sleep_hours <= 8:
            return 'Moderate'
        else:
            return 'Low'

    def improve_sleep(self):
        self.sleep_hours += 1

    def reduce_heart_rate(self):
        self.heart_rate -= 10",

