def update_price(supply, demand, is_promo_active):
    base_price = 100
    if supply < 50:
        price_increase = 20
    elif supply >= 100:
        price_increase = -10
    else:
        price_increase = 5
    if demand > 100:
        demand_factor = 15
    else:
        demand_factor = -5
    if is_promo_active:
        promo_discount = 20
    else:
        promo_discount = 0
    final_price = base_price + price_increase + demand_factor - promo_discount
    return final_price",

