class ProductSales {
  int price;
  int unitsSold;
  int marketingBudget;
  ProductSales(this.price, this.unitsSold, this.marketingBudget);
  int calculateRevenue() {
    return price * unitsSold;
  }
  int allocateMarketingBudget(int additionalBudget) {
    marketingBudget += additionalBudget;
    if (marketingBudget > 1000) {
      unitsSold += 50;
    } else {
      unitsSold += 20;
    }
    return unitsSold;
  }
}",

