def analyze_performance(data):
    if data['sales'] > 100000:
        data['market'] = 'high'
    else:
        data['market'] = 'low'
    if data['reviews'] > 500:
        data['customer_satisfaction'] = 'good'
    else:
        data['customer_satisfaction'] = 'poor'
    if data['market'] == 'high' and data['customer_satisfaction'] == 'good':
        data['future_profit'] = 'likely high'
    elif data['market'] == 'low' and data['customer_satisfaction'] == 'poor':
        data['future_profit'] = 'likely low'
    else:
        data['future_profit'] = 'uncertain'
    return data",

