public class HealthSystem {
    private int health = 100;
    private bool immune = false;

    public void TakeDamage(int damage) {
        if (!immune) {
            health -= damage;
            if (health < 0) {
                health = 0;
            }
        }
    }

    public void Heal(int amount) {
        if (health > 0) {
            health += amount;
            if (health > 100) {
                health = 100;
            }
        }
    }

    public void ActivateImmunity() {
        immune = true;
    }

