class TaskScheduler { 
    private int count; 
    public TaskScheduler() { count = 0; } 

    public void addTask() { count++; } 

    public boolean executeTask() { 
        if (count > 0) { 
            count--; 
            return true; 
        } 
        return false; 
    } 

    public void resetScheduler() { 
        count = 0; 
    } 

    public int getCount() { 
        return count; 
    } 
}",

