import random

def update_health(health, steps):
    if steps > 10000:
        health += 10
    elif steps < 5000:
        health -= 5
    return health

def main_activity():
    health = 50
    weather = random.choice(['sunny', 'rainy'])
    if weather == 'sunny':
        steps = random.randint(8000, 12000)
    else:
        steps = random.randint(3000, 7000)
    health = update_health(health, steps)
    if health > 60:
        mood = 'happy'
    else:
        mood = 'sad'
    return mood

# Run the simulation
mood_today = main_activity()
""",

