class EconomySystem {
    int interestRate = 5;
    int investment = 100;
    double consumerConfidence = 0.8;

    void updateRates(double globalInfluence) {
        interestRate += (globalInfluence > 0.5) ? 1 : -1;
    }

    void adjustInvestment() {
        investment += (interestRate > 4) ? 20 : -10;
    }

    void modifyConsumerConfidence() {
        consumerConfidence *= (interestRate > 4) ? 1.05 : 0.95;
    }
}

EconomySystem myEconomy = new EconomySystem();
myEconomy.updateRates(0.6);
myEconomy.adjustInvestment();
myEconomy.modifyConsumerConfidence();",

