def update_prices(prices, rate_increase, special_deal, day_of_week):
    if day_of_week == 'Monday':
        new_prices = {item: price * 1.05 for item, price in prices.items()}
    else:
        new_prices = {item: price * (1 + rate_increase) for item, price in prices.items()}
    if special_deal:
        new_prices = {item: price * 0.9 for item, price in new_prices.items()}
    return new_prices",

