def process_sales_data(product_sales, bonus_threshold): 
    total_sales = sum(product_sales.values()) 
    average_sales = total_sales / len(product_sales) 
    bonuses_awarded = {product: sales > bonus_threshold for product, sales in product_sales.items()} 
    return average_sales, bonuses_awarded",

