    class HealthMonitor:
        def __init__(self):
            self.water_intake = 0
            self.step_count = 0
            self.sleep_hours = 0
            self.calorie_intake = 0

        def drink_water(self, ounces):
            self.water_intake += ounces
            self.calorie_intake -= 5

        def walk(self, steps):
            self.step_count += steps
            if steps > 1000:
                self.calorie_intake += 50
            else:
