        def sleep(self, hours):
            self.sleep_hours += hours
            if hours < 7:
                self.calorie_intake += 30
            else:
                self.calorie_intake -= 10

    # Example usage
    person = HealthMonitor()
    person.drink_water(16)
    person.walk(1200)
    person.sleep(6)
