class EnvironmentalData {
  float temperature;
  float humidity;

  public EnvironmentalData() {
    temperature = adjustTemperatureBasedOnSeason('winter');
    humidity = adjustHumidityBasedOnWeather('sunny'); 
  }

  private float adjustTemperatureBasedOnSeason(String season) {
    if (season.equals('winter')) {
      return 32.0f;
    } else if (season.equals('summer')) {
      return 85.0f;
    } else {
      return 68.0f; // default for spring/fall
    }
  }

  private float adjustHumidityBasedOnWeather(String weather) {
    if (weather.equals('sunny')) {
      return 45.0f;
    } else if (weather.equals('rainy')) {
      return 80.0f;
    } else {
      return 60.0f; // default assumption
    }
  }
}
