class WeatherSimulator {
  private boolean isRaining;
  private int temperature;

  public WeatherSimulator(boolean isRaining, int temperature) {
    this.isRaining = isRaining;
    this.temperature = temperature;
  }

  public boolean activateSprinklers() {
    if (!isRaining && temperature > 30) {
      return true;    // Activates sprinklers
    }
    return false;
  }

  public boolean isMuddy() {
    if (isRaining || activateSprinklers()) {
      return true;    // Ground becomes muddy
    }
    return false;
  }
}",

