class WeatherSimulator {
  int temperature;
  boolean isRaining;

  WeatherSimulator(int temperature, boolean isRaining) {
    this.temperature = temperature;
    this.isRaining = isRaining;
  }

  boolean decideToCarryUmbrella() {
    if (isRaining) {
      return true;
    } else if (temperature < 10) {
      return true;
    }
    return false;
  }

  boolean willPlantsSurvive() {
    if (!isRaining && temperature > 30) {
      return false;
    }
    return true;
  }
}",

