class WeatherSimulator {
  private boolean isRaining;
  private int temperature;
  public WeatherSimulator(boolean isRaining, int temperature) {
    this.isRaining = isRaining;
    this.temperature = temperature;
  }
  public void updateWeather(boolean newRainStatus, int newTemperature) {
    if (newTemperature > 20 && !isRaining) {
      newRainStatus = false;
    }
    this.isRaining = newRainStatus;
    this.temperature = newTemperature;
  }
  public String getWeatherStatus() {
    if (isRaining) {
      return "Rainy";
    } else if (temperature > 25) {
      return "Sunny";
    } else {
      return "Cloudy";
    }
  }
}",

