class HealthApp {
  private int steps;
  private int calorieCount;

  public HealthApp(int steps, int calorieCount) {
    this.steps = steps;
    this.calorieCount = calorieCount;
  }

  public void walk(int stepInc) {
    this.steps += stepInc;
    this.calorieCount -= stepInc / 20;
  }

  public void eat(int calories) {
    this.calorieCount += calories;
  }

  public int getSteps() {
    return steps;
  }

  public int getCalorieCount() {
    return calorieCount;
  }
}",

