class OnlineStore:
    def __init__(self, products):
        self.products = products
        self.orders = []
        self.revenue = 0

    def add_product(self, product, price):
        self.products[product] = price

    def place_order(self, product, quantity):
        if product in self.products and quantity > 0:
            total_price = self.products[product] * quantity
            self.revenue += total_price
            self.orders.append((product, quantity, total_price))
        else:
            raise ValueError('Product not available or invalid quantity')

    def calculate_discount(self, order, discount_rate):
        product, quantity, total_price = order
        return total_price - (total_price * discount_rate / 100)

    def apply_discount_and_process_order(self, product, quantity, discount_rate):
        order = self.place_order(product, quantity)
        discounted_price = self.calculate_discount(order, discount_rate)
        return discounted_price",

