    class HealthSystem:
        def __init__(self, population, infected_rate):
            self.population = population
            self.infected_rate = infected_rate
            self.infected_population = int(self.population * self.infected_rate)

        def spread_virus(self, control_measures=False):
            if control_measures:
                reduction_factor = 0.5
            else:
                reduction_factor = 1.0
            self.infected_population = int(self.infected_population * 2 * reduction_factor)

        def immunize_population(self, vaccine_effectiveness):
            self.infected_population = int(self.infected_population * (1 - vaccine_effectiveness))

        def increase_population(self, growth_rate):
            self.population = int(self.population * (1 + growth_rate))
            self.infected_population = int(self.infected_population * (1 + growth_rate))
