class Store {
    int customers;
    int sales;

    Store(int initialCustomers) {
        customers = initialCustomers;
        sales = 0;
    }

    void increaseCustomers(int count) {
        customers += count;
    }

    void makeSale() {
        if (customers > 0) {
            sales += customers * 10;
            customers -= 1;
        }
    }

    void runPromotion() {
        increaseCustomers(5);
        makeSale();
    }
}",

