public class TrafficSystem {
 public boolean isRushHour; 
 public int trafficDensity; 
 public int waitTime; 

 public TrafficSystem(boolean isRushHour) { 
 this.isRushHour = isRushHour; 
 if (isRushHour) { 
 this.trafficDensity = 100; 
 this.waitTime = 30; 
 } else { 
 this.trafficDensity = 20; 
 this.waitTime = 5; 
 } 
 }

 public void changeTrafficDensity(int density) { 
 this.trafficDensity = density; 
 if (density > 80) { 
 this.waitTime = 25; 
 } else { 
 this.waitTime = 10; 
 } 
 }
 }",

