def process_data(data):
    cleaned_data = clean_data(data)
    analyzed_data = analyze_data(cleaned_data)
    final_result = compile_results(analyzed_data)
    return final_result

def clean_data(data):
    return {key: val.strip() for key, val in data.items()}

def analyze_data(data):
    return {key: 'processed' if len(val) > 5 else 'skipped' for key, val in data.items()}

def compile_results(data):
