class WeatherSimulator {
    int temperature = 20;
    boolean isRaining = false;

    void updateWeather(int time) {
        if (time > 18) {
            isRaining = true;
            temperature -= 5;
        } else if (time < 6) {
            temperature -= 3;
        }
    }

    String getWeatherStatus() {
        if (isRaining) {
            return "Rainy and cool";
        }
        return "Clear and mild";
    }
}
