def analyze_data(data):
    scores = data['scores']
    average = sum(scores) / len(scores)

    if average > 65:
        outcome = 'pass'
    else:
        outcome = 'fail'

    modification_score = data.get('bonus', 0)
    adjusted_scores = [s + modification_score for s in scores]
    adjusted_average = sum(adjusted_scores) / len(adjusted_scores)

    if adjusted_average > 65:
        adjusted_outcome = 'pass'
    else:
        adjusted_outcome = 'fail'

    return outcome, adjusted_outcome",

