class RoomEnvironment:
    def __init__(self, temperature=20):
        self.temperature = temperature
        self.heater_on = False
        self.window_open = False

    def update_temperature(self):
        if self.heater_on:
            self.temperature += 5
        if self.window_open:
            self.temperature -= 3

    def heater_switch(self, status):
        self.heater_on = status

    def window_control(self, open_status):
        self.window_open = open_status

