class OrderProcessor {
    private int discountRate;
    private boolean isPremiumMember;

    public OrderProcessor(boolean memberStatus) {
        isPremiumMember = memberStatus;
        if (isPremiumMember) {
            discountRate = 20;
        } else {
            discountRate = 5;
        }
    }

    public double processOrder(double orderValue, boolean applyDiscount) {
        double finalPrice = orderValue;
        if (applyDiscount) {
            finalPrice -= (orderValue * discountRate / 100);
        }
        return finalPrice;
    }
}
",

