class WeatherController {
    private int temperature;
    private bool cloudy;
    public WeatherController(int temp, bool isCloudy) {
        temperature = temp;
        cloudy = isCloudy;
    }

    public bool willItRain() {
        if (cloudy && temperature < 20) {
            return true;
        }
        return false;
    }

    public void setTemperature(int temp) {
        temperature = temp;
    }

    public void makeCloudy() {
        cloudy = true;
    }
