            self.total *= (1 - discount)

    def calculate_tax(self, tax_rate):
        if self.total > 0:
            tax = self.total * tax_rate
            self.total += tax
            return tax

    def check_out(self, cash_paid):
        if cash_paid >= self.total:
            self.total = 0
            return 'Checked out successfully.'
        else:
            return 'Insufficient funds.'",

