def calculate_health_index(age, weight, exercise_freq):
    if age > 50:
        health_index = 70
    else:
        health_index = 80
    health_index -= weight//20
    if exercise_freq > 3:
        health_index += 10
    else:
        health_index -= 5
    return health_index",

