class WeatherSystem {
  private int temperature;
  private boolean isRaining;

  public WeatherSystem(int temperature, boolean isRaining) {
    this.temperature = temperature;
    this.isRaining = isRaining;
  }

  public void updateWeather(int tempChange, boolean rainStatus) {
    temperature += tempChange;
    if (temperature < 0) {
      isRaining = false; // It's too cold, so it will snow instead.
    } else {
      isRaining = rainStatus;
    }
  }

  public boolean willItSnow() {
    return temperature < 0 && !isRaining;
  }

  public int getTemperature() {
    return temperature;
  }

  public boolean getIsRaining() {
    return isRaining;
  }
}",

