class SalesReport:
    def __init__(self, sales_data):
        self.sales_data = sales_data

    def total_sales(self):
        return sum(self.sales_data)

    def apply_discount(self, percentage):
        return [s * (1 - percentage/100) for s in self.sales_data]

    def predict_next_month_sales(self, increase_factor):
        return sum(self.sales_data) * (1 + increase_factor/100)

report = SalesReport([100, 150, 200])
final_sales = report.apply_discount(10)
predicted_sales = report.predict_next_month_sales(5)",

