            speed = 'fast'
        else:
            priority = 'normal'
            speed = 'normal'
    elif task_type == 'calculation':
        memory_used = 'low'
        if urgent:
            priority = 'high'
            speed = 'fast'
        else:
            priority = 'low'
            speed = 'slow'
    return {'memory': memory_used, 'priority': priority, 'speed': speed}",

