def update_inventory(items, purchases, returns):
    for purchase in purchases:
        if purchase in items:
            items[purchase] += 1
        else:
            items[purchase] = 1
    for return_item in returns:
        if return_item in items and items[return_item] > 0:
            items[return_item] -= 1
    return items

inventory = {'apples': 10, 'oranges': 5}
purchases = ['apples', 'bananas', 'bananas']
returns = ['oranges', 'bananas']
updated_inventory = update_inventory(inventory, purchases, returns)",

