def adjust_temperature(sensor, desired_temp):
    current_temp = get_reading(sensor)
    heater_on = False
    if current_temp < desired_temp - 5:
        heater_on = True
        increase_temperature(desired_temp - current_temp)
    elif current_temp > desired_temp + 5:
        decrease_temperature(current_temp - desired_temp)
    return heater_on",

