class HealthCareSystem {
  private boolean hasInsurance;
  private int age;
  private boolean hasChronicDiseases;

  public HealthCareSystem(boolean insurance, int age, boolean chronic) {
    this.hasInsurance = insurance;
    this.age = age;
    this.hasChronicDiseases = chronic;
  }

  public boolean canAccessAdvancedTreatment() {
    if (this.hasInsurance && this.age > 65 && this.hasChronicDiseases) {
      return true;
    }
    return false;
  }

  public boolean checkEligibility() {
    if (this.age > 65) {
      return hasInsurance && canAccessAdvancedTreatment();
    }
    return false;
  }
}",

