class ShoppingList {
public:
    int apples;
    int oranges;
    int bananas;

    ShoppingList() : apples(0), oranges(0), bananas(0) {}

    void addFruit(int a, int o, int b) {
        apples += a;
        oranges += o;
        bananas += b;
    }

    void removeFruit(int a, int o, int b) {
        if(apples >= a) apples -= a;
        if(oranges >= o) oranges -= o;
        if(bananas >= b) bananas -= b;
    }

    int getTotalFruits() const {
        return apples + oranges + bananas;
    }
};
",

