class SalesReport:
    def __init__(self, sales_data):
        self.sales_data = sales_data

    def total_sales(self):
        return sum(self.sales_data)

    def apply_discount(self, percentage):
        self.sales_data = [sale * (1 - percentage / 100) for sale in self.sales_data]

report = SalesReport([100, 200, 300])
original_total = report.total_sales()
report.apply_discount(10)
discounted_total = report.total_sales()",

