import random

class HealthSystem:
    def __init__(self, initial_health=100):
        self.health = initial_health

    def consume_food(self, food_type):
        if food_type == "healthy":
            self.health += 20
        elif food_type == "junk":
            self.health -= 15

    def exercise(self, duration):
        if duration > 30:
            self.health += 5 * (duration // 30)
        else:
            self.health -= 10

class Person:
    def __init__(self, name):
        self.name = name
        self.health_system = HealthSystem()

    def live_one_day(self, food, exercise_time):
        self.health_system.consume_food(food)
        self.health_system.exercise(exercise_time)
        return self.health_system.health
""",

