    def exercise(self, duration):
        if duration > 30:
            self.health += 5 * (duration // 30)
        else:
            self.health -= 10

class Person:
    def __init__(self, name):
        self.name = name
        self.health_system = HealthSystem()

    def live_one_day(self, food, exercise_time):
        self.health_system.consume_food(food)
        self.health_system.exercise(exercise_time)
        return self.health_system.health
""",

def update_inventory(inventory, purchase_orders, sales_orders):
    for item, quantity in purchase_orders.items():
        if item in inventory:
            inventory[item] += quantity
        else:
            inventory[item] = quantity

    for item, quantity in sales_orders.items():
        if item in inventory and inventory[item] >= quantity:
            inventory[item] -= quantity
        elif item in inventory and inventory[item] < quantity:
            inventory[item] = 0
            print(f'Not enough stock for {item}.')
    return inventory",

