def update_prices(prices, demand, discount_flag):
    adjusted_prices = {}
    for item, price in prices.items():
        if demand[item] > 100:
            if discount_flag:
                adjusted_prices[item] = price * 0.9
            else:
                adjusted_prices[item] = price * 1.05
        else:
            adjusted_prices[item] = price
    return adjusted_prices",

