def calculate_score(temperature, humidity, season):
    if season == 'summer':
        base_score = 20
    elif season == 'winter':
        base_score = 30
    else:
        base_score = 25

    if temperature > 75:
        temperature_score = 5
    else:
        temperature_score = 3

    if humidity > 50:
        humidity_score = 10
    else:
        humidity_score = 8

    final_score = base_score + temperature_score + humidity_score
    return final_score",

