\t}
\tincreaseTemperature(delta) {
\t\tthis.temperature += delta;
\t\tif (this.temperature > 30) {
\t\t\tthis.isRaining = true; // Heat can cause evaporation leading to rain
\t\t} else if (this.temperature < 10) {
\t\t\tthis.isRaining = false; // Less heat, less evaporation
\t\t}
\t}
\tdecreaseTemperature(delta) {
\t\tthis.temperature -= delta;
\t\tif (this.temperature < 10) {
\t\t\tthis.isRaining = false; // Cold conditions, less evaporation
\t\t} else if (this.temperature > 30) {
\t\t\tthis.isRaining = true; // High heat, more evaporation
\t\t}
\t}
\tsetRainStatus(status) {
\t\tthis.isRaining = status;
\t}
}",

