def check_health(system_status, error_logs):
    if system_status == 'good' and not error_logs:
        return 'System is healthy'
    elif system_status == 'good' and error_logs:
        return 'Check logs for warnings'
    elif system_status == 'bad' and error_logs:
        return 'System failure imminent'
