class HealthMonitor:
    def __init__(self, age, baseline_heart_rate):
        self.age = age
        self.heart_rate = baseline_heart_rate
        self.exercise_level = 0

    def update_heart_rate_on_exercise(self, increase_rate):
        self.heart_rate += increase_rate * self.exercise_level

    def start_exercise(self, level):
        if level >= 1 and level <= 10:
            self.exercise_level = level
        else:
            self.exercise_level = 0
