class HealthMonitor {
    private int heartRate;
    private boolean isSleeping;

    public HealthMonitor(int hr, boolean sleep) {
      this.heartRate = hr;
      this.isSleeping = sleep;
    }

    public void updateHeartRate(int hr) {
      if (isSleeping && hr < 50) {
        heartRate = 50;
      } else {
        heartRate = hr;
      }
    }

    public int getHeartRate() {
        return heartRate;
    }

    public boolean isUserSleeping() {
        return isSleeping;
    }

    public void userHasWokenUp() {
        isSleeping = false;
        if (heartRate < 60) {
            heartRate = 60;
        }
    }
}",

class HealthMonitor {
