class Graph:
    def __init__(self, nodes):
        self.nodes = nodes
        self.adjacency_list = {}
        for node in nodes:
            self.adjacency_list[node] = []

    def add_edge(self, start, end):
        self.adjacency_list[start].append(end)
        self.adjacency_list[end].append(start)

    def has_path(self, start, end, visited=None):
        if visited is None:
            visited = set()
        visited.add(start)
        if start == end:
            return True
        for neighbor in self.adjacency_list[start]:
            if neighbor not in visited:
                if self.has_path(neighbor, end, visited):
                    return True
        return False

g = Graph(['A', 'B', 'C', 'D'])
g.add_edge('A', 'B')
g.add_edge('B', 'C')
g.add_edge('C', 'D')
g.has_path('A', 'D')",

