def calculate_discount(cart_items, promo_code): 
    total = sum(item['price'] * item['quantity'] for item in cart_items) 
    discount = 0 
    if promo_code == 'SAVE10': 
        discount = total * 0.10 
    elif promo_code == 'SAVE20': 
        discount = total * 0.20 
    net_price = total - discount 
    return net_price",

