def administer_medication(age, symptoms):
    if age > 50 and 'cough' in symptoms:
        medication = 'DrugA'
    elif age <= 50 and 'fever' in symptoms:
        medication = 'DrugB'
    else:
        medication = 'DrugC'
    effects = ['none']
    if medication == 'DrugA':
        effects = ['drowsiness', 'nausea']
    elif medication == 'DrugB':
        effects = ['rash', 'headache']
    return medication, effects",

