class Car:
    def __init__(self, max_speed, fuel_level):
        self.max_speed = max_speed
        self.fuel_level = fuel_level
    def drive(self):
        if self.fuel_level > 0:
            self.fuel_level -= 10
            return 'Driving'
        else:
            return 'No Fuel'
    def refuel(self, amount):
        self.fuel_level += amount
        return f'Fuel level: {self.fuel_level}'
