class SalesReport:
    def __init__(self, sales_data):
        self.sales_data = sales_data
    def total_sales(self):
        return sum(self.sales_data)
    def apply_discount(self, discount):
        self.sales_data = [sale * (1 - discount) for sale in self.sales_data]
    def predict_future_sales(self, growth_rate):
        future_sales = sum(self.sales_data) * (1 + growth_rate)
        return future_sales",

