def process_data(input_data):
    temperature = input_data['temp']
    humidity = input_data['humidity']
    adjusted_temp = temperature * 1.8 + 32
    comfort_index = adjusted_temp - humidity
    if humidity > 50:
        risk_of_mold = True
    else:
        risk_of_mold = False
    return {'adjusted_temp': adjusted_temp, 'comfort_index': comfort_index, 'risk_of_mold': risk_of_mold}",

