def calculate_discount(prices, season, coupon_code):
    if season == 'Summer':
        discount_rate = 0.1
    elif season == 'Winter':
        discount_rate = 0.2
    else:
        discount_rate = 0.05

    if coupon_code:
        extra_discount = 0.05
    else:
        extra_discount = 0.0

    final_prices = [price * (1 - (discount_rate + extra_discount)) for price in prices]
    return final_prices",

