class HealthSystem:
    def __init__(self, num_doctors):
        self.num_doctors = num_doctors
        self.patients = []

    def add_patient(self, patient):
        self.patients.append(patient)
        if len(self.patients) > 50:
            self.increase_staff()

    def increase_staff(self):
        self.num_doctors += 1

    def treat_patient(self):
        healed = False
        if self.num_doctors > 1 and len(self.patients) > 0:
            self.patients.pop(0)
            healed = True
        return healed

    def manage_resources(self):
        if len(self.patients) < 30:
            self.num_doctors -= 1 if self.num_doctors > 1 else 0
