        self.diet = "poor"
        self.health_status = "poor"

    def exercise(self):
        self.has_exercise = True
        self.update_health_status()

    def eat_healthy(self):
        self.diet = "healthy"
        self.update_health_status()

    def update_health_status(self):
        if self.has_exercise and self.diet == "healthy":
            self.health_status = "good"
        elif self.has_exercise or self.diet == "healthy":
            self.health_status = "average"
