    "code": """"
class Worker:
    def __init__(self, name, workload):
        self.name = name
        self.workload = workload
        self.productivity = 100

    def complete_task(self):
        if self.workload > 0:
            self.workload -= 1
            self.productivity += 5

    def add_task(self, number):
        self.workload += number
        self.productivity -= number * 2

    def apply_overtime(self):
        if self.workload > 3:
            self.productivity += 20
            self.complete_task()

class Company:
    def __init__(self, name):
        self.name = name
        self.profit = 0
        self.workers = []

    def add_worker(self, worker):
        self.workers.append(worker)

    def calculate_profit(self):
        for worker in self.workers:
            self.profit += worker.workload * 50

    def month_end(self):
        for worker in self.workers:
            for _ in range(worker.workload):
                worker.complete_task()
            self.calculate_profit()
""""
