class InventoryManager:
    def __init__(self, stock_level):
        self.stock_level = stock_level

    def order_stock(self, additional_stock):
        if additional_stock > 0:
            self.stock_level += additional_stock
            self.notify_supplier(additional_stock)

    def notify_supplier(self, ordered_amount):
        print(f'Ordered {ordered_amount} units from supplier.')

    def sale_processed(self, units_sold):
        if units_sold <= self.stock_level:
            self.stock_level -= units_sold
        else:
            print('Not enough stock.')",

