class WeatherSystem {
    int temperature;
    float humidity;
    boolean isRaining;
    boolean isSnowing;

    WeatherSystem(int temperature, float humidity) {
        this.temperature = temperature;
        this.humidity = humidity;
        this.isRaining = false;
        this.isSnowing = false;
        updateWeatherCondition();
    }

    void updateWeatherCondition() {
        if (temperature < 0) {
            isSnowing = true;
            isRaining = false;
        } else if (humidity > 80) {
            isRaining = true;
            isSnowing = false;
        }
    }
}
",

