class ManageInventory { 
 public:  
     int itemsInStock, itemsSold;  
     double pricePerItem;  
     ManageInventory(int stock, double price) : itemsInStock(stock), pricePerItem(price), itemsSold(0) {}  

     void sellItem(){  
         if(itemsInStock > 0) {  
             itemsInStock--;  
             itemsSold++;  
         }  
     }  
     double revenueGenerated() {  
         return itemsSold * pricePerItem;  
     }  
 };",

