class SalesPredictor:
  def __init__(self, base_sales, advertising_budget):
    self.base_sales = base_sales
    self.advertising_budget = advertising_budget

  def predict_sales(self):
    advertising_effect = self.advertising_budget * 0.5
    seasonal_effect = self.detect_season_effect()
    return self.base_sales + advertising_effect + seasonal_effect

  def detect_season_effect(self):
    current_month = self.get_current_month()
    if current_month in ['December', 'November', 'October']:
      return 100
    elif current_month in ['June', 'July', 'August']:
      return 50
    else:
      return 20

  def get_current_month(self):
    from datetime import datetime
    return datetime.now().strftime('%B')",

