class WeatherSimulation:
    def __init__(self, temperature, humidity):
        self.temperature = temperature
        self.humidity = humidity

    def feels_like(self):
        adjustment = 0
        if self.humidity > 70:
            adjustment = 5
        elif self.humidity < 30:
            adjustment = -3
        return self.temperature + adjustment

    def is_rainy(self):
        if self.temperature < 15 and self.humidity > 80:
            return True
        return False
