class OfficeEnvironment: 
 def __init__(self, initial_temp): 
  self.temperature = initial_temp 
  self.employee_comfort = self.calculate_comfort() 
  self.productivity = self.calculate_productivity()

 def calculate_comfort(self): 
  return max(0, min(100, 100 - abs(self.temperature - 22) * 5)) 

 def calculate_productivity(self): 
  if self.employee_comfort > 80: 
   return min(100, self.employee_comfort + 10) 
  else: 
   return max(0, self.employee_comfort - 10)",

