  class CommunicationSystem:
      def __init__(self):
          self.messages = []
          self.is_active = True

      def receive_message(self, message):
          if self.is_active:
              self.messages.append(message)
              self.has_unread_messages = True

      def send_message(self, recipient, message):
          if self.is_active:
              recipient.receive_message(message)

      def activate_system(self):
          self.is_active = True

      def deactivate_system(self):
          self.is_active = False
          self.has_unread_messages = False

  class User:
      def __init__(self, name, system):
          self.name = name
          self.system = system

      def send_message(self, recipient, message):
          self.system.send_message(recipient, message)

      def read_messages(self):
          if self.system.has_unread_messages:
              self.system.has_unread_messages = False
              return self.system.messages
          return []

  # Example usage
  system = CommunicationSystem()
  alice = User("Alice", system)
  bob = User("Bob", system)
  alice.send_message(bob, "Hello Bob")
