    # This code snippet models a simple ecosystem
    class Ecosystem:
        def __init__(self, initial_sunlight, initial_water):
            self.sunlight = initial_sunlight
            self.water = initial_water
            self.plant_growth = 0

        def update_environment(self, new_sunlight, new_water):
            self.sunlight = new_sunlight
            self.water = new_water

        def photosynthesis(self):
            if self.sunlight >= 5 and self.water >= 3:
                self.plant_growth += 1
            elif self.sunlight < 5 or self.water < 3:
                self.plant_growth -= 1

        def simulate_day(self, add_sunlight, add_water):
            self.update_environment(self.sunlight + add_sunlight, self.water + add_water)
            self.photosynthesis()

    # Example invocation
    my_ecosystem = Ecosystem(5, 4)
    my_ecosystem.simulate_day(1, -2)  # Adding 1 sunlight and reducing water by 2
    """
