    class Store:
        def __init__(self):
            self.inventory = {"apples": 20, "bananas": 30}
            self.balance = 1000

        def sell_item(self, item, quantity, price_per_unit):
            if item in self.inventory and self.inventory[item] >= quantity:
                self.inventory[item] -= quantity
                self.balance += price_per_unit * quantity
                return True
            return False

        def restock(self, item, quantity, cost_per_unit):
            if self.balance >= cost_per_unit * quantity:
                if item in self.inventory:
                    self.inventory[item] += quantity
                else:
                    self.inventory[item] = quantity
                self.balance -= cost_per_unit * quantity
                return True
            return False
    `,

