class WeatherSystem {
\
    private int temperature;
\
    private boolean isRaining;
\
    public WeatherSystem(int temp, boolean rain) {
\
        temperature = temp;
\
        isRaining = rain;
\
    }
\
    public void changeWeather(int newTemp, boolean newRain) {
\
        temperature = newTemp;
\
        isRaining = newRain;
\
    }
\
    public boolean willSnow() {
\
        return temperature < 32 && isRaining;
\
    }
\
    public String currentWeather() {
\
        if (temperature < 32 && isRaining) return "Snowy";
\
        else if (isRaining) return "Rainy";
\
        else return "Clear";
\
    }
\
}",

