import random

sales = {'winter': 300, 'spring': 500, 'summer': 700, 'autumn': 400}
weather_impact = {'winter': 0.8, 'spring': 1.1, 'summer': 1.2, 'autumn': 1.0}
def forecast_sales(season):
    base_sales = sales[season]
    weather_factor = weather_impact[season]
    final_sales = base_sales * weather_factor
    if random.random() > 0.5:
        final_sales += 100  # Promotional boost
    else:
        final_sales -= 50  # Limited stock impact
    return final_sales

forecasted_values = {season: forecast_sales(season) for season in sales}",

