class EnvironmentController:
    def __init__(self, temp, humidity):
        self.temp = temp
        self.humidity = humidity

    def adjust_temp(self, change):
        self.temp += change
        if self.temp > 25:
            self.temp = 25
        elif self.temp < 18:
            self.temp = 18

    def adjust_humidity(self, change):
        self.humidity += change
        if self.humidity > 50:
            self.humidity = 50
        elif self.humidity < 30:
            self.humidity = 30

    def status(self):
        print(f'Temperature: {self.temp}, Humidity: {self.humidity}')",

