class HealthMonitor:
    def __init__(self, age, weight, height):
        self.age = age
        self.weight = weight
        self.height = height
        self.bmi = self.calculate_bmi()
        self.risk_level = self.assess_risk()

    def calculate_bmi(self):
        return self.weight / ((self.height/100) ** 2)

    def assess_risk(self):
        if self.bmi >= 30:
            return 'High'
        elif self.bmi >= 25:
            return 'Medium'
        else:
            return 'Low'

# Example Usage
person = HealthMonitor(age=28, weight=85, height=175)",

