class HealthSystem {
  int age;
  boolean smoker;
  double healthScore;

  HealthSystem(int age, boolean smoker) {
    this.age = age;
    this.smoker = smoker;
    this.healthScore = calculateHealthScore();
  }

  private double calculateHealthScore() {
    double baseScore = 100;
    if (smoker) baseScore -= 20;
    baseScore -= age * 0.5;
    return baseScore;
  }

  void updateAgeAndSmokingStatus(int newAge, boolean isSmoker) {
    this.age = newAge;
    this.smoker = isSmoker;
    this.healthScore = calculateHealthScore();
  }
}",

