def update_stock(item_purchased, current_stock, purchase_history):
    # Update the item count in stock
    if item_purchased in current_stock:
        current_stock[item_purchased] -= 1
    # Record the purchase
    if item_purchased not in purchase_history:
        purchase_history[item_purchased] = 1
    else:
        purchase_history[item_purchased] += 1

    return current_stock, purchase_history",

