class Product:
    def __init__(self, price, quantity):
        self.price = price
        self.quantity = quantity

    def update_price(self, new_price):
        self.price = new_price

    def apply_discount(self, percentage):
        self.price *= (1 - percentage)

    def increase_stock(self, additional_units):
        self.quantity += additional_units

class SalesReport:
    def __init__(self, product):
        self.product = product

    def generate_report(self):
        revenue = self.product.price * self.product.quantity
        return f'Total Revenue: ${revenue:.2f}'

# Example Usage
shampoo = Product(10.0, 50)
report = SalesReport(shampoo)
