def calculate_health_score(age, diet_quality, exercise_frequency):
    base_score = 100

    if age > 50:
        base_score -= 20
    else:
        base_score -= 10

    if diet_quality.lower() == 'poor':
        base_score -= 30
    elif diet_quality.lower() == 'average':
        base_score -= 15
    else:
        base_score += 10

    if exercise_frequency > 3:
        base_score += 20
    elif exercise_frequency == 0:
        base_score -= 20

    return base_score
