    base_sales = 100
    if season == 'high':
        seasonal_multiplier = 1.5
    elif season == 'low':
        seasonal_multiplier = 0.75
    else:
        seasonal_multiplier = 1.0
    total_sales = base_sales * seasonal_multiplier + ad_budget * 0.3
    return total_sales",

