class SalesReport {
    int discountRate = 10;
    double price = 150.0;
    boolean hasPromotion = false;

    double calculateFinalPrice() {
        if (hasPromotion) {
            return price * (1 - discountRate / 100.0);
        }
        return price;
    }

    void setPromotion(boolean status) {
        hasPromotion = status;
    }

    void updatePrice(double newPrice) {
        price = newPrice;
    }
}",

