        status = 'drought'
    elif temperature < 0 and rainfall > 50:
        status = 'flood'
    else:
        status = 'normal'
    return status

def send_alert(status):
    if status == 'drought':
        alert_sent = True
    elif status == 'flood':
        alert_sent = True
    else:
