def process_sales_data(prices, discounts, region):
    if region == 'west':
        tax_rate = 0.07
    else:
        tax_rate = 0.05
    discounted_prices = [p - (p * d) for p, d in zip(prices, discounts)]
    final_prices = [dp * (1 + tax_rate) for dp in discounted_prices]
    total_sales = sum(final_prices)
    return total_sales",

