class Store:
    def __init__(self, items, sales):
        self.items = items
        self.sales = sales

    def update_sales(self, item, percent):
        if item in self.items:
            self.sales[item] *= (1 + percent/100)

    def check_item_stock(self, item):
        return self.items.get(item, 0)

    def add_stock(self, item, quantity):
        if item in self.items:
            self.items[item] += quantity
        else:
            self.items[item] = quantity

    def sale_event(self, discount):
        for item in self.items:
            self.update_sales(item, discount)

items = {'shoes': 50, 'shirts': 100}
sales = {'shoes': 500, 'shirts': 800}
my_store = Store(items, sales)
sale_percentage = 10
my_store.sale_event(sale_percentage)
my_store.add_stock('shoes', 10)
shoe_sales = my_store.check_item_stock('shoes')
