# Python program to simulate demand-supply market dynamics

import random

class Market:
    def __init__(self, base_demand, base_supply):
        self.base_demand = base_demand
        self.base_supply = base_supply

    def fluctuate_demand(self, change):
        self.base_demand += change

    def fluctuate_supply(self, change):
        self.base_supply += change

    def market_price(self):
        if self.base_supply > self.base_demand:
            price = (self.base_demand / self.base_supply) * 100
        else:
            price = (self.base_supply / self.base_demand) * 100
        return price

    def simulate_day(self):
        demand_change = random.randint(-10, 10)
        supply_change = random.randint(-10, 10)
        self.fluctuate_demand(demand_change)
        self.fluctuate_supply(supply_change)
        return self.market_price()

market_instance = Market(100, 120)
price_today = market_instance.simulate_day()
""",

