def ecosystem_model(predators, prey, resources):
    if resources > 50:
        prey_growth_rate = 0.1
    else:
        prey_growth_rate = 0.02

    prey += prey * prey_growth_rate
    predator_consumption_rate = 0.05 * predators

    if predators > 30:
        predator_death_rate = 0.1
    else:
        predator_death_rate = 0.02

    resources_consumed = predators * predator_consumption_rate
    resources -= resources_consumed
    predators -= predators * predator_death_rate
    predators += 0.02 * prey
    return predators, prey, resources",

