class HealthTracker {
  constructor() {
    this.calorieIntake = 0;
    this.waterIntake = 0;
    this.sleepHours = 0;
    this.stepCount = 0;
  }

  logCalories(amount) {
    this.calorieIntake += amount;
    if (this.calorieIntake > 2500) {
      this.feelTired = true;
    }
  }

  logWaterIntake(liters) {
    this.waterIntake += liters;
    if (this.waterIntake < 2) {
      this.feelDehydrated = true;
    } else {
      this.feelDehydrated = false;
    }
  }

  logSleep(hours) {
    this.sleepHours += hours;
    if (this.sleepHours < 7) {
      this.feelRested = false;
    } else {
      this.feelRested = true;
    }
  }

  logSteps(steps) {
    this.stepCount += steps;
  }

  reset() {
    this.calorieIntake = 0;
    this.waterIntake = 0;
    this.sleepHours = 0;
    this.stepCount = 0;
    this.feelTired = false;
    this.feelDehydrated = false;
    this.feelRested = true;
  }
}
`,

