def process_sales_data(daily_sales, tax_rate, discount_policy):
    if discount_policy == 'holiday':
        discount_rate = 0.2
    else:
        discount_rate = 0
    total_sales = sum(daily_sales)
    if total_sales > 1000:
        discount_rate += 0.05
    tax_amount = total_sales * tax_rate
    discount_amount = total_sales * discount_rate
    final_amount = total_sales + tax_amount - discount_amount
    return final_amount",

