    class TemperatureController:
        def __init__(self, set_point):
            self.set_point = set_point
            self.current_temperature = 20  # Initial room temperature in degrees Celsius

        def heating_system(self, outdoor_temp, heater_on):
            if heater_on:
                self.current_temperature += 5  # Increase by 5 degrees if heater is on
            else:
                self.current_temperature -= 2  # Decrease by 2 degrees if heater is off
            self.current_temperature += outdoor_temp * 0.1  # Additional dependency on outdoor temperature

        def adjust_temperature(self, heater_control):
            self.heating_system(outdoor_temp=5, heater_on=heater_control)  # Outdoor temperature is fixed at 5 degrees for simplicity

        def check_status(self):
            return "Heating" if self.current_temperature < self.set_point else "Off"
    """
