class WeatherSimulator:
    def __init__(self):
        self.cloud_cover = 0
        self.temperature = 72  # default temperature in F

    def increase_temperature(self, increment):
        if self.cloud_cover < 50:
            self.temperature += increment
        else:
            self.temperature += (increment * 0.5)  # less effect when cloudy

    def change_cloud_cover(self, percentage):
        if 0 <= percentage <= 100:
            self.cloud_cover = percentage
        else:
            raise ValueError("Cloud cover must be between 0 and 100.")

    def is_rainy(self):
        return self.cloud_cover > 70 and self.temperature < 75

simulator = WeatherSimulator()
simulator.change_cloud_cover(80)
simulator.increase_temperature(5)
""",

