    class Store:
        def __init__(self):
            self.inventory = {'apples': 50, 'bananas': 75}
            self.sales = {'apples': 0, 'bananas': 0}

        def sell_item(self, item_name, quantity):
            if self.inventory[item_name] >= quantity:
                self.inventory[item_name] -= quantity
                self.sales[item_name] += quantity
                return True
            else:
                return False

        def restock_item(self, item_name, quantity):
            self.inventory[item_name] += quantity

        def report_sale(self, item_name):
            return self.sales[item_name]

        def check_inventory(self, item_name):
            return self.inventory[item_name]

