class AirPurifier():
    def __init__(self, is_on=False, filter_dirty=True):
        self.is_on = is_on
        self.filter_dirty = filter_dirty
    def turn_on(self):
        if not self.filter_dirty:
            self.is_on = True
        return self.is_on
    def clean_filter(self):
        self.filter_dirty = False
    def check_air_quality(self):
        if self.is_on and not self.filter_dirty:
            return 'Good'
        else:
            return 'Poor'",

