        if season == 'summer':
            self.temperature += 5
            self.humidity += 10
        elif season == 'winter':
            self.temperature -= 5
            self.humidity -= 10

    def is_snowing(self):
        if self.temperature < 0 and self.humidity > 30:
            return True
        return False
