    def __init__(self, initial_health):
        self.health = initial_health
        self.has_immunity = False

    def apply_medication(self, medicine_dose):
        if medicine_dose > 50:
            self.health += 20
            self.has_immunity = True
        else:
            self.health += 10

    def encounter_pathogen(self):
        if not self.has_immunity:
            self.health -= 30

system = HealthSystem(100)
system.apply_medication(60)
system.encounter_pathogen()",

def compute_values(temp, pressure):
    boiling_point = 100 + (pressure - 1) * 0.5
    if temp > boiling_point:
        state = 'Gas'
    elif temp == boiling_point:
        state = 'Transition'
    else:
        state = 'Liquid'
    return state",

