        self.current_temp = 70  # Default room temperature in Fahrenheit

    def adjust_temperature(self, external_factor):
        if external_factor == 'cold_wave':
            self.current_temp -= 10
        elif external_factor == 'heat_wave':
            self.current_temp += 10
        self.regulate_temp()

    def regulate_temp(self):
        if self.current_temp < self.desired_temp:
            self.heat_room()
        elif self.current_temp > self.desired_temp:
            self.cool_room()

    def heat_room(self):
        self.current_temp += 5

    def cool_room(self):
        self.current_temp -= 5",
