def compute_scores(data, bonus_factor): 
    total_score = 0 
    for record in data: 
        score = record['score'] 
        if record['type'] == 'A': 
            score *= 1.1 
        elif record['type'] == 'B': 
            score -= 2 
        total_score += score 
    total_score *= bonus_factor 
    return total_score",

