class SalesData {
  int basePrice = 100;
  int discountRate = 20;
  boolean hasDiscount = false;

  public void applyDiscount() {
    if (hasDiscount) {
      basePrice -= discountRate;
    }
  }

  public int finalPrice(int additionalFee) {
    applyDiscount();
    return basePrice + additionalFee;
  }
