class WeatherForecast {
    private int temperature;
    private boolean isRaining;

    public WeatherForecast(int temp, boolean rain) {
        this.temperature = temp;
        this.isRaining = rain;
    }

    public void updateWeather(int newTemp, boolean newRain) {
        this.temperature = newTemp;
        this.isRaining = newRain;
    }

    public boolean decideToCarryUmbrella() {
        if(this.temperature < 20 && this.isRaining) {
            return true;
        }
        return false;
    }
}",

