class WeatherSimulator {
    private int temperature;
    private boolean isRaining;

    public WeatherSimulator(int temperature, boolean isRaining) {
        this.temperature = temperature;
        this.isRaining = isRaining;
    }

    public void changeWeather(int newTemp, boolean newRainStatus) {
        this.temperature = newTemp;
        this.isRaining = newRainStatus;
    }

    public boolean willPeopleUseUmbrellas() {
        return isRaining && temperature < 25;
    }

    public String getWeatherStatus() {
        if (isRaining) {
            return temperature > 15 ? "Warm Rain" : "Cold Rain";
        } else {
            return temperature >= 20 ? "Sunny" : "Cloudy";
        }
    }
}",

