class Student: 
   def __init__(self, student_id, knowledge_level): 
       self.student_id = student_id 
       self.knowledge_level = knowledge_level 
       self.enrolled_courses = [] 
       self.grades = {} 

   def enroll_in_course(self, course): 
       if self.knowledge_level >= course.required_knowledge_level: 
           self.enrolled_courses.append(course) 

   def complete_course(self, course, grade): 
       self.grades[course.course_id] = grade 
       if grade >= 50: 
           self.knowledge_level += 20 



