class WeatherSimulator {
    int temperature;
    boolean raining;
    boolean useUmbrella;

    WeatherSimulator(int temperature, boolean raining) {
        this.temperature = temperature;
        this.raining = raining;
        this.useUmbrella = false;
    }

    boolean decideToUseUmbrella() {
        if (this.raining && this.temperature < 25) {
            this.useUmbrella = true;
        } else {
            this.useUmbrella = false;
        }
        return this.useUmbrella;
    }

    void changeWeather(int newTemperature, boolean isRaining) {
        this.temperature = newTemperature;
        this.raining = isRaining;
        decideToUseUmbrella();
    }
}",

