class HealthMonitor:
    def __init__(self, age, is_smoker):
        self.age = age
        self.is_smoker = is_smoker
        self.risk_level = 0

    def update_risk_level(self):
        if self.age > 50 or self.is_smoker:
            self.risk_level += 1
        if self.age > 60 and self.is_smoker:
            self.risk_level += 2

    def apply_medication(self, reduce_smoking):
        if reduce_smoking and self.is_smoker:
            self.is_smoker = False
            self.risk_level -= 1
        self.update_risk_level()",

