class WeatherSimulator {
  private int temperature;
  private boolean isRaining;
  private boolean umbrellaTaken;

  public WeatherSimulator() {
    temperature = 20; // Degrees Celsius
    isRaining = false;
    umbrellaTaken = false;
  }

  public void setTemperature(int temp) {
    temperature = temp;
    if (temperature < 18) {
      isRaining = true;
    } else {
      isRaining = false;
    }
  }

  public void setUmbrellaTaken(boolean taken) {
    umbrellaTaken = taken;
  }

  public boolean willGetWet() {
    return isRaining && !umbrellaTaken;
  }
}",

