import random

def weather_condition():
    conditions = ['sunny', 'rainy', 'cloudy']
    return random.choice(conditions)

def decide_to_travel():
    weather = weather_condition()
    if weather == 'sunny':
        travel = True
    else:
        travel = False
    return travel

def external_influence():
    forced_travel = random.choice([True, False])
    return forced_travel

def final_decision():
    natural_decision = decide_to_travel()
    influence = external_influence()
    if influence:
        return True
    else:
        return natural_decision",

