class Car:
    def __init__(self, model, year):
        self.model = model
        self.year = year
        self.speed = 0

    def accelerate(self, increment):
        self.speed += increment
        if self.speed > 120:
            self.speed = 120

    def brake(self, decrement):
        self.speed -= decrement
        if self.speed < 0:
            self.speed = 0",

