def calculate_scores(data): 
    summary = {} 
    for student, grades in data.items(): 
        average_grade = sum(grades) / len(grades) 
        if average_grade >= 90: 
            summary[student] = 'A' 
        elif average_grade >= 80: 
            summary[student] = 'B' 
        elif average_grade >= 70: 
            summary[student] = 'C' 
        else: 
            summary[student] = 'F' 
    return summary",

