class DrugResponseSimulator:
    def __init__(self, drug_dose):
        self.drug_dose = drug_dose

    def simulate_patient_response(self):
        base_health = 100
        if self.drug_dose > 50:
            return base_health - (self.drug_dose * 0.8)  # High dose reduces health
        else:
            return base_health - (self.drug_dose * 0.5)  # Low dose reduces health less intensely

simulator = DrugResponseSimulator(60)
patient_response = simulator.simulate_patient_response()",

