class WeatherPredictor:
    def __init__(self, temperature, humidity):
        self.temperature = temperature
        self.humidity = humidity

    def feels_like(self):
        adjusted_temp = self.temperature * 1.04 if self.humidity > 80 else self.temperature
        return adjusted_temp

    def possibility_of_rain(self):
        return 'High' if self.humidity > 70 else 'Low'
