class SalesData:
    def __init__(self, base_sales, marketing_spend, holiday):
        self.base_sales = base_sales
        self.marketing_spend = marketing_spend
        self.holiday = holiday

    def calculate_sales(self):
        if self.holiday:
            return self.base_sales * 1.5
        else:
            return self.base_sales + (self.marketing_spend * 0.2)

    def update_marketing(self, increment):
        self.marketing_spend += increment

sales_data = SalesData(1000, 200, False)
sales_data.update_marketing(300)
final_sales = sales_data.calculate_sales()
",

