class BookStore:
    def __init__(self):
        self.inventory = {'fiction': 100, 'nonfiction': 100, 'comics': 50}
        self.sales_record = {'fiction': 0, 'nonfiction': 0, 'comics': 0}
        self.discount_applied = []

    def sale(self, category, quantity):
        if self.inventory[category] >= quantity:
            self.inventory[category] -= quantity
            self.sales_record[category] += quantity
            if quantity > 10:
                self.apply_discount(category)

    def restock(self, category, quantity):
        self.inventory[category] += quantity

    def apply_discount(self, category):
        self.discount_applied.append(category)
""",

