class WeatherSimulator {
    private boolean isSunny;
    private boolean isWeekend;

    public WeatherSimulator() {
        isSunny = true; // Default sunny day
        isWeekend = false; // Default not weekend
    }

    public void setWeather(boolean sunny) {
        isSunny = sunny;
    }

    public void setDay(boolean weekend) {
        isWeekend = weekend;
    }

    public boolean willGoHiking() {
        return isSunny && isWeekend;
    }

    public boolean willGoShopping() {
        return !isSunny && isWeekend;
    }
}",

